UPDATE posts SET content = $tag2$<p class="has-text-align-justify">Medusa' nın ismini duymuşsunuzdur ya da laneti kulağınıza fısıldanmıştır. O gözlerine bakanı taşa çeviren kadın…</p>



<figure class="wp-block-image aligncenter size-medium is-style-default"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/05/IMG_20200210_123249-330x400.jpg" alt="Medusa, Gian Loranzo Bernini, 1644-1648" class="wp-image-1983"/><figcaption>Medusa, Gian Loranzo Bernini, 1644-1648<br></figcaption></figure>



<p>Kâinatın, Tanrılar tarafından bölüşüldüğü çağlarda, Medusa adında güzelliğiyle herkesi kıskandıran, aynı zamanda bütün tanrıları kendisine aşık eden bir kız yaşarmış. Medusa o kadar güzel bir kızmış ki yeryüzünde güzelliğiyle ona rakip olabilecek başka bir kadın bulmak mümkün değilmiş. Bu yüzden derlermiş ki; yeryüzünde bütün kadınlar bu güzelliği yüzünden Medusa'yı kıskanırmış. İşte bu güzel Medusa kendisini Tanrılara adamış ve iki kız kardeşi ile birlikte baş Tanrı Zeus'un en sevdiği kızı zekâ Tanrıçası Athena'ya ait bir tapınakta yaşarmış. Phorkus ve Keto'nun kızları olan bu üç kız kardeşten Medusa'nın haricinde diğer ikisi ölümsüzmüş. Kendi tapınağında yaşayan bu güzel kızı gören Athena da kızın güzelliğinden etkilenmiş ama kendisini daha güzel ve çok daha zeki bulduğu için de pek fazla önemsememiş. Athena, Baştanrı Zeus'un kardeşi olan denizlerin efendisi büyük Poseidon ile birlikteymiş. Güçlü ve ölümsüz, büyük Tanrı Poseidon da karısı Athena'nın tapınağında yaşayan bu güzeller güzeli kızın farkındaymış ama Tanrılar katında bir ölümlüye âşık olduğu için küçümsenmekten korktuğu için de gizliyormuş ona olan ilgisini. Bir gün Athena her şeyi ilen baş Tanrı Zeus'un izniyle öğrenmiş Poseidon'un, Medusa'ya karşı ilgisini. Poseidon bunu şiddetle reddetmiş ve Tanrıça Athena'ya da yeryüzü ve gökyüzünde ondan daha güzel ve alımlı hiçbir canlının olmadığı üzerine yeminler etmiş. Athena da Poseidon'un bu söylediklerine inanarak olayı çok fazla büyütmemiş. Poseidon Athena'ya öyle demiş demesine ancak yine de bir türlü çıkaramıyormuş aklından dünyalar güzeli Medusa'yı. Medusa tutkusu yüzünden Poseidon aklını kaçıracak gibi oluyormuş. Sonunda denizlerin büyük tanrısı bu tutkusuna yenik düşmüş ve bir gün gizlice girdiği sevgilisi Athena'nın tapınağında, güzeller güzeli Medusa'ya zorla sahip olmuş. Dünyalar güzeli Medusa harap bir halde tapınakta kalmaya devam ediyormuş ama bu olayı Athena'nın duyması da fazla zaman almamış.</p>



<figure class="wp-block-image aligncenter size-large is-resized is-style-default"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/05/medusa.jpg" alt="Perseus with the Head of Medusa, Benvenuto Cellini, 1545-1554" class="wp-image-1990" width="280" height="426"/><figcaption>    <em>Perseus with the Head of Medusa, Benvenuto Cellini, 1545-1554</em></figcaption></figure>



<p> Athena, güçlü Poseidon'un bu yaptığı karşısında kendisini aşağılanmış hissetmiş. Bu hissi önce derin bir kıskançlığa, sonra da büyük bir sinire dönüşmüş. Öyle hiddetlenmiş,öyle hiddetlenmiş ki Medusa'yı çok acı bir şekilde cezalandırmaya karar vermiş ve kendi kendine demiş ki "Öyle birden öldürmeyeceğim onu ve kardeşlerini, onlara da önce büyük acılar çektirmeliyim. Tıpkı benim çektiğim gibi."Ve bu sinirle Medusa ve kız kardeşlerini birer ifrite çevirivermiş. Dünyalar güzeli Medusa ve kız kardeşlerinin artık yüzleri o kadar çirkinmiş ki kimse bakmaya tahammül bile edemiyormuş. Medusa'nın gören herkesi bir mecnuna çeviren, en ufak bir yelde bile bütün telleri havalanan o güzelim saçlarının her bir teli bir yılana dönüşmüş. Bununla da yatışmayan Athena'nın siniri Medusa'ya yine de bakmaya çalışan herkesi o bakışların taşa çevirmesini sağlamış ve o da bunun üzerine dünyanın en kuzeyindeki Hyperborea'ya sürülmüş. Gel zaman git zaman Athena bu cezayla da yetinmemiş ve Medusa'yı öldürmek için Argos Kralı Akrisios'un kızı Danae'nin, Zeus'tan olma oğlu Perseus' la yani üvey kardeşiyle iş birliği yaparak Medusa'nın kafasını kesmeye karar vermiş. Perseus üvey kız kardeşinin bu isteğini hemen yerine getirerek ışıltılar saçıp insanların gözlerini kamaştıran keskin kılıcını savurduğu gibi zavallı Medusa'nın yılan saçlı kafasını bedeninden ayırıvermiş.</p>



<figure class="wp-block-image aligncenter size-large is-resized is-style-default"><img src="https://i2.wp.com/www.loveinartsz.com/wp-content/uploads/2020/05/Rubens_Medusa-scaled.jpeg?fit=1024%2C589&amp;ssl=1" alt="" class="wp-image-1984" width="479" height="275"/><figcaption><em>The Head of Medusa, Peter Paul Rubens, 1617-1618</em></figcaption></figure>



<p>İşte böyle anlatılıyor hikâye. Peki Athena, Medusa’yı lanetlerken suçlu olmadığını düşünmemiş miydi? Sanmam…</p>



<p>Tarihin tozlu raflarında bu hikâyeye defalarca tanık olduk. Tablolar, heykeller, kitaplar Medusa’ nın öldürülmesini defalarca tasvir etti. Tarih neden bir suça ortak oldu bilinmez fakat İtalyan Sanatçı Luciano Garbati, tarihin bu sorgulamasız tavrını tamamen yıktı. Medusa’nın elinde tuttuğu Perseus’un kafasıyla yepyeni bir hikâye yarattı. Bu heykele göre Medusa galip/ öldüren, Perseus ise öldürülen tarafta. Luciano Garbati’ nin 2008 yılında yaptığı bu heykel dünyada büyük bir ses getirmiş ve insanlar bu yeni Medusa’ yı daha da sevmişler.</p>



<div class="wp-block-jetpack-tiled-gallery aligncenter is-style-square"><div class="tiled-gallery__gallery"><div class="tiled-gallery__row columns-2"><div class="tiled-gallery__col"><figure class="tiled-gallery__item"><img alt="" data-height="1000" data-id="1986" data-link="https://www.loveinartsz.com/?attachment_id=1986#main" data-url="https://www.loveinartsz.com/wp-content/uploads/2020/05/medusa01.jpg" data-width="1500" src="https://i0.wp.com/www.loveinartsz.com/wp-content/uploads/2020/05/medusa01.jpg?ssl=1&amp;resize=1000%2C1000" data-amp-layout="responsive"/></figure></div><div class="tiled-gallery__col"><figure class="tiled-gallery__item"><img alt="" data-height="1000" data-id="1987" data-link="https://www.loveinartsz.com/?attachment_id=1987#main" data-url="https://www.loveinartsz.com/wp-content/uploads/2020/05/medusa02-1.jpg" data-width="1500" src="https://i0.wp.com/www.loveinartsz.com/wp-content/uploads/2020/05/medusa02-1.jpg?ssl=1&amp;resize=1000%2C1000" data-amp-layout="responsive"/></figure></div></div><div class="tiled-gallery__row columns-2"><div class="tiled-gallery__col"><figure class="tiled-gallery__item"><img alt="" data-height="1000" data-id="1985" data-link="https://www.loveinartsz.com/?attachment_id=1985#main" data-url="https://www.loveinartsz.com/wp-content/uploads/2020/05/medusa06.jpg" data-width="1500" src="https://i0.wp.com/www.loveinartsz.com/wp-content/uploads/2020/05/medusa06.jpg?ssl=1&amp;resize=1000%2C1000" data-amp-layout="responsive"/></figure></div><div class="tiled-gallery__col"><figure class="tiled-gallery__item"><img alt="" data-height="1000" data-id="1988" data-link="https://www.loveinartsz.com/?attachment_id=1988#main" data-url="https://www.loveinartsz.com/wp-content/uploads/2020/05/medusa04.jpg" data-width="1500" src="https://i0.wp.com/www.loveinartsz.com/wp-content/uploads/2020/05/medusa04.jpg?ssl=1&amp;resize=1000%2C1000" data-amp-layout="responsive"/></figure></div></div></div></div>



<p>Burada önemli Medusa’nın intikamı neden aldığıydı. Medusa istismara uğramıştı hem de gücün timsali tarafından. Ne yapabilirdi ki? Sadece bir ölümlüydü. Tecavüze uğramış olduğu yetmedi hemcinsi tarafından önce lanetlendi sonra öldürüldü. Sesini çıkartamadı, kimsenin gözünün içine bakamadı. Ömrünün sonuna kadar ondan kaçanlarla, onu öldürmeye çalışanlarla yaşadı. Tecavüz edildi ve öldürüldü ne tanıdık bir hikaye değil mi?</p>



<p class="has-small-font-size">Kaynak:<a href=" https://tr.wikipedia.org/wiki/Medusa"> https://tr.wikipedia.org/wiki/Medusa</a>     </p>



<p class="has-small-font-size">   <a href="https://www.lucianogarbati.com/medusa  ">https://www.lucianogarbati.com/medusa  </a>            </p>



