UPDATE posts SET content = $tag2$<figure class="wp-block-gallery has-nested-images columns-default is-cropped">
<figure class="wp-block-image size-large"><img src="https://i1.wp.com/www.loveinartsz.com/wp-content/uploads/2020/05/das-parfum-1.png?fit=1024%2C604&amp;ssl=1" alt="" class="wp-image-1768"/></figure>
</figure>



<blockquote class="wp-block-quote"><p>Ama kokudan kaçamıyorlardı. Çünkü koku, soluğun kardeşiydi.</p></blockquote>



<p class="has-text-align-justify">Alman yazar <a href="https://tr.wikipedia.org/wiki/Patrick_S%C3%BCskind" class="aioseop-link"><span class="has-inline-color has-vivid-cyan-blue-color">Patrick Süskind</span></a> 1985 yılında, orijinal adıyla "<a href="https://www.goodreads.com/book/show/1232658.Koku" class="aioseop-link"><span class="has-inline-color has-vivid-cyan-blue-color">Das Parfum</span></a>" adlı romanı yazarken, edebiyat dünyasında bu kadar büyük sükse yaratacağından haberdar mıydı, bilemiyoruz... "Koku" yazarın ilk romanıydı ve yayınlandığı günden itibaren çok uzun yıllar en çok satanlar listesini işgal etti. Bu roman başarısının yanı sıra, beraberinde getirdiği tartışmalarla da gündemden düşmedi. Peki neydi "bir katilin öyküsü"nün üzerine, övgülerin ve yergilerin bir parfüm misali püskürtülmesine sebep olan şey? Biz bugünkü yazımızda, işte bu ölümsüz eseri postmodernite üzerinden değerlendirmeye çalışacağız.</p>



<blockquote class="wp-block-quote"><p>On sekizinci yüzyılda Fransa’da, dahi ve iğrenç kişiler yönünden hiç de yoksul olmayan bu dönemin en dahi ve iğrenç kişilerden biri sayılması gereken bir adam yaşadı.</p></blockquote>



<p class="has-text-align-justify">Yıl 1738, yer Paris. Süskind bize daha ilk sayfalardan oyun oynamaya başlar. Postmodernist bir tutumla kurmaca/gerçek düzlemlerini iç içe örerek, ana karakteri tarihte gerçekten yaşamış “de Sade, Saint-Just, Fouché, Bonaparte vb. öbür 'dahi'lerle” karşılaştıran yazar, dönemin “en dahi ve en iğrenç kişilerinden biri sayılması gereken bir adam” olarak nitelendirdiği ana karakter Jean-Baptiste Grenouille ile bizi tanıştırır. Bu elbetteki "deha" kavramının bir ironisi ve ters-yüz edilmiş halidir.  Grenouille ilk olarak; sefalet, pislik ve bolca koku içerisinde bir balık tezgahında annesi tarafından çöpe atılmak suretiyle ölüme terk edilirken karşımıza çıkar. Ağlama sesinin fark edilmesiyle ölmekten kurtulan Grenouille'ın, bu dakikadan itibaren bir gelişim serüvenine tanık olacağız. Kurmaca/gerçek düzlemlerini iç içe örerek, Parodik anlatım tarzına ve yazıldığı çağda pek alışkın olmadığımız "ilahi" bir anlatıcıya sahip olan roman; bu noktadan itibaren postmodernizm paradigması olduğunu bize sezdirir.</p>



<figure class="wp-block-gallery has-nested-images columns-default is-cropped">
<figure class="wp-block-image size-large"><img src="https://i0.wp.com/www.loveinartsz.com/wp-content/uploads/2020/05/maxresdefault.jpg?fit=1024%2C576&amp;ssl=1" alt="" class="wp-image-1773"/></figure>
</figure>



<p class="has-text-align-justify">Grenouille yetimhanede büyür, gençlik döneminde tabakhanede çalışmaya başlar. Bu sırada Grenouille'ın koku duyusunun ne kadar gelişmiş olduğunu görürüz. Her şeyin kokusunu çok uzaklardan alır ve zihninde bir kokular kütüphanesi oluşturarak onun içinde yaşamaya başlar. Dünya artık, o sefil aklına göre sadece kokulardan ibarettir. İyi-kötü ayırt etmeksizin tüm kokuları içine çeker ve belleğine kazır. Daha sonra Paris'in ünlü parfümcülerinden birinin yanında çırak olarak işe kendini kabul ettirir ve üstün koku alma yeteneği sayesinde parfüm sanatını öğrenerek dünyanın en iyi kokularını yapmaya başlar. </p>



<figure class="wp-block-gallery has-nested-images columns-default is-cropped">
<figure class="wp-block-image size-large"><img src="https://i0.wp.com/www.loveinartsz.com/wp-content/uploads/2020/05/le-parfum-histoire-d-un-meurtrier-1.jpg?fit=1024%2C680&amp;ssl=1" alt="" class="wp-image-1775"/></figure>
</figure>



<p class="has-text-align-justify">İşte bu dakikadan itibaren romanı; Paris'in kirli ve pis kokulu caddelerinin ve parfümcülerinin tarihi yansıttığı için "tarih romanı", dönemin Fransa'sı üzerinden Avrupa yaşantısının sosyal gerçeklerini sunduğu için "sosyolojik roman", içerdiği ağır ironi ve dönem eleştirisi ile bir "parodi romanı", ana karakterin gelişimini ve yaşam öyküsünü anlattığı için "gelişim romanı", parfümcülük sanatını ayrıntılı bilgilerle sunduğu için "ansiklopedik roman"  kategorilerine girdiğini görürüz. İşte postmodernizmin nimetlerinden biri olan çoğulcu roman tipi... Grenouille, parfümcülük zanaatıyla ilgilenirken beraberinde birçok içsel çatışma yaşamaya başlamıştır. Öyle bir noktaya gelir ki "koku" onun için bir yaşama tutkusu haline gelir ve kokladığı en mükemmel kokunun peşinden giderek bir gece yarısı kırmızı saçlı bir kadını öldürür, kokusunu içine doya doya çeker ve oradan ayrılır.</p>



<figure class="wp-block-gallery has-nested-images columns-default is-cropped">
<figure class="wp-block-image size-large"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/05/koku-patrick-suskind-cover-1000x600-1.jpg" alt="" class="wp-image-1770"/></figure>
</figure>



<blockquote class="wp-block-quote"><p>Onu elde etmeliydi, sırf sahibi olmak için değil, yüreğinin dinginliği aşkına.</p></blockquote>



<p class="has-text-align-justify">Bu cinayet onun zihninde bakire kokularını damıtma ve şişelerde parfüm olarak hayata tekrar döndürme fikrini canlandırır. Bakire kızların kokularını almak için birbiri ardına tam 25 cinayet işler. Bu dakikadan itibaren birçok kategoriye soktuğumuz roman tüm bunlara ek olarak; işlenen cinayetlerle "cinayet romanı", katilin analiz edilmesiyle "dedektif romanı", halkın şeytanla özdeşleştirdiği katilin etrafa saldığı dehşetle "korku romanı", yalnızca bakire kurbanları hedefleyen katilin müstehcen betimlemeleriyle “erotik roman” kategorilerine dahil olur. Postmodern romandaki çoğulculuk ilkesi gücüne güç katmıştır. Ayrıca yazar; romantizm, coşkunluk, klasisizm, simgecilik ,gerçekçilik, doğalcılık, çöküş yazını gibi farklı akımlardan faydalanarak hem ciddi hem de eğlencelik bir roman yaratarak kimliğini ortaya koymuştur. Grenouille katil olarak her yerde aranırken inziva ve gezilerine başlar. Bu noktada roman; karakterin yaptığı gezilerle "gezi romanı" ve o geziler esnasında kurbağa, kene, örümcek, büyücü, şeytan, Mesih, melek gibi birçok grotesk dönüşüm geçiren ana figürüyle "fantastik roman" kategorilerine de girmeyi başarır. Ana karakter Grenouille'ın isminin Almancada "kurbağa" anlamına geldiğini söylememiz de de fayda var. Tüm bu ruhsal dramalar ve katilin psikolojik çözümlemeleriyle beraber romanın sonuna geldiğimizde katil olarak yakalanır ve ölüme mahkum edilir. Ancak Grenouille kolay pes etmez. </p>



<figure class="wp-block-gallery has-nested-images columns-default is-cropped">
<figure class="wp-block-image size-large"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/05/s-429aa42db13305c987ccb61a9b9550a35228d717.jpg" alt="" class="wp-image-1771"/></figure>
</figure>



<blockquote class="wp-block-quote has-text-align-left"><p>Bugüne kadar hep, büzülüp uzaklaşması gereken şeyin genel olarak dünya olduğunu sanmıştı. Oysa dünya değildi, insanlardı. Öyle görünüyordu ki dünyada, insanları boşalmış bir dünyada pekâlâ yaşanabilirdi.</p></blockquote>



<p class="has-text-align-justify">Bir mağaranın derinliklerinde 7 yıl boyunca inzivada geçirdiği süreçte  İçindeki tanrıyı öldürür ve kendini "tanrı" ilan etmiştir. Bu gaye ile dünyadaki kokuların en mükemmelini icat ederek parfümünü sürülür. Şehir meydanında onun çarmıha gerilmesini bekleyen kızgın halk kokuyu alır almaz ona adeta bir tanrı gibi tapar ve burada; kamuya açık bir alanda gerçekleşen idam sahnesindeki tüm hiyerarşik yapıların yetkesini bozan cinsel taşkınlık skandalı ve kitle psikolojisi olgularıyla "karnavalesk roman" türü karşmıza çıkar. Romanın en sonunda ise yarattığı mükemmel parfümün tamamını üstüne boşaltarak etrafındaki insanların kendine "olağanüstü bir sevgi" nedeniyle saldırmasını ve etlerinin kopartılıp yenmesini sağlayarak intihar eder.</p>



<figure class="wp-block-gallery has-nested-images columns-default is-cropped">
<figure class="wp-block-image size-large"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/05/96ea72c86f5305bac969f4b8d6ce9c90.png" alt="" class="wp-image-1772"/></figure>
</figure>



<p class="has-text-align-justify">Eleştirmenlerin bir kısmı, Süskind'i yakaladığı popülariteden dolayı olumsuz yönde eleştirir. Postmodern edebiyatın büyük kitleler tarafından popüler kültür haline getirilmesinin Süskind'in edebiyat anlayışındaki çatlaklardan dolayı meydana geldiğini düşünür. Onlara göre postmodern edebiyat genel kitleye hitap etmemelidir, popülarite yakalamamalıdır. Süskind'in romanının içerik olarak "hafif" kaldığını düşünürler. Ancak diğer taraftan da Süskind'in romanı yazarken, 16 farklı roman türünü ve 7 farklı yazın akımını ironi/parodi/pastiş teknikleriyle yapıbozuma uğratarak kullandığının; tek anlamlılığı, tek biçimciliği ve içerdiği karşıtlıklarıyla oluşturduğu bulanık romanı modernizmden pek çok noktada ayrılarak postmodernist yazının en yetkin örneklerinden birini sunduğunun altını çizen diğer eleştirmenlerde vardır. Bizler, hem biçem hem içerik düzleminde postmodern bir paradigma olan bu romanın kültleştiğini düşünüyoruz. Senaryoda özellikle Aydınlanma Çağı'na yönelttiği ironik eleştiri bombardımanı açısından büyük kayıplara uğradığı için, film izlenmeden önce romanın okunması gerektiği kanısındayız. Gelecek yazılarda görüşmek üzere...</p>



<p class="has-small-font-size"><em>Kaynakça</em>:</p>



<p class="has-small-font-size"><em>Kızıler, F. (2006). SÜSKİND’İN, POSTMODERN ANLATI EVRENİNDE BİR PARADİGMA OLARAK KÜLTLEŞEN ve SİNEMAYA UYARLANAN METNİ: DAS PARFUM. Atatürk Üniversitesi Sosyal Bilimler Enstitüsü Dergisi, 8(2), 33-47.</em></p>



<p class="has-small-font-size"><em>Bakhtin, Mikhail,(2001); Karnavaldan Romana, çev. C. Soydemir, Ayrıntı Yay., İstanbul.</em></p>



<p class="has-small-font-size"><em>Baudrillard, Jean, (1998); Kötülüğün Şeffaflığı, çev. : I. Ergüden, Ayrıntı Yay., İstanbul.</em></p>



<p class="has-small-font-size"><em>Ecevit, Yıldız, (Mart1999); ” Benim Adım Kırmızı’da Çoğulcu Estetik”, Varlık Dergisi, sayı 1098.</em></p>



