UPDATE posts SET content = $tag2$<p>Kadın. Her şeyden önce insandır. Uğruna şiirler yazılası, yollarına güller dökülesi denerek tarih boyunca romantikleştirilen varlık olduğu kadar ne yazık ki hor görülüp şiddeti hak ettiği gerekçesine sığınılan da odur. Annedir, kız kardeştir, teyzedir veyahut dışarda yanından geçtiğiniz elli kişiden biridir, kasada para üstünüzü verendir veya öğretmeninizdir, ülkenize tatil için gelen herhangi bir turisttir. Kadın, insandır kısaca. Yalnızca söylemsel tanımla sınırlı bir varlık değildir. Cinsiyeti kadın olanların yanı sıra, kendini kadın hissedenler de unutulmamalıdır ki insandır. Kadınlık kutsal olmak zorunda da değildir veya kadınlara ‘çiçek’ metaforu yapılmak zorunda değildir çünkü kadına saygı duymaktan ziyade ‘insan’ a saygı duymalı önce. Bunları idrak ettiğimizde ancak toplumumuz dönüşür çünkü insanı savunmasız bırakan şey da aslında ilk olarak toplumun görgüsüdür. Bunları bu sene içinde haysiyetsizce canları alınan 67 kadınımız, insanımız için hatırlatıyorum.</p>



<p>Hatice Soysal, Feride T., Merve Abasiyun, Selma Taşkömür, Kristina Noystka, Vildan İnce, Sevda Kösecik… yalnızca birkaçı ve belki kim bilir daha duymadıklarımız. </p>



<p>Anıt Sayaç için <a href="http://anitsayac.com/">http://anitsayac.com/</a></p>



<figure class="wp-block-image size-large"><img src="https://www.loveinartsz.com/wp-content/uploads/2021/03/women-nicole-wilson.jpg" alt="" class="wp-image-6759"/><figcaption>Nicole Wilson, Kadınlar</figcaption></figure>



<p>Kadınlar olarak biz, kendi günümüzde bile ahlaksızca şiddete uğramaya; kurban edilmeye devam ediliyoruz. Sebebi her ne olursa bizi katleden caninin; bize şiddet gösterenlerin sırtları sıvazlanmaya devam ediliyor o çok tanıdık laflarla “Erkeksin, yaparsın.”</p>



<p>Oysa biz, hayata renk katabilen; detaylarla ilgilenen, belki anaç ruhlu belki bunların tam tersi kişiliklerle varız, hayattayız. Bu satırları yazıyoruz, çocukları doğuruyoruz veya ülke yönetiyoruz. Etek giyeriz veya pantolon, saçımız kıvırcıktır veya düz; belki kapamışızdır veya ‘kız gibi’ bir saçımız yoktur kesmişizdir! Çünkü nasıl mutluysak öyle yapabiliriz. Duygusalızdır veya değilizdir kabaca ‘duygusuz biriyizdir’. Çünkü her insan başkadır. Fakat bunları yalnız tek bir cinsiyete atfetmek doğru olmaz. Bu kavramlar elbette cinsiyetsizdir. İşte normlar burada devreye giriyor. Çünkü normlara göre erkekler pembe giymez ve kadınlar da ‘erkek işi’ yapamaz öyle değil mi?</p>



<figure class="wp-block-image size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2021/03/maggie-cole-1.jpg" alt="" class="wp-image-6760" width="503" height="503"/><figcaption>Maggie Cole</figcaption></figure>



<p>Düşününce yerleşmiş bu kültürel sözlerdeki eşitsizliğin iki yüzlülüğü de ortaya çıkıyor. Erkekler pembe ‘giymez’ yani ‘giymemek tercihi’ bu yönde olmak ‘zorunda’ bırakılıyor. Erkeklere dayatılan şu saçma norma bakar mısınız?</p>



<p>Kadınlar ise, erkek işi ‘yapamaz’ yani ‘kadın başına’ yapabilme ihtimali yine var ama o erkek işidir. Geçmişte bir yaşam düşününce, bu kadının hayatında bir erkek olmamalı ki bunları yapabilme gücünü keşfetsin. Tabi bu lafların doğduğu ortamların şartlarıyla bunlar böyle kabul görmüş olacaktır ki günümüzde özellikle teknolojik imkanlarla birlikte çok fazla dönüşümün gerçekleştiği aşikârdır o halde bu laflar şu anda kabul edilemezdir. Yirmi birinci yüzyılda hala bunları konuşuyor olmak da cabası.</p>



<p>Günümüzde özellikle toplumsal konularda neden hala kadın ve erkek ayrımına girerek kutuplaşıyoruz? Silkelenip içinde büyütüldüğümüz bu normları fark etmeli, sosyal yaşamda çok daha bilinçli olmalıyız!</p>



<p>Şiddet bir insanlık suçudur, ve şiddetin rengi; cinsiyeti; sebebi yoktur.</p>



<p>Kadın cinayetlerinin son bulduğu daha eşitlikçi günlere umutla,</p>



<p>8 Mart dünya kadınlar günümüz kutlu olsun!</p>$tag2$ WHERE slug = 'sifatlara-sigmayan-bir-varlik-olarak-kadin';
UPDATE posts SET content = $tag2$<p class="has-drop-cap">Arthur Schopenhauer'in Ölüm Üzerine tahayyüllerinin esaslı bir özetini çıkarmak zor olsa da, ikinci yazımda bunun üzerinde çalışmaya devam edeceğim. <em>Schopenhauer'in Ölümü</em> dizisinin ilkinde, düşünürün fikirleri çerçevesinde ağırlıklı olarak yaşama iradesi kavramı üzerine konuşmuştuk ve bu iradenin bireyin zihninde yarattığı ölüm korkusunun yapaylığını anlatmıştık. Ölüm üzerine koyduğu düşüncelerde bireycilikten uzaklaşarak idealist bir çerçevede birey-tür, yani aslında fenomen-idea, ayrımı yaratan yazar; insan aklının kibirli fikirleri neticesinde zihinsel olarak bağını koparmaya çalıştığı doğanın illiyet zinciri dışında kalan biricik varlığının, tüm bireyler üzerindeki kapsayıcılığını yitirmediğini fakat daha çok türün, yani ideanın, sürekliliğini önemsediğini anlatır. Yani insan kendini diğer canlılardan farklı ve üstte görerek ayrıca ölümü bireysel adlederek doğanın gücünü ve ölümsüzlük fikrini anlayamaz. </p>



<p class="has-text-align-left">Yaşam, kendi içinde tözsel bir nitelik taşımasının yanısıra bu töz, sıkça öne sürüldüğü üzere, bilinç, zihin ya da ruh değildir; yaşamanın neticesinde ortaya çıkan bunlar yaşamanın tözü olamaz. Fani olanın illiyet zinciri içerisinde var olduğunu bildiğimizden dolayı bilincin kendisi de temelde bağımlı olarak ortaya çıkar, görünür ve kaybolur. Uyurken, baygınken, nöbet sırasında kaybolan bilinç, dolayısıyla hayatın nedeni ve göstereni değildir. Organik hayatın değişkenlerine göre farklılık gösteren bu bilinç, çeşitli şartlara kökten bağlı olarak görünmüştür. Bireysellik organik şeyleri niteler, eğer canlı kendinin farkında ise bireysellik bilinci de niteler. Buna mukabele, et parçasına hayat veren doğal gücün bireyselliğe atfedilmiş güce bağımlı olduğu sanrısına kapılmak bizim için büyük bir hatadır. Bireysellik bu gücün doğal bir parçası olarak ortaya çıkamaz. Mamafih, hayat verici gücün ölen bedenle birlikte yok olup gittiğini düşünmek bizi içinde keskin hatalar barındıran bir denkleme iter, dolayısıyla nedenlerin sonuçlarla yer değiştirdiği, bazen nedenselliğin dahi gözardı edildiği çarpık bir düşünsel temel üzerinde bulunmak yönümüzü kaybetmemize sebebiyet verecektir. Üstünde elektrik yükleri biriken bir cismin bu yükü boşaltması evrende elektrik gücünün tamamen yok olduğu anlamına gelemez, sadece bu cisimden çekilmiştir. Schopenhauer bu örneği verirken hayat verici gücün evrenin her yerinde her an bulunduğu ve tüm fenomenlere her an her yerde etki etmekte olduğunu belirtir. Elektrik metaforu onun düşünceleri için gerçekten de bulunmaz bir madendir. Bundan ötürü, hayat gücünün bedenden alınması insanın bütünüyle yok olduğu anlamına da gelmemelidir. 4000 yıl önce kılıç sallamış bir savaşçının bunu yapmasına vesile olan gücün tamamen ortadan kalktığını iddia edemeyiz ve hatta bunu bir adım ileri götürerek, gücün o savaşçıda ilk kez ortaya çıkıp daha sonradan kaybolduğu fikri de yine aynı derece sorunludur. Dolayısıyla, o kaslara eyleme gücü verenin günümüz her yerde aktif olan ve sürekli eyleme gücüne sahip doğallığın da bir parçası olduğunu kabul etmemiz gerekir; fani olan o bedendeki o andaki eyleme gücüdür. Fakat, fani olana atfettiğimiz illiyet zincirleri bu gücün doğallığını kapsamaz: değişimden etkilenmeden baki kalan madde ile tözü baki olan doğal güç tüm bu zincirin nedeni olduklarından dolayı bu ilişkilerin dışındadır. Her yerde sürekli bir yenileme ve yaratma biçiminde kendini gösteren bu doğa gücü, sebep ve sonuçların fenomenler üzerinde kıldığı yıkıcı değişim ve dönüşümlerinden ya hiç etkilenmez ya da asgari düzeyde etkilenir. Bu sebeple, insanın gerçek varlığının yok olmazlığı ortaya konabilir.</p>



<p>Paradoksal bir biçimde; sebep/sonuç tahakkümünün değiştirici ve yıkıcılığından azade olan madde, bize doğa gücünün sürekliliğinin de bir kanıtı olarak sunulabilir. Burada mevzubahis olan madde ise topraktır. Toprak sürekli olarak üretir, çoğaltır, yaratır. Fakat burada akıllara kaba bir maddenin, toprağın, insan yaşamının nasıl tözü olabileceği düşüncesi gelebilir. Toprak doğa için sınırsız bir dölyatağı konumundadır ve sürekli olarak hayat döngüsünü içinde devam ettirir. Şüphesiz ki böyle bir maddenin parçası olarak kalmak yok olup gitmek anlamına gelemez ve tam da bu yüzden, toprağa bağımlı olan tüm yaşam gibi, insan da içinden çıktığı bütüne geri dönecektir. Bir ağacın meyvesinin olgunlaşıp büyüdükten sonra dibine düşüp çürümesi ve ona tekrar gübre olarak karışması bunun için açıklayıcı bir örnek olabilir. Kimse o elmanın yok olup gittiğini söyleyemez çünkü içerisinde bulundurduğu vitaminler toprağa tekrar karıştı bir karınca bir solucan, bir miktop tarafından da tüketildi ve böylece onlara da karışmış oldu. Schopenhauer'in panteist tahayyülünün biricik yansıması olan bu paradigmadaki temel dayanak, doğanın bir ve bütün olarak kabul edilmesi ve içinden çıkan tüm varlıkların da onunla bağını öldükten sonra da devam ettirdiği fikridir. Maddeye, yani toprağa, süreklilik ve sonsuzluk atfedilmiştir. </p>



<p>Bir diğer mesele her şeyin ana kaynağı olan doğanın tüm yavrularına karşı takındığı kayıtsızlıktır. Öyle ki doğa, tüm canlıların yaşamını yardıma gelmek yerine ihtimaller evrenine terk ederek aslında bireyin ölümünün ya da hayatının bir kıymetinin olmadığını ileri sürer. Yolda yürürken ne kadar sıklıkla adım attığınıza bağlı olarak yerde bulunan böceklerin hayatta kalıp kalmayacağının belirleyicisi siz olursunuz, bilinçli olarak yapmadığınız her durumda bir böceği ezmek size sadece ihtimallerin belirleyicisi konumu verir. Aynı şekilde doğada bir arada bulunan zehirli ve zehirsiz mantarlardan hangisini yiyip öleceğinin ihtimali kişiyi çarpık bir küçük ihtimaller kaosuna iter. Yaşamın ve ölümün belirleyicisi ihtimallerdir ve bir parçası olduğumuz doğa genelde bu ihtimalleri değiştiren hiçbir şey yapmaz. Ağdaki balık, kartalın yukarıdan takip ettiği fare gibi tüm canlılar, ölüm ve yaşam arasındaki ihtimallerin kaotik dünyasında yapayalnızlardır. Dolayısıyla kör talihe, kötü şansa terk edilen canlıların bireysel olarak ölmesinin ya da yaşamasının doğada bir şeyler değiştirmeyeceği fikri ortaya çıkar. Fakat bu kayıtsızlığın ve umursamamazlığın yegane sebebi, bireylerin ölümünün sadece kendi sonsuz dölyatağına geri döneceğini düşündüğünden dolayıdır, yani aslında bireyin ölümü doğa için sadece ufak bir düşme şakasıdır; birey annesinin kucaklarına koşarak geri dönmüş olur. İnsan da kendi varlığının bilincinde olan bir canlı olarak, eğer bireysel ölüm konusunu doğanın onu gördüğü gibi görebilse şüphesiz ki ondan korkmazdı. Her saniye bir yerlerde ölüm ve doğum bir arada bulunuyor, doğa sürekli olarak çocuklarını çağırıyor ve yerlerine yenilerini gönderiyor.</p>



<p></p>$tag2$ WHERE slug = 'schopenhauerin-olumu-ii-icsel-sonsuzluk-uzerine';
UPDATE posts SET content = $tag2$<p>Adalet... Herkesin ihtiyacı olan su gibi, ekmek gibi bir kavram hayatımızda. Hakları yarıştırırken o mahkemelerde, kusurların, ihmalleri tartışırken ortaya çıkan bir sistem. Adalet. Peki siz hiç erkek adaleti denen bir kavram duydunuz mu?</p>



<p>Yüzyıllarca yıl hayatın her alanında erkekler hakimdi. Erkeklerin geliştirdiği kurumlar, sistemler ve kurallar tüm topluma ahkam kesiyor, uygulanıyordu. Son yüzyıllık süreçte kadınlar hayata daha fazla katılmaya başladı. Çalışmaya başladılar, kendilerine ait odalarını kendi emekleriyle kurup "Biz buradayız!" diye bağırmaya başladılar. Onlar bağırdıkça kafalar döndü o seslere. Bu kadın neyin kavgasını veriyorlardı?</p>



<p>O kadınlar eşitliğin kavgasını, insan olmanın ve onurlu yaşamanın kavgasını veriyorlardı. Hala veriyorlar. İşte seksenlerde bir kadının erkek adaleti içinde nasıl eriyip gittiğini anlatan bir kitap yazıldı.<a href="https://en.wikipedia.org/wiki/Pınar_Kür"> Pınar Kür'ün</a> Asılacak Kadın'ı.  Aynı Duygu Asena'nın Kadının Adı Yok'u gibi bir etki yaratmıştı edebiyat dünyasında. Yasaklandılar. Ama filmleri yapıldı. Yargılandılar. Ama ödüller aldılar. Kadınlara yaşatılanlara müstehcen dediler. Ama o eserlere denk gelen her insanda bir ışık yakıldı. Peki neler diyordu Asılacak Kadın da?</p>



<blockquote class="wp-block-quote"><p><strong><span style="color:#7e0909" class="has-inline-color">... baskıya karşı çıkmamak üzere yetiştirilmişti. Bilmiyordu baş kaldırılabileceğini; zorbalığı yaşamın doğal bir öğesi bellemişti. Bu baskıyı erkeklerin kurması, her bakımdan kurması da doğaldı onun için. Çünkü güçlü olan onlardı; hep başta olan, her şeye egemen olan.</span></strong></p></blockquote>



<div class="wp-block-image"><figure class="aligncenter size-large"><img src="https://www.loveinartsz.com/wp-content/uploads/2021/04/0000000064042-1.jpg" alt="Asılacak kadın" class="wp-image-7069"/></figure></div>



<p>Melek. Kocası Hüsrev Bey'i öldürmekten yargılanıyor. Hüsrev Bey nüfuzlu, zengin ve yaşlı bir adam. Melek ise gencecik, köylü bir kadın. Üç kişinin gözünden anlatılıyor roman. İlk göz yargıç Faik İrfan Elverir. Faik İrfan Bey kalemi kırıyor. Ceza belirlendi. İdam. Melek tepkisiz. Faik İrfan Bey'in yargıç olması gereken berrak zihni yok o mahkeme salonunda. Öğrenilmişlikler, kadınlara karşı oluşturulmuş o önyargılar. Her biri dolanıyor zihninde. Melek, ona göre yaşlı bir adamın parasını yemeye çalışan bir kahpe. Ama gerçekten öyle mi? Gerçi öyle olmasa bile o kalem kırıldı. Artık önemi kaldı mı?</p>



<p>İkinci göz Melek. Melek gibi bir köylü kızının konuşabileceği gibi yazmış yazar. Hiç noktalama işareti yok. Hiç dur durak yok. Çünkü Melek o mahkeme salonunda konuşamıyor. Anlatsa derdini ona kim inanır? Kim yaşadıklarına üzülür? Ailesi tarafından dahi kullanılacak ve üzerinden para kazanılacak bir meta gibi görülürke, kim ona bir insan gibi bakabilir? Bakmadılar. Melek, o ihtiyarın sapkınlıklarına meze oldu. Birileri buna alet oldu. Kimse bunun suç olduğunu düşünmedi. Kimse vicdanının sesini duymadı. Tek bir kişinin duydu. O da Yalçın'dı.</p>



<p>Üçüncü göz Yalçın. Evin genç delikanlısı. Melek'in içine düştüğü o iğrenç çukuru farkettiği an o pisliğe alet oldu. Evet, mahkeme salonunda "O öldürmedi, ben öldürdüm!" diye bağıran bu genç alet oldu. Üzerine bulaşan pisliğin kirini atmak mı istedi yoksa gerçekten bu rezillikten Melek'i kurtarmak mı istedi, ben tespit edemedim. Çünkü biliyorum ki bu toplumda insanlar birilerine yardım etmekten önce kendi vicdanlarını rahatlatmak için sadaka veriyorlar.</p>



<p>Yalçın tarafından işlenen cinayete kimse inanmak istemedi. Melek'in öldürdüğüne herkes o kadar inanmıştı ki koşulları duymak dahi istemediler. Toplumun yozlaşmış değerleri, kadını yönetilen bir eşya gibi gören o zihniyet ve erkek adaleti kalemi kırdı Melek için. Keşke yalnızca kurgu olsaydı bu roman ama maalesef bu olay Edirne' de yaşandı.</p>



<p>Kitabının etkileyiciliği kadar filminde de başarılı olan bir eser Asılacak Kadın. 1986 yapımı aynı isimle yayınlanan filmin başrolünde Müjde Ar yer alıyor. Kitapta bahsedilen Melek karakterinden daha olgun gözükse de başarıyla icra etmiş rolünü.</p>



<p>Kadının toplum içindeki yerine ve erkek adaletinin neden bu kadar dile geldiğini anlamanız için iyi bir eser. Okumanızı ve izlemenizi temenni ediyor, eşitlik ve adalet dolu günlerde buluşmayı diliyorum.</p>



<p></p>



