UPDATE posts SET content = $tag2$<p>İskandinav mitolojisi denilince akla ilk gelen karakter Marvel filmlerinin de etkisiyle Thor olmuştur. Loki ise Thor’un doyumsuz ve kıskanç kardeşi olarak tasvir edilmiştir.</p>



<p><a href="https://www.loveinartsz.com/mitoloji-tarih/">Mitoloji</a>ye göre Loki çok yakışıklı, oyunbaz, sinsi ve sevilesiydi. Zekâsı ve oyunlarıyla çoğu defa kendini cezalar içinde bulsa da çoğu defa da fakat içi öfke, hırs ve kıskançlıkla doluydu. Loki’nin babası “yeri göğü titreten” buz devi Farbauti, annesi ise Laufey ya da Nal ismiyle tanınan bir başka buz deviydi. Yani Loki aslında bir devdi.</p>



<div class="wp-block-image"><figure class="aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2021/01/Loki-676x1024.jpg" alt="Loki" class="wp-image-6015" width="420" height="632"/></figure></div>



<p>Loki’nin Asgard’a ne zaman geldiği diğer tanrılar tarafından bilinmemekle birlikte kötü biri olduğu halde ya da kötülükler yaptığı halde bununla birlikte o da Aesir üyelerinden biri olarak kabul görerek Odin’in kan kardeşi olmuştur. Yani o çok izlenen filmlerde Thor ve Loki’nin kardeş olarak gösterilmesi yanlış.</p>



<p>Her ne kadar Loki kötü ve hilebaz biri olarak anılsa da ihtiyaç duyulduğunda zekâsını Aesir’in hizmetine sunmuştur. Yani ne Loki ile ne de Loki’siz…</p>



<h2>Loki'nin Çocukları</h2>



<p>Loki, Sigyn adında bir kadınla evlendi. Bu evlilikten Narfi ve Vali adında iki çocuğu oldu. Öte yandan Loki'nin üç çocuğu daha vardı. Bu çocuklar Sigyn'den değildi. Loki üç defa uzun süre eve gelmedi, Sigyn onu arasa da hiçbir yerde bulamadı fakat Loki üç uzun ayrılık sonunda hiçbir şey olmamış gibi eve geri döndü. </p>



<div class="wp-block-image"><figure class="aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2021/01/canva-photo-editor_-_2019-03-27T104023.039_1024x1024.png" alt="" class="wp-image-6019" width="617" height="306"/></figure></div>



<p>Bir gün Odin, Loki'yi yanına çağırdı. Ona bir rüya gördüğünü ve üç çocuğu daha olduğunu bildiğini söyledi. Bu çocuklar tanrıların başına büyük dertler açacaktı. Üç çocuk anneleri dev Angrboda'dan alınarak tanrıların huzuruna getirildi. </p>



<p>İlk çocuk Jormungundr adında bir yılandı. Odin onu kontrol altında tutmak için tüm diyarların ötesindeki denize bıraktı. Yılan gün geçtikçe büyüdü ve yerkürenin etrafını sardı.</p>



<p>İkinci çocuk Hel adında bir kızdı. Kızın sağ tarafından bakanlar güzeller güzeli bir kız görürken sol tarafından bakanlar ölmeye başlayan bir vücut görüyordu. Odin onu, dokuz diyardaki tüm ölülerin hakimi yaparak yeraltına gönderdi.</p>



<h2>Loki'nin Kurt çocuğu: Fenrir</h2>



<p>Üçüncü çocuk ise  Fenrir adında bir kurttu. Yurt yeryüzünde bırakıldı fakat Tyr onun bakımını üstlenecekti.  Tyr, onu besledikçe Fenrir büyüdü daha da vahşi ve büyük bir hal almaya başladı. Öte yandan Odin rüyalarında bu çocuğun gözlerini görüyordu ve ondan kurtulunması gerektiğini söyledi. Fenrir bağlandı ve ona bu zincirleri kırabilir misin diye soruldu, Fenrir  kolayca kırdı. Sonrasında daha güçlü zincirler getirildi ve Fenrir bunları da kırdı. Tanrılar daha güçlü bir şeyler yapmaları gerektiğini anladılar.</p>



<div class="wp-block-image"><figure class="aligncenter size-large"><img src="https://www.loveinartsz.com/wp-content/uploads/2021/01/lokinin-oglu-fenrir.jpg" alt="loki'nin oğlu Fenrir" class="wp-image-6020"/></figure></div>



<p>Altı farklı madde bir araya getirildi: </p>



<ul><li>Kedinin ayak izleriydi ilki. </li><li>Kadının sakalıydı ikincisi. </li><li>Dağın kökleriydi üçüncüsü. </li><li>Ayının kas teliydi dördüncüsü.</li><li>Balığın nefesiydi beşincisi. </li><li>Bir kuşun tükürüğüydü altıncısı ve sonuncusu.</li></ul>



<p>Malzemeler bir araya getirildi. Zincir yapıldı. Fenrir yapılan her zinciri kırdığı için kendine çok güveniyordu. Bu zincirleri de bağlamalarına izin verdi fakat onlardan kurtulamadı. Böylece tanrıların istediği oldu ve kurt sonsuza dek zincire bağlı kaldı.</p>



<div class="wp-block-image"><figure class="aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2021/01/Lokis-Children-Art-Print-by-irenhorrors.jpg" alt="" class="wp-image-5915" width="252" height="351"/><figcaption>Loki'nin Çocukları</figcaption></figure></div>



<h3>Balder'i Öldüren Loki</h3>



<p>Loki, Odin’in oğlu Balder’in ölümünde de sorumluydu. Onu bu denli çıldırtan şey <a href="https://tarihiolay.com/mitoloji/iskandinav-mitolojisi/loki/">kaynaklara</a> göre Balder'in herkes tarafından sevilip, saygı duyulmasıydı.</p>



<p>Balder Odin ve Frigg'in oğluydu. Yaptığı iyilikler karşısında tanrıların sevgisini kazanmıştı. Balder kabuslar görüyordu. Kabuslarında alemlerin sonunu, Güneş ve Ay'ın bir kurt tarafından yutulduğunu, karanlığı, acıyı ve ölümü görüyordu.  Bir gün rüyalarından ağlayarak uyandı ve tanrılara rüyalarını anlattı. Herkes Balder'in öleceğinden korktu ve dehşete düştü. Biri hariç...</p>



<div class="wp-block-image"><figure class="aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2021/01/Baldur.jpg" alt="" class="wp-image-6021" width="277" height="443"/></figure></div>



<p>Odin, Balder'in kötü rüyalarını anlamak için yola çıktı. Yolda rüyalara yanıtlar aradı bir yere vardı sonunda. Burada bilge bir kadının ona yardımcı olabileceğini söylediler fakat kadın ölmüştü ne yazık...</p>



<p>Odin ölüler ülkesine gitti burada bilge kadını buldu. Kadın ona Balder'in öleceğini anlattı çok geçmeden Odin onun aslında bilge kadın değil Loki'nin sevgilisi Angrboda olduğunu anladı. Odin gerçeklerin farkındaydı tanrılar dahi kaderi değiştiremezlerdi...</p>



<p>Odin eve döndü ve karısı Frigg'e gördüklerini, öğrendiklerini anlattı. Frigg, Balder'den nefret edebilecek biri olduğunu kabul etmedi dolayısıyla yollara çıkıp dağdan taştan, yeryüzündeki her şeyden Balder'in sevgisine sağdık olmaları, ona zarar vermemeleri için yemin istedi. Eve döndü ve herkesin karşısında Balder'e bir taş fırlattı, taş Balder'in üzerinden atlayarak yere düştü. Tanrılar ona silahlar fırlattı ve silahlar ona ulaşamadan yere düştü herkes çok mutluydu. İki kişi hariç...</p>



<div class="wp-block-image"><figure class="aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2021/01/The-Death-of-Baldr.jpg" alt="" class="wp-image-6017" width="484" height="388"/><figcaption><em>Baldur’s Death” by Christoffer Wilhelm Eckersberg (1817)</em></figcaption></figure></div>



<h5><strong>Balder'in bu mutluluğunu paylaşmayan iki kişi vardı</strong>: Loki ve Hod</h5>



<p>Balder'in kardeşi Hod'un iki gözü de görmüyordu dolayısıyla insanların neden bu kadar mutlu olduğunu anlayamıyordu. Herkes mutluluk içinde eğleniyordu fakat Hod ne olduğunu anlayamıyordu. Loki, Hod'un yanına yaklaştı ve ona olan biteni anlatıp onun da eğlenceye katılması için Badler'e bir şey fırlatması gerektiğini söyledi. Hod sonunda sevince ortak olacağını ve herkesin onu alkışlayacağını düşünerek Loki'den aldığı ökse otundan yapılmış oku Balder'e fırlattı. Büyük bir sessizlik oldu. Sonra da çığlık ve ağlama sesleri her yeri kapladı. Frigg, onu ziyarete gelen nazik bir kadına sadece ökse otuna uğramadığını diğer herkese uğradığını söylemişti. Bu nazik kadın tabi ki Loki'den başkası değildi...</p>



<p><strong>Artık tek bir kişinin yüzü gülüyordu...</strong><br>Balder'i ölüler diyarından geri getirmek için Odin'in hizmetkarı Hermod gönüllü oldu. Loki'nin kızı ve ölüler diyarının kraliçesi Hel'in yanına gitti. Hel eğer yeryüzündeki herkes ve her şey Balder'i sevip onun için ağlıyorsa onu geri vereceğini söyledi. Fakat Balder'i sevmeyen tek bir kişi vardı ve Balder sonsuz dek Hel'in yanında kaldı. </p>



<p>Kaynak:</p>



<ul><li>GAIMAN Neil, İskandinav Mitolojisi, İthaki Yayınları, İstanbul, 2019</li><li>MUNCH Peter Andreas, İskandinav Mitolojisi, Maya Kitap, İstanbul, 2020</li><li><a href="https://tarihiolay.com/mitoloji/iskandinav-mitolojisi/loki/" target="_blank" rel="noreferrer noopener">tarihiolay.com/mitoloji/iskandinav-mitolojisi/loki/</a></li></ul>



