UPDATE posts SET content = $tag2$<p class="has-text-align-justify">Özel mimarileriyle binlerce yıldır ayakta kalmış dünyaya iz bırakan en büyük 10 kaleyi birlikte tanıyalım.</p>



<p class="has-text-align-center"><strong><em>Marlbork Kalesi - Polonya</em></strong></p>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/Malbork-castle.jpg" alt="" class="wp-image-2232" width="354" height="478"/></figure>



<p class="has-text-align-justify">Klasik Orta Çağ mimarisine sahip Marlbork Kalesi, dünyanın en büyük kalesidir. Haçlı katolik Alman bir tarikat tarafından 1406 yılında yapılmıştır.1997 yılında UNESCO Dünya Miras Listesi'ne eklendi.</p>



<p class="has-text-align-center"><strong><em>Buda Kalesi - Macaristan</em></strong></p>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/macaristan.jpg" alt="" class="wp-image-2238" width="480" height="300"/></figure>



<p class="has-text-align-justify">Buda Kalesinin inşa sebebi, bölge sakinlerini Moğol istilasından korumaktı. Macaristan'ın Budapeşte şehrinde olan kale 13. yüzyılda inşa edilmiştir ve Gotik'ten Barok mimariye kadar birçok tarzı gözler önüne sermektedir.</p>



<p></p>



<p class="has-text-align-center"><strong><em>Prag Kalesi - Prag</em></strong></p>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/prag.jpg" alt="" class="wp-image-2233" width="593" height="322"/></figure>



<p>Prag Kalesi, Çek Cumhuriyeti'nin başkenti Prag'ta bulunan dünyanın en büyük kalelerinden biridir. Kalenin tarihi 9. yüzyıla dayanır ancak sonraki süreçlerde genişletilmiştir. Gotik, Rönesans ve Romanesk tipi mimarinin en güzel salonları bu kalede bulunur.</p>



<p></p>



<p class="has-text-align-center"><strong><em>Hohensalzburg Kalesi - Avusturya</em></strong></p>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://i2.wp.com/www.loveinartsz.com/wp-content/uploads/2020/06/avusturya.jpg?fit=1024%2C535&amp;ssl=1" alt="" class="wp-image-2239" width="555" height="290"/></figure>



<p>Hohensalzburg Kalesi 250 metre uzunluğunda ve 150 metre genişliğiyle Avrupa'daki en büyük Orta Çağ kalelerinden biridir. 506 metrelik bir yüksekliğe 1077 yılında inşa edilmiştir.</p>



<p></p>



<p class="has-text-align-center"><strong><em>Mehrangarh Kalesi - Hindistan</em></strong></p>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/hindistan-2.jpg" alt="" class="wp-image-2236" width="556" height="341"/></figure>



<p>1459 yılında inşa edilen Mehrangarh bazı eski kaynaklarda hisar olarak geçse de aslında bir Hint Kalesidir. 125 metre yükseklikte bir kayalığa inşa edilmiştir. Kaleye ancak 7 kapıdan giriş yapılarak girilebilir, bu sebepten dolayı işgal edilmesi oldukça zordur.</p>



<p></p>



<p class="has-text-align-center"><strong><em>Spis Kalesi - Slovakya</em></strong></p>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/slovakya.jpg" alt="" class="wp-image-2240" width="540" height="331"/></figure>



<p>13. yüzyılda inşa edilen Spis Kalesi, Slovakya'nın doğusunda yer almaktadır ve 1993 yılında UNESCO tarafından Dünya Miras listesine girmiştir. Orta Avrupa'daki en büyük Orta Çağ kalelerinden biridir.</p>



<p></p>



<p class="has-text-align-center"><strong><em>Himeji Kalesi - Japonya</em></strong></p>



<figure class="wp-block-image aligncenter size-large"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/japonya.png" alt="" class="wp-image-2237"/></figure>



<p class="has-text-align-justify">Savaş, bombardıman ve depremlerden sonra sağlam kalabilen Himeji Kalesi, 1993 yılında UNESCO Dünya Mirası listesinde yerine almıştır. 14. yüzyılda inşa edilen kale kompleksi 1609 yılında tamamlanmıştır. Himeji Kalesi hala Japonya'nın en güzel kalesidir.</p>



<p class="has-text-align-center"><strong><em>Halep Kalesi - Suriye </em></strong></p>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/suriye.png" alt="" class="wp-image-2241" width="623" height="380"/></figure>



<p class="has-text-align-justify">Suriye'nin Halep şehrine inşa edilen Halep Kalesi tepesinin kullanımı M.Ö. 3000 yıllarına dayanır. Bizanslılar, Yunanlar, Eyyübiler ve Memlükler gibi birçok medeniyet tarafından işgal edilmiştir. Dünyanın en eski ve en büyük kalelerinden biri sayılır. Günümüze kadar ayakta kalmayı başarabilen kısmı 13. yüzyılda inşa edilen kısımdır.</p>



<p class="has-text-align-center"><em><strong>Windsor Kalesi - İngiltere</strong></em></p>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://i0.wp.com/www.loveinartsz.com/wp-content/uploads/2020/06/windsor-kalesi.jpg?fit=1024%2C584&amp;ssl=1" alt="" class="wp-image-2243" width="539" height="307"/></figure>



<p class="has-text-align-justify">Britanya monarşisinin resmi ana rezidanslarından biridir. Tarihin en uzun süreli ikamet halinde bulunan sarayıdır ve dünyada içinde insan yaşayan en büyük kale olarak adlandırılır. İngiltere'nin de en büyük kalesidir. Londra'nın 35 kilometre doğusunda yer almaktadır.</p>



<p></p>



<p class="has-text-align-center"><strong><em>Edinburgh Kalesi - İskoçya</em></strong></p>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://i1.wp.com/www.loveinartsz.com/wp-content/uploads/2020/06/edinburgh-castle_1.jpg?fit=1024%2C768&amp;ssl=1" alt="" class="wp-image-2244" width="532" height="398"/></figure>



<p class="has-text-align-justify">Sönmüş bir volkanik kayalıklar üzerine kurulan Edinburgh Kalesi şehrin tepesine inşa edilmiştir. Kaledeki binaların çok azı 16. yüzyıl öncesine dayanır. Kale içerisindeki en önemli bina St. Margaret Şapeli'dir, 12. yüzyılın ilk yarısında inşa edilip ayakta kalan en eski yapıdır.</p>$tag2$ WHERE slug = 'seyahate-cikiyoruz-en-buyuk-kaleler';
UPDATE posts SET content = $tag2$<p>+Ya bak dün gece televizyonu açtım, dedim bir şeyler izleyeyim.</p>



<p>-Güzel dizi hiç yok ki!</p>



<p>+Ben yine de bakmak istedim, hani belli olmaz belki iyi bir şeye denk gelirim diye. Yahu hiç güzel bir şey olmaz mı ya, saçma sapan dizi dolmuş her yer. Hayır anlamıyorum bunları kim izliyor?</p>



<p>-Harbiden öyle, ben de anlamıyorum. Film falan yok muydu peki?</p>



<p>+Filmler var da hepsi dandik. Kaç yıllık yabancı filmler... Ama yerel kanallara denk geldim, birinde Tokatçı vardı.</p>



<p>-Ooo harika film o be.</p>



<p>+Gerçekten ya, babamın çocukluğunda çekilmiş ama hala izliyoruz. Kemal Sunal zaten efsane.</p>



<p>-Şimdi öyle adamlar yok hiç, filmler de vasat. Bu sene film çıksa 3 ay sonra unutuyoruz.</p>



<p>+Vizyon yok kardeşim vizyon, bak yabancılara kaç yıllık kovboy filmleri var ama izliyoruz. Kalite çünkü kalite.</p>



<p>-TRT’de babam izlerdi, şimdi nerede o günler.</p>



<p>+Keşke çocukluğumuza dönsek, bir pazar uyansak böyle, tüplü televizyonda ailecek film izleyip kahvaltı yapsak…</p>



<p>Merhaba sevgili okurlar. Umarım ki böyle samimiyetsiz bir diyaloğa denk gelmemişsinizdir ama tahmin ediyorum ki benzerlerini görmüş ya da bizzat içinde bulunmuşsunuzdur. Bugün eskiye dair olan şeyler hakkında konuşacağız.</p>



<p>Pandemi ile birlikte hepimiz içerik arayışına girdik. Normalde izlemeyeceğimiz ya da sürekli izlemek isteyip vakit bulamadığımız şeyleri izlemek için fırsat bulduk. Birçok kişinin yeni içerikler ve türler denediğini ve daha önce gözden kaçırdığı şeyleri izlediğini gördüm ama başta ben olmak üzere çoğu insanda ise şunu gördüm: izlediğimiz bir şeyi yeniden ve yeniden izlemek. Bir film ya da dizi yeniden izlenebilir. Günümüzde pek olmasa da eski yapımların bana kalırsa daha çok yeniden izlenme kapasitesi var ancak pandemi bu durumu biraz daha melankolik hale getirdi, bizi duygusallaştırdı.</p>



<div class="wp-block-image"><figure class="aligncenter size-large"><img src="https://www.loveinartsz.com/wp-content/uploads/2021/02/9acx06_654a_0001F.jpg" alt="" class="wp-image-6461"/></figure></div>



<p>Yeni şeyleri izlememizin nedeni daha önce izlediklerimizle karşılaştırdığımızda aynı zevki alamama korkusudur bence. Bu elbette benim düşüncem ancak sosyal medyada biraz dolaşınca yalnız olmadığımı anlıyorum. Birçok kişi açıkça belirtmese de yeni yapımlar izlemek istemiyor. Elbette yapımların kalitesi, oyuncu kadrosu ve senaryosu bu konuda büyük bir etken. Ve tabi son yıllarda özellikle mahvolmuş konular/temalar da cabası.</p>



<p>Ben bu dönemde elbette yeni yapımlara önem verdim. Çizgi-dizi türü çok dikkatimi çeken bir tür olduğu için yeni şeyler izlemeye çalıştım. Filmlerde de ödüllü yapımlara özellikle baktım. Sevdiklerim oldu ancak çok kısa bir süre sonra yeni şeyler izlemeyi tamamen bıraktım ve eski, daha sıcak ve bana samimi gelen yapımlara geri döndüm.</p>



<div class="wp-block-image"><figure class="aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2021/02/cem.png" alt="" class="wp-image-6462" width="582" height="423"/></figure></div>



<p>Bir kısmını gayet net hatırlıyordum ancak bir kısmını hayal meyal hatırlıyordum sadece. Bunlardan en çok izlediğim ise kuşkusuz 'Avrupa Yakası' idi. Muhteşem kadrosu, kurgusu, senaryosu bir kenara, bu dizi bir diziden daha fazlasıydı benim için. O tatlı ve güzel, sıcacık, insanların henüz kötü niyetli olmadığı, dünyanın daha güzel olduğu bir dönemdeydi o dizi. Ve bu konu aklıma çok takıldı. İnsanlar gerçekten diziyi mi izliyorlardı yoksa o dönemki hayatlarını mı?</p>



<p>Ve soruma yanıt bulmak çok kolay oldu. Hemen izlediğim videolara gittim ve yorumlara baktım. Bazı yorumlar daha eleştireldi ancak bazıları ise daha duygusaldı. Aynen şunlar ile karşılaştım:</p>



<p>‘’Herkes Avrupa Yakası izlediğine göre ülkenin durumu iyi değil’’</p>



<p>‘’Tahsin babaaa adamsın’’</p>



<p>‘’Dolar iki liramı olacak, ulan Sertaç ülke ne hale geldi be’’</p>



<p>‘’Ne güzel zamanlardı be’’</p>



<p>‘’Keşke bir daha çekilse’’</p>



<div class="wp-block-image"><figure class="aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2021/02/tahsin-baba-1024x662.png" alt="" class="wp-image-6463" width="596" height="381"/></figure></div>



<p>Sadece Avrupa Yakası değil; Muhteşem Yüzyıl, Behzat Ç, Leyla ile Mecnun vb. birçok yapımda bu tarz yorumlar görmek mümkün. Ve farklı şeyler yazsalar da aslında hepsinin ortak bir noktası var: eskiye duyulan özlem.</p>



<p>Elbette bu yapımlar çok güzel ve günümüz yapımlarından en azından bana göre daha kaliteli ancak bizim bunları yeniden izleme sebebimiz yapımların kalitesi değil sadece, ilk izlediğimiz zamanki hayatımızı özlüyoruz. O dönemki yaşantımızı, yaşadıklarımızı özlüyoruz. Belki o yıllar sizin için çok zorlu geçmiş olabilir ancak anılarda iyiler hep ön sıradadır. İyi olanları hatırlarız, bu diziler de bize iyi anlarımızı hatırlatır ve hasretimiz artar. O günlere geri dönemeyeceğimizi hatırlayıp hüzünleniriz.</p>



<figure class="wp-block-gallery columns-3 is-cropped"><ul class="blocks-gallery-grid"><li class="blocks-gallery-item"><figure><img src="https://www.loveinartsz.com/wp-content/uploads/2021/02/CpcpX9aWEAA4iiM.jpg" alt="" data-id="6464" data-link="https://www.loveinartsz.com/?attachment_id=6464" class="wp-image-6464"/><figcaption class="blocks-gallery-item__caption">Behzat Ç</figcaption></figure></li><li class="blocks-gallery-item"><figure><img src="https://www.loveinartsz.com/wp-content/uploads/2021/02/ggf.jpg" alt="" data-id="6465" data-link="https://www.loveinartsz.com/?attachment_id=6465" class="wp-image-6465"/><figcaption class="blocks-gallery-item__caption">Muhteşem Yüzyıl</figcaption></figure></li><li class="blocks-gallery-item"><figure><img src="https://www.loveinartsz.com/wp-content/uploads/2021/02/yavuz_dayak_yedi.jpeg" alt="" data-id="6466" data-link="https://www.loveinartsz.com/?attachment_id=6466" class="wp-image-6466"/><figcaption class="blocks-gallery-item__caption">Leyla ile Mecnun</figcaption></figure></li><li class="blocks-gallery-item"><figure><img src="https://www.loveinartsz.com/wp-content/uploads/2021/02/avrupa-yakasi-ndaki-burhan-altintop-karakterinin-12454670_7842_m.jpg" alt="" data-id="6467" data-full-url="https://www.loveinartsz.com/wp-content/uploads/2021/02/avrupa-yakasi-ndaki-burhan-altintop-karakterinin-12454670_7842_m.jpg" data-link="https://www.loveinartsz.com/?attachment_id=6467" class="wp-image-6467"/><figcaption class="blocks-gallery-item__caption">Avrupa Yakası</figcaption></figure></li></ul></figure>



<p>Ve bu durum sadece diziler ile sınırlı değil. Filmler de bu konuda büyük yer kaplıyor. Özellikle Kemal Sunal filmleri bir çoğumuz için neşenin ve mutluluğun sembolü haline geldi. Ben de çok sevdiğim ve kaç kere izlediğimi hatırlayamadığım Üçkağıtçı, Sakar Şakir ve Yedi Bela Hüsnü filmlerini yeniden izledim. Yorumlara da baktım ve gerçekten eskiye özlem duyduğumuzu anladım.</p>



<p>Zaten bu, kült yapımların en büyük özelliklerinden biri ancak içinde bulunduğumuz durum bu işi daha karmaşık ve duygusal hale getiriyor. Gerek o gün yaşanan hayatlar, gerek ülkenin durumu, gerekse karakterlerin saf ve kin gütmeyen yapısı bizi etkiliyor ve birçoğumuz o yıllarda doğmamış olsak bile özlem duyuyoruz. Ve bu durum bu şekilde sürüp gidiyor.</p>



<div class="wp-block-image"><figure class="aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2021/02/yedi-bela-husnu-16-9-1560165880-880x495-1.jpg" alt="" class="wp-image-6468" width="607" height="338"/></figure></div>



<p>Ben bu uzun dönemde eskileri yad etmenin, yenilere ise kucak açmanın deneyimini bir kez daha yaşadım. Bu sadece film ya da dizi değil, fikir ve düşünce olarak da geçerli. Durup düşünmek, arkamıza bakmak ve mutluluk duymak bizi sevindiriyor ama önümüze de bakmalı ve yıllar sonra yeniden arkamıza baktığımızda bu günlere de özlem duyacağımızı hatırlamalıyız.</p>



<div class="wp-block-media-text alignwide is-stacked-on-mobile"><figure class="wp-block-media-text__media"><img src="https://www.loveinartsz.com/wp-content/uploads/2021/02/Author-Paolo-Coehlo-joins-Worldreader-Library.jpg" alt="" class="wp-image-6469 size-full"/></figure><div class="wp-block-media-text__content">
<p class="has-text-align-left" style="font-size:26px"> Her fikrin bir sahibi olduğu   eski güzel günler sonsuza dek gitti.</p>



<p class="has-text-align-left has-medium-font-size">   Paulo Coelho</p>
</div></div>


