UPDATE posts SET content = $tag2$<p>&nbsp;&nbsp; Doğru ve yanlışı bizim/toplumlarımızın belirlediği bu dünyada ahlakın ne olduğunu, nasıl geliştiğini hiç düşündünüz mü? Ahlak; sözlük tanımına bakıldığında dini, felsefi ve toplumsal açıdan iyi ve kötüyü ayırt etmemizi ve etiketlememizi sağlayan kavram olarak karşımıza çıkar. Peki biz bu iyi-kötü ya da doğru-yanlış kavramını nasıl öğreniyoruz? Ahlaki gelişimimiz nasıl oluyor?</p>



<figure class="wp-block-image size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/08/unnamed-2.jpg" alt="" class="wp-image-3611" width="492" height="277"/></figure>



<p>&nbsp;&nbsp; Ünlü psikolog Kohlberg de bunu merak edip çalışmalar yapmıştır. Bir çalışmasında her yaştan (çocuk, genç ve yaşlı) katılımcısına birtakım hikayeler yöneltmiş ve katılımcıların cevaplarındaki ahlaki yargılamaları incelemiştir.</p>



<p>&nbsp;&nbsp; O zaman Kohlberg’in ünlü hikayelerinden biri olan ‘Heinz İkilemi’ hikayesini bir de sizin üzerinizde inceleyelim ve ahlaki gelişiminizi bulalım:</p>



<figure class="wp-block-image size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/08/heinz-dilemma-1-1024x645.png" alt="" class="wp-image-3621" width="748" height="470"/></figure>



<p>  Kanserden ölmek üzere olan bir kadına onu kurtarabilecek yeni ve özel bir ilaç bulunur. Ama eczaneci ilaç için maliyetinden fazla para istemektedir. Kadının kocası olan Heinz, parayı bulmakta zorlanmaktadır. Tüm çözüm yollarına başvurur, eczaneciye yalvarır, bağış toplamaya çalışır ama gerekli parayı bir türlü bulamaz. En sonunda ölmekte olan karısı için ilacı çalar. Heinz’ın bu davranışı sizce ahlaki açıdan doğru mudur, yanlış mıdır?</p>



<p>Şimdi verilebilecek cevapları inceleyin ve kendinize en uygun cevabı bulun. Bakalım ahlaki gelişiminizde Kohlberg’e göre hangi yaşta kaldınız?</p>



<p>1a) *İlacı çalmamalı çünkü yakalanırsa hapse girer. *İlacı çalmalı eğer üst yetkililerden tanıdıkları varsa ya da yakalanmazsa sıkıntı olmaz. Karısının ölmesine seyirci kalırsa soruşturmaya gidebilir.</p>



<p>1b) *İlacı çalmamalı çünkü karısı kötü biri olabilir/ hapisten çıkana kadar karısı ölebilir/ karısının kanser olması onun suçu değil. *İlacı çalmalı çünkü karısı Heinz’ı yalnız bırakmamış olur, evi çekip çevirir/ eğer yakalanırsa ilacı geri verir çok ceza almaz/ karısını kurtarmak için biraz ceza almayı göze almalı.</p>



<p>2a) *İlacı çalmamalı çünkü herkes onun suçlu olduğunu düşünür ve kimse bir daha yüzüne bakmaz. *İlacı çalmalı çünkü iyi bir amaç için çaldığından insanların gözünde kötü duruma düşmez, iyi bir adam olduğu düşünülür.</p>



<p>2b) *İlacı çalmamalı, zaten çalsa da hapse girdiğinde yasaları çiğnediğinden vicdan azabı çeker. *İlacı çalmalı çünkü karısını kurtarmak için yapabileceği tek şey bu, onurlu bir adam olmalı.</p>



<p>3a) *İlacı çalmamalı, aslında çalacak olsa bile suçlu değil, mecbur kalmış bir adam fakat olağanüstü durumlarda bile yasalar çiğnenmemeli. *İlacı çalmalı yasalar böyle durumlarda çok önemli değildir, herkesin yaşama hakkı vardır.</p>


<!-- wp:block {"ref":2008} /-->


<p>3b) *İlacı çalmamalı çünkü onun gibi ilaca ihtiyaç duyan başka insanlar da var ve herkes çalmaya kalkarsa bir felaket olabilir. *İlacı çalmalı çünkü Heinz ya hırsızlık yapacak ya karısının hayatının kurtaracak böyle bir durumda çalmak ahlaken yanlış olmaz, insan hayatı daha önemlidir.</p>



<figure class="wp-block-image size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/08/600_484700808.png" alt="" class="wp-image-3625" width="565" height="317"/></figure>



<p>Kohlberg’in sunduğu Heinz ikilemi hikayesine verilen cevap ve türevlerinin toparlanmış hali bu cevaplardır. Her cevabın ahlaki olarak neye yöneldiğimizi gösteren bir açıklaması vardır ve Kohlberg bu cevaplarda yaş gruplandırması yapmıştır. Şimdi kendinize uygun bulduğunuz cevabı aklınızda tutun ve Kohlberg’in ahlak kuramında yerinizi bulun:</p>



<p>&nbsp;&nbsp; Eğer 1a ya da 1b seçeneklerindeki cevaplardan birine yakın hissediyorsanız, o zaman 9-10 yaşlarındaki çocukların ahlaki gelişiminde kalmışsınız. Yani tam adıyla ‘Geleneksellik Öncesi Ahlak’ evresi. Genelde bu yaştaki çocuklar bu seçeneklerdeki gibi cevaplar vermişlerdir çünkü verdikleri cevaplarda ceza (1a) ve ödül (1b) yönelimi vardır. Ve çocuklar çoğunlukla ceza ve ödül yönelimiyle büyür -bazen sınavdan yüksek not aldığınız için gelen bir eşya ödülü ya da yanlış bir davranışta bulunduğunuzda gelen odana git cezası gibi-. Dolayısıyla o yaşta bilebileceği tek yönelim budur. Ceza ve ödülün aslında 1a ve 1b seçeneklerine de yansıdığını tekrar okuduğunuzda görebilirsiniz.</p>



<p>&nbsp;&nbsp; Ergenlik döneminin başlarıysa Kohlberg’e göre 2a ya da 2b seçeneklerindeki cevaplara denk gelir, yani o dönemdekilerin çoğunlukla verdiği cevaplar bunlardır. Bu seçeneklerde ortaya çıkan yönelimler: ‘Elalem ne der?’, iyi çocuk ve otoriter yönelimdir. 2a'da okuduğunuz üzere ''İnsanlar ne der?'' düşüncesi ve iyi biri olmanın önemli olduğu algısı mevcuttur. 2b'de ise otoriteler ön plandadır. Yani bu şıklardan birini seçtiyseniz ahlaki gelişimde ergenlik döneminin başlarındasınız. Ayrıca bu evre ‘Geleneksel Ahlak’ olarak adlandırılır.</p>



<p>&nbsp;&nbsp; Kohlberg’in kuramına göre aslında bir çoğumuzun seçtiği cevaplar 3a ya da 3b'de olmalıdır. Tabi eğer bu yazıyı okuyan 9-10 yaşlarında bir çocuk ya da ergenlik döneminin başlarında bir birey değilseniz.</p>



<p>  ‘Geleneksellik Sonrası Ahlak’ evresinde 3a ve 3b'de bulunan cevaplar yer alır ve soyut akıl yürütme olduğu düşünülür. Kohlberg bunun da ergenlik döneminden itibaren yapılabildiğini varsayar. Seçeneklerde sosyal sözleşme (3a) ve etik ilke (3b) yönelimi vardır. Yani daha da açmak gerekirse sosyal sözleşme yöneliminde hukukun üstünlüğü gözetilirken temel insan hakları da ön planda olur -bkz. 3a cevapları-. Etik ilke yöneliminde ise eşitlik ve evrensel etik ilkeleri dikkate alınır ve bazen bu ilkeler hukukla çelişebilir -bkz. 3b cevapları-.</p>



<figure class="wp-block-image size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/08/ahlaki-katiligi-neden-seviyoruz-bilimfilicom-1.jpg" alt="" class="wp-image-3626" width="656" height="328"/></figure>



<p>&nbsp;&nbsp; Belki de şu an seçtiğiniz bir cevap ahlakınızın 9-10 yaşlarındaki bir çocukla ya da ergenliğin başındaki bir bireyle aynı olduğunuzu söylüyor olabilir. Belki de soyut akıl yürütme yapabildiğiniz, tam yaşınızı yansıtan bir cevap seçtiniz ve ahlak gelişiminiz Kohlberg’in kuramına göre gayet normal. Fakat kuramdaki Heinz İkilemi ne kadar size beyin fırtınası yaptırsa da eksik olan şey düşüncelerimiz ve davranışlarımızın uyuşmama halidir.</p>



<p>Şöyle ki insanlar düşüncede çok daha rahat karar alıp verebiliyor veya ahkam kesebiliyor fakat düşünceyi davranışa yansıtma kısmına gelindiğinde işler fazlasıyla değişebiliyor. Aslında en basitinden bu, günümüzde sosyal medyaya yansıyan ‘klavye artistliği’ ile açıklanabilir. Sosyal medyada düşüncelerimizi ifade etmemiz aşırı kolay olduğundan birçok siber zorbalıkla karşılaşabiliyoruz ama gerçek dünyaya baktığımızda insanlar bu kadar açık, kaba ya da kırıcı değillerdir. İşte Kohlberg, kuramını kurarken bu hataya düşmüş ve Heinz ikilemini sadece düşünsel olarak sorup cevabını almıştır. Oysaki eğer insanlar gerçekte o durumda kalsaydı cevapları ve davranışları uyuşmayabilirdi. Bugün ahlaksız dediği cevabı yarın uygulamak zorunda kalabilirdi. O yüzden şimdi bir de Heinz’ın yerinde olduğunuzu tam anlamıyla hayal edin, eğer gerçekten öyle bir durum yaşasaydınız ‘ahlaklı’ davranışınız ne olurdu?</p>



<p>Yararlanılan Kaynak: Psikolojiye Giriş – Smith ve ark.</p>$tag2$ WHERE slug = 'ahlaki-gelisimimiz-heinz-ikilemi';
UPDATE posts SET content = $tag2$<p><em><strong>Ah Tamara!</strong></em></p>



<p>Efsaneye göre zamanında bu adada Ermeni baş keşişi ile güzelliği dillere destan kızı Tamara yaşarmış. Çevre köylerden birinde yaşayan bir çoban, kızın bu güzelliğini duyup aşık olmuş ve her gece kıyıdan adaya doğru yüzmeye başlamış. Tamara ise elinde fener her gece sevgilisinin yolunu aydınlatırmış. Bir gün Keşiş aşıkların geceleri gizli gizli buluştuğunu öğrenmiş ve fırtınalı bir gece kıyıya inerek feneri eline almış ve sürekli yer değiştirmeye başlamış. Çoban sürekli farklı yöne yüzdüğünden gücü tükenmiş ve son nefesini “Ah Tamara!” diye haykırarak vermiş.</p>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/akdamar-adas.jpg" alt="" class="wp-image-2264" width="579" height="407"/><figcaption><em>1860</em></figcaption></figure>



<p>&nbsp;Bu hikâye Ermeni şair Hovhannes Tumanyan anlatımıyla efsaneleşmiştir.</p>



<p>&nbsp;IX. yüzyıldan itibaren kaydedilmiş olan&nbsp;<em>Ağtamar</em>&nbsp;adının Arapça ĞMR kökünden "kabartı, tümsek" anlamına gelen bir sözcük olduğu düşünülmektedir. Türkçeleşmiş hali ise Akdamar'dır.</p>



<p>Ortaçağ'da Van ve Doğu Anadolu bölgesi Ermeni ailelerinin yönetimindeydi. Bu ailelerden Ruştiniler, Vaspurakan adıyla bilinen Van Gölü havzası'nın yönetimini sürdürmekteydiler. Eski kaynaklarda adanın adı &nbsp;<strong>Rştunik Adası</strong> olarak geçmektedir. Ada bir süre sonra Ardzruni ailesinin eline geçmiştir. 908'de&nbsp;<strong>I. Gagik Ardzruni</strong>&nbsp;kendini Vaspuragan Kralı ilan etmiştir. I. Gagik adada halen mevcut olan kiliseyi inşa ettirmiştir. </p>



<p>Van'a gittiğiniz zaman uğramanız gereken duraklardan biridir Akdamar Adası. Van’ın Gevaş ilçesi sınırlarında olan Akdamar Adası'na gitmek için kıyıdan kalkan teknelere binmeniz gerekiyor. 15-20 dakikalık bir mavi yolculuk sonrası adaya ayak basabiliyorsunuz. Girişte sizi gişeler bekliyor ve adayı ve kiliseyi ziyaret etmek için ufak bir ücret ödemeniz gerekiyor.</p>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://i0.wp.com/www.loveinartsz.com/wp-content/uploads/2020/06/Tekne1-1-scaled.jpg?fit=768%2C1024&amp;ssl=1" alt="" class="wp-image-2263" width="410" height="547"/></figure>



<p>Kilise mimarisi oldukça dikkat çekici. Özellikle dış cephesinde bulunan kabartmalar görsel şölen yaratırken, kiliseyi görmeye geleni bir kitap okuyormuş gibi sarıyor. </p>



<figure class="wp-block-gallery has-nested-images columns-2 is-cropped">
<figure class="wp-block-image size-large"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/akdamar-süsleme-2.png" alt="" class="wp-image-2265"/></figure>



<figure class="wp-block-image size-large"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/akdamar-süsleme.png" alt="" class="wp-image-2266"/></figure>
</figure>



<p>Bu süslemeler İncil'den ve Tevrat'tan sahneleri yansıtıyor.</p>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/1.png" alt="" class="wp-image-2269" width="543" height="353"/><figcaption>Yunus Peygamber Sahnesi,Tevrat (Yunus1:1-4)</figcaption></figure>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/2.png" alt="" class="wp-image-2270" width="266" height="379"/><figcaption>Pantakrotor İsa ve Annesi Meryem</figcaption></figure>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/adem-ile-havva.png" alt="" class="wp-image-2271" width="666" height="452"/><figcaption>Adem ve Havva'nın Yasak Meyveyi Yemeleri</figcaption></figure>



<p>Kabartmalar ve tarih arasında kaybolurken kilisenin içindeki bir detay ilginizi çekebilir. Kilisenin hemen içinde sağda bir yazı bulunuyor. Orijinali Ermenice olan bu yazı Katolik Rışdunikli Der Khaçadur'a ait ve  II. Abdulhamit'e övgü dolu sözleri bulunuyor. </p>



<figure class="wp-block-gallery has-nested-images columns-default is-cropped">
<figure class="wp-block-image size-large"><img src="https://i1.wp.com/www.loveinartsz.com/wp-content/uploads/2020/06/Yazı-scaled.jpg?fit=768%2C1024&amp;ssl=1" alt="" class="wp-image-2274"/></figure>



<figure class="wp-block-image size-large"><img src="https://i1.wp.com/www.loveinartsz.com/wp-content/uploads/2020/06/yazı-2-scaled.jpg?fit=768%2C1024&amp;ssl=1" alt="" class="wp-image-2275"/></figure>
</figure>



<p>Adanın ve gölün doğal güzelliği birleşince ortaya harika bir görsel şölen çıkıyor. Üstelik bahar aylarında gittiyseniz yeni açan çiçeklerle adanın uyumunu görmeniz mümkün. Yazın ise adaya ait olan kıyılarda göle girip serinleyebilirsiniz. </p>



<p>Ayrıca Ermeniler bu adayı dini vecibelerini yerine getirmek için ziyaret ediyor. Kültür ve Turizm Bakanlığının izniyle 2010'dan bu yana eylül ayının ikinci pazarı gerçekleştirilen ayinlerde adayı binlerce Ermeni ziyaret ediyor. </p>



<p>Adayı sanal turla gezmek için: https://www.akdamarkilisesi.gov.tr/sanaltur</p>



