UPDATE posts SET content = $tag2$<p>Değişen tenis topları sergisi olduğunu duysanız ne yapardınız? </p>



<p>İngiltere’nin başkenti Londra’da sanatçı David Shrigley’in Stephen Friedman Galerisi'nde açtığı yeni enstelasyon dikkat çekiyor.</p>



<figure class="wp-block-image size-full"><img src="https://www.loveinartsz.com/wp-content/uploads/2021/11/Sergi.jpg" alt="" class="wp-image-8518"/></figure>



<p>Sanatçı David Shrigley’in yeni sergisinde değişmeyen tenis topu kalmaması amaçlanıyor.  Ziyaretçilerin ellerinde getirdikleri tenis toplarını sergide yer alanlardan birisiye değişmeleri isteniyor.  </p>



<p>Sanat enstalasyonunda 12 bin tenis topu yer alıyor.</p>



