<p>Kaynak: Sözcü</p>$tag2$ WHERE slug = 'ingilterede-ilginc-sergi';
UPDATE posts SET content = $tag2$<p>Dünyaca ünlü sokak sanatçısı Banksy'nin imzalı bir resminin bulunduğu duvar söküldü.. Sosyal medyadan yankı bulan duvarın sökülme anı vatandaşları endişelendirdi. </p>



<p>Levyeli bir çocuğun resminin bulunduğu duvar bölgeye gelen ekipler tarafından söküldü </p>



<p>Bölgede yaşayan bir kişi ise “Sanatsal bir bağlamda şehir içinde daha belirgin bir yerde sergilenmek üzere kaldırılıyorsa, bu çok hoş. Sahibi, eserin bulunmasının mülkün değerine 200.000 Sterlin eklediğini, ancak müzayede için çok daha fazlasını getirebilir. Bu büyük bir utanç” dedi.</p>



<p>Londra Kraliyet Sanat Koleji’nde Siyasi Sanat Profesörü Peter Kennard, “Bu, kapitalizmin uç noktası. Birisi halk için bir şey yapıyor, başka biri de para kazanmak için bunu kaldırıyor. Ahlak dışı ama sanat dünyasındaki alış ve satışların çoğu ahlaksız. Bu tamamen Banksy’nin yaptığının ahlakına aykırı” dedi.</p>



<p>Parçayı satacak olan Julien’s Auctions, eserin 200 bin ila 400 bin&nbsp;<a href="https://www.sozcu.com.tr/dolar/?utm_source=anchortext&amp;utm_medium=free&amp;utm_campaign=dolar" target="_blank" rel="noreferrer noopener">dolar</a>&nbsp;arasında bir fiyata satılabileceğini tahmin ediyor.</p>



