UPDATE posts SET content = $tag2$<p>Hemen hemen her çağda <a href="https://www.loveinartsz.com/edebiyat/yazar-sair/" title="">şairleri </a>etkileyen, <a href="https://www.loveinartsz.com/sanat/resim/" title="">ressamlara </a>ilham veren Nergis çiçeği anlamı ile de oldukça dikkat çeker. Nergis çiçeğini en güzel anlatan şairler arasında <a href="https://tr.wikipedia.org/wiki/Ovidius" title="">Ovidius</a> gelir. </p>



<h2>Nergis Çiçeğinin Anlamı</h2>



<p>Efsaneye göre bir perinin ve bir tanrının oğlu olan Narkissos o kadar yakışıklı bir delikanlıymış ki onu gören tüm kızlar aşık olurmuş. Bir gün çok güzel bir peri kızı olan "Ekho" ormanda avlanan Narkissos adında ki yakışıklı avcıyı görmüş. Ona ilk görüşte aşık olur, ancak Narkissos kendini beğenmiş tavrı ile bu sevgiye karşılık vermez ve peri kızının yanından uzaklaşmış. Ekho bu durum karşısında günden güne eriyerek kara sevda ile içine kapanmış ve ölmüş. Bütün vücudundan arta kalan kemikleri kayalara, sesi ise bu kayalarda "Eko" dediğimiz yankılara dönüşmüş. Olimpos dağında yaşayan tanrılar bu duruma çok sinirlenmiş ve Narkissos'u cezalandırmaya karar vermişler.</p>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2023/01/image-3-844x1024.png" alt="Nergis Çiçeğinin mitolojik hikayesi" class="wp-image-10013" width="700"/></figure>



<h3>Narkissos'un Cezası</h3>



<p>Günlerden bir gün kırlarda avlanmaya çıkan Narkissos susamış ve yorgun bir şekilde bir nehrin kenarına gitmiş. Narkissos  su içmek için eğildiğinde, sudan yansıyan kendi yüzü ve vücudunun güzelliğini görmüş. O da bu güzellik karşısında adeta büyülenmiş ve kendine aşık olmuştur. O ana dek kimseyi sevmediği kadar, kendini sevmiştir. O andan sonra Narkissos orada ne su içebilmiş ne de yemek yiyebilmiş. "Ekho" gibi Narkissos da günden güne erimeye başlamış ve orada kendini seyrederek ölmüştür. Öldükten sonra da vücudu nergis çiçeklerine dönüşür. Efsane bu şekildedir. </p>



<p><strong><em>Not: kendini beğenen kişiler için söylenen "Narsist" kelimesi de Narkissos'un kendine olan aşkından gelmektedir.</em></strong></p>



<figure class="wp-block-image aligncenter size-full is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2023/01/image-2.png" alt="Nergis Çiçeğinin mitolojik hikayesi" class="wp-image-10012" width="700"/></figure>



<h4>1944 yılı Tercüme Mecuası'nda yayınlanan Can Yücel Çevirisiyle Ovidiud'un Nergis hikayesi;<br></h4>



<pre class="wp-block-verse">Ekho görünce Narkissos'u bir ıssız kırda dolaşırken
arzu sardı gönlünü, düştü gizlenerek izlerinin ardına;
bir çıranı ucuna sürülmüş yanıcı kükürt beri getirilen alevi nasıl kaparsa
Ekho da yaklaştıkça ona daha yakından yanıyordu aşkla.
Kaç kere okşayıcı gözlerle ona sokulmak, kaç kere yumuşak dileklerini ona sunmak istedi;
Yaradılışı vermedi izin söze başlamaya, bekleyebilirdi ancak sözleri ki onlara cevap yollayacak
Narkissos la Ekho arasında anlamsız diyalog şöyle sürdürülür:
Bağırdı: "Orada kim var?", "Var" diye cevap verdi yankı.
Narkissos, "Burada buluşalım" der, Ekho da koşa koşa çıkar ormandan, ama oğlan kızı görünce kaçmaya koyulur:
"Ölmek yeğdir" diye bağırıyordu "olacaksa senin her şeyim".
Ekho başka bir şey söylemedi: "Senin her şeyim"

Bundan sonra da asıl Narkissos efsanesi başlar:
Berrak bir pınar vardı, dalgalarında gümüşler oynaşır,
Ona ulasan ne bir çoban, ne otlayan bir keçi, ne bir sürü
Ne vahşi bir hayvan, ne ağaçtan düsen bir dal;
tek bir kus bile yoktu onun sükûnunu bozan.
Çevresinde en vakin suyla beslenir bir çayır, ve oranın güneş ışığıyla ısınmasına engelolan orman.
Pınar ve yerin güzelliği çeker onu kendine, uzanır Narkissos av yorgunluğu ve sıcağın verdiği ağırlıkla yere.
Gidermek isterken susuzluğunu, artıyordu bir yandan susuzluğu;
içtikçe suya vuran güzelliğine hayran, seviyordu tensiz bir hayali, vücut sanıyordu sulardakini
Donakaldı Paros mermerinden bir heykele
benzeyen o aynı yüzle kımıldamaksızın, bakıyordu kendine kendi şaşkın şaşkın.
Bilmeden kendini arzuluyor, severken onu kendini seviyor,
isterken kendini istiyordu, içini yakan ateşi tutuşturan da kendiydi.
Kaç kere faydasız öpücükler sundu aldatan pınara...
Ellerini kaç kere daldırdı, boşa kavuştu kolları sularda.
Neyi gördüğünü bilmiyor, fakat yanıyordu onunla,
gözleri aldatan hayal onu costuruyordu.
Narkissos anlar başına geleni ve söyle dile getirir:
Anlıyorum, o benim, aldatmıyor beni artık hayalim.
Tutuşturan da ben, yanan da.
Kendime olan sevgimle yanıyorum.
Ne yapayım? İsteneyim mi? İsteyeyim mi?
İstenecek ne kaldı artık?
Beni yoksul ediyor varlığım; arzuladığım benimle.
Ayrılabilsem vücudumdan; garip bir dilek seven için ama,
sevdigim uzak olsa keşke. Kemirsin artık gücünü acı, ve geldi son günleri ömrümün, göçüyorum hayatimin baharında.
Ölüm gelmeyecek bana ağır dinecekse acılarım.
Sevdiğim daha ömürlü olsun dilerim.
Ve şimdi can verelim ikimiz bir solukta.

Narkissos gün geçtikçe eriyip gider, Ekho da uzaktan seyreder sevdiğini,
Tekrarlar durur iniltilerini ve bu güzelim şiir su dizelerle sona erer:
Şunlar oldu son sözleri, gözlerini ayırmadan sulara bakan Narkissos' un:
"Ey bos yere sevdiğim çocuk" yer tekrar iletti dediklerini.
"Elveda" deyince o, bağırdı Ekho: "Elveda".
Yorgun başını dayadı sık çayırlığa, ölüm kapadı efendilerinin güzelliğine hayran gözlerini.

Hala bakıyordu kendine, yeraltına göçtükten sonra bile;
bakıyordu Styks sularına. Dövündüler bacıları Naias'lar
kesik saçlarını yani başına koydular; dövündüler Dryas'lar,
Ekho da katıldı onlara. Tam sedyeyi, odun yığınını, titreyen meşaleleri hazırladılar, ama vücut yoktu hiçbir yerde, yerinde sari göbeğini beyaz yaprakların kucakladığı bir çiçek buldular.</pre>



<p>Kaynak: Azra Erhat, Mitoloji Sözlüğü</p>$tag2$ WHERE slug = 'nergis-ciceginin-mitolojik-hikayesi';
UPDATE posts SET content = $tag2$<figure class="wp-block-pullquote"><blockquote><p>"Yalnızca bir şeyi öğren, henüz yoğrulabilir olan aklına şunu iyice kazı: insanoğlunda büyük bir yalnızlık korkusu vardır. Yalnızlıklar içinde en korkuncu, töresel yalnızlıktır. İlk keşişler Tanrı'yla yaşadılar, dünyaların en kalabalığında, ruhlar dünyasında ömür sürdüler. İster keşiş olsun, ister mahpus, ister bir günahkar ya da alçak, insanoğlunun ilk düşüncesi, yazgısını paylaşan bir arkadaşının olmasıdır. Bu güçlü istek olmasaydı şeytan kendine arkadaş bulabilir miydi?"</p><cite><em>Kaşifin avcısı - balzac</em></cite></blockquote></figure>



<p> İnsan ana rahminden ayrıldı mı bir daha geri dönemez, insan cennetten bir kez kovuldu mu geri gidemez. Bireyselleşme süreci göbek bağımız koparıldığı an başlar, özgürleşme ise cennetten kovulma ile. Bireyselleşen bireyin gelişimini kimi kuramcı ebeveyn durumlarına göre değerlendirir, kimi gelişim dönemlerindeki kazanımlarla, kimi ise libidoyla. "Yaşamlarımız" der Adler, "başkalarının yaşamlarına değer kattığımız ölçüde değerlidir". Sosyal çevreyi gelişim basamaklarında ana faktör olarak Adler gibi görenler de yok değildir. Bireyselleşmenin sosyal ilgi ile taçlanıp toplumsal dayanışma ile ilerlemesiyle birey sağlıklı bir insan olabilecektir. Bireyselleşmenin doğuşu ona özgürlük getirir. Fakat birey sürüden ayrılamaz. Sürü liderinden kopamaz. Özgürleşme isteği yerini kitleye ait olmaya bırakacaktır.</p>



<div class="wp-block-image"><figure class="aligncenter size-large"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/12/goya_-_entierro_de_la_sardina_real_academia_de_bellas_artes_de_san_fernando_1812-14.jpg" alt="" class="wp-image-5524"/><figcaption>Francisco Goya  “The Burial of the Sardine”&nbsp;</figcaption></figure></div>



<p>Aidiyet duygusu önce ebeveyne yönelik olarak başlasa da bu durum ergenlikte yerini romantik ilişkilere bırakır. Fakat yaşamın ilerleyen safhalarında bireyi tatmin edecek ikili ilişkiler yerine toplumsal duygulara bırakacak ve bireysellikten toplumsallığa geçiş aşaması başlayacaktır. Birey, dünyada yolunda gitmeyen olayların var olduğunu anlayacak ve kendini sosyokültürel bağlamın içinde bulacaktır. Bir dini inanç sistemine ait olabilir, bir ideolojiye kendini feda edebilir, varoluş amacı öğretmek olabilir. Yaşam tarzları ne olursa olsun insanların var olma amacı bir kitleye yöneliktir. Hitap ettiğimiz kitleyi bazen biz seçeriz. Bazen ise o bizi seçer. Bireyin ruhuna hükmeden özgürlük ihtiyacı değil ait olma ihtiyacıdır. </p>



<p><em>"Fiziksel açlık nasıl bedeni ölüme götürürse, kendini tümden yapayalnız ve soyutlanmış hissetmek de aynı şekilde insanın zihnini parçalamaya götürür" der Fromm. Bireyin inandığı düşünce sistemi, dini inanç, ideoloji dışarıdan ne kadar saçma gözükürse gözüksün bir aidiyet duygusu katacağı için dört elle sarılır ona.</em> Hatta bu sarılış çoğu zaman kendi aleyhine kararlar almasına bile sebebiyet verebilir. Kitlenin olumlu sosyal bir dürtüsü ile birey çoğu zaman bencillik yapamayacak ve kitle lehine kararlar verecektir. Bireyin kendini ikinci plana atışı yalnızca bir kitleye ait olduğunda göstereceği bir harekettir. </p>



<p>Fikirleriyle Atatürk'ü etkileyen düşünür Gustave Le Bon Kitlelerin Psikoloji kitabında şuna değinir: Kitle içinde imkansızlık kavramı yoktur. Birey tek başına yapamayacağını bildiği şeyleri kitlenin ruhuyla yapabilir. Tek başınayken bir sarayı ateşe vermek zordur fakat arkanızda bir kitle varken aklınızdan geçenleri ortaya koymak daha kolay olacaktır. Üstelik kitlelerin karar alma süresi bireysel karar alma süremizden kimi zaman daha hızlıdır. Anlık uyarıcılar ile karar alan kitle için düşünülen şey o an harekete geçirilir. Bireysel olarak özel hayatımızdaki kararları çoğunlukla uzun süre düşünür ve hayata geçiririz.</p>



<p>Bir kitleye ait olmanın olumsuz yönlerini vurgulayanlar ise yok değildir. Kitle demek herkesin belli bir düzeyde olduğu yerdir. Bireysel olarak edindiğimiz kültürel, sanatsal, entelektüel becerilerimiz kitle içinde yok olur. Kitle herkesi alt bir düzeyde eşitler. Birey başaracağı kimi görevleri, ortaya koyacağı kimi hedefleri bir kitlenin üyesi olduğu için kaçırabilir veya onlardan vazgeçebilir. Kitlelerin her zaman doğru kararlar alacağının, gittiği yolun düzgün olacağının garantisi yoktur. Üstelik kitlenin büyüsüyle birey gitmek isteyeceği yönü şaşırabilir.</p>



<p>Göbek bağının kesilmesiyle başlayan özgürlük, bir seçim ile son bulur; kitle seçimi. Hangi kitleye ait olacağımıza karar verdiğimiz veya buna karar vermek zorunda kaldığımız andan itibaren artık özgür değilizdir. Seçimler kitleleri güçlendirecek ve güçlenen kitleler itaatin kapılarını aralayacaktır. <em>Askerlikte her gün sabah aynı saatte uyanmanın, hep aynı hareketleri yapmanın, sol ayağını kaldırarak yürümenin elbette savaş stratejisi yoktur</em>. <em>Fakat itaat stratejisi vardır. Yarın ölüm emrini geldiğinde korkusuzca savaşa gitmenin stratejisi vardır.</em> Kitleler itaatler ile kendini yaşatır. Bireyler ise ait olduğu kitlenin normlarına itaat eder. </p>



<p>İçinde yaşadığımız dünya çağlar boyunca farklı kitlelere ve gruplara tanıklık etti. Otoriter rejimler yıkıcı kitleler üretti, hümanist rejimler barışı getirdi. Gandi, İsa, Sezar, Atatürk içinde bulunduğu kitleyi değiştirmiş olan liderlerdir. Onların yaşadığı çağlarda dünya elbette başka bir dünyaydı ve onların yapabildiği kendi kitlesini etkilemekti. Bizler ise hangi kitleye ait olursak olalım onu şekillendirecek olanın yine bizler olduğunu unutmamalıyız.</p>



<h4>KAYNAKÇA</h4>



