<p>Baktım rüzgarsın sen<br>Baktım çamaşır ipini zorluyorsun<br>Hepimizin derdi güzel yaşlanmak sevgilim<br>Baktım bir kitabın sayfalarını çeviriyorsun<br>Ayağına terlik giy<br>Bildiğimiz şeylerin taşında yalınayak geziyorsun<br><br>Biz satranç oyuncusuyuz sevgilim<br>Üzerimizde kara bir leke biz satranç oyuncusuyuz<br>İnanıyoruz ceketlere düğmelere<br>İnanmıyoruz takvimleri savurarak gelen geleceğe<br>İşte yitirdik bütün taşlarımızı darmadağınık oyun tahtası<br>Bir tek şahımız duruyor sevgilim, o da evli, iki çocuk babası<br><br>Kelimeler önümüze çıkıyor sevgilim<br>Uykumuzu bölüyor buradan çocukluğumuza kadar<br>Buradan çocukluğumuza kadar bir telaş<br>İçi boş kuşları kovalıyoruz ve bir sebep arıyoruz<br>Herkese küsmek için<br>Hemen o cumartesi buluyoruz, hemen o pazar<br><br>Yaşamak çukur yerlere doluyor diyorlar<br>Bu yüzden yıkıntıya dönüşse de yaşıyormuş insan<br>Ama hep yıkıldığımız yeter sevgilim, biraz da kekik toplayalım<br>Kıymetini bilmediğimiz şeyler var<br><br>Yaşamak bir at gibi huysuzlanıyor kapımızda sevgilim<br>Geçen günlere üzüldük tamam yola düşelim<br>Düşünelim: başka günlerin duvarı daha sağlam<br>Düşünelim: başka günlerin sokağı daha neşeli<br>Başka evlerin kadınları erkekleri tam bir kahraman<br>Tül perdeler uçuşurken başka evlerin pencerelerinde<br>Bizi bir kitabın sayfaları arasında kurutuyor zaman<br><br>Ama baktım sen rüzgârsın sevgilim<br>Kitapları bir başından bir sonundan okuyorsun<br>Başucunda bir bardak su<br>Beni başucumda bir bardak su gibi avutuyorsun</p>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://i0.wp.com/www.loveinartsz.com/wp-content/uploads/2020/05/1_oRoWuDVHzk5V01MavnQTmw.jpeg?fit=1024%2C576&amp;ssl=1" alt="" class="wp-image-1840" style="width:719px;height:404px"/></figure>



