UPDATE posts SET content = $tag2$<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://i0.wp.com/www.loveinartsz.com/wp-content/uploads/2020/05/Autoportrait_au_béret_par_Paul_Cézanne-1-scaled.jpg?fit=853%2C1024&amp;ssl=1" alt="Paul Cézanne Kimdir?" class="wp-image-1847" width="369" height="441"/></figure>



<p class="has-text-align-justify">Paul Cézanne 19 Ocak 1839'da Fransa' nın taşra bir bölgesi olan <a href="https://tr.wikipedia.org/wiki/Aix-en-Provence" class="aioseop-link">Aix-en Provence</a>' de doğdu. </p>



<p class="has-text-align-justify">Paul' un babası <a href="https://tr.wikipedia.org/wiki/Fötr" class="aioseop-link">fötr şapka </a>ticareti ile uğraşıyordu ve bu işten çok fazla kazanınca Cézanne and Cabassol Bankasını kurdu Paul' un varlıklı bir aileden gelmesi eğitim hayatınında iyi bir şekilde gelişmesine neden olmuştur. Aix' deki Collage Bourbon' a girmiş ve burada yakın dostu Emile Zola ile tanışmıştır. </p>



<p class="has-text-align-justify">Paul babasının teşvikiyle Aix Üniversitesine hukuk okumak için kaydolmuştu fakat ailesinin izinden gitmeyeceği ve hukuk okumayacağı açıkca görünüyordu. Emile Zola onu bu konuda cesaretlendirdi ve Paul Paris' e gidip sanatçı olmaya karar verdi. Fakat Paris' e taşındıktan sonra oldukça mutsuz bir dönem geçirdi çünkü Paris' in sofistike yaşamına ayak uyduramamış ve kendini yalnız hissetmişti.  Daha sonra Aix' e geri döndü fakat orada çok uzun süre kalmayarak tekrar cesaretlenerek Paris'e geri döndü. </p>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://i1.wp.com/www.loveinartsz.com/wp-content/uploads/2020/05/Le_Père_du_peintre_lisant_LÉvénement_par_Paul_Cézanne-scaled.jpg?fit=612%2C1024&amp;ssl=1" alt="" class="wp-image-1848" width="310" height="518"/><figcaption>sanatçının babası</figcaption></figure>



<p class="has-text-align-justify">Paul,  sık sık Louvre Müzesine gider ve büyük sanatçıları taklit ederdi. İlk eserlerini kendinden önceki ustalardan ve o dönemin büyük ustalarından etkilenerek yaptı. Cézanne, Paris' te yeni arkadaşlar edindi. Paris' in Batignolles bölgesinde Cafe Guerbois' de aydınların arasına katıldı. Cézanne burada Camille Pissarro ile tanıştı ve onun sayesinde Manet, Monet Renoir gibi isimlerle tanıştı.  Resmi Salon tarafından reddedilen sanatçılardan biri de Cézanne olmuştu. Salon' a birçok resim göndermiş fakat hepsi reddedilmişti. Kariyerinin başlarında eserleri Manet, Pissarro ve Whistler gibi isimlerle aynı yerde sergilenmişti.</p>



<p>Cézanne, sevgilisi Hortense Fiquet ile aynı eve yerleştiğinde ailesine bu durumdan bahsetmemişti çünkü babasının harçlığını kesmesini istemiyordu. Bu sebeple yeni kurduğu ailesini Aix' deki ailesinden saklamıştı. Hortense ile yaşamaya başladıktan sekiz sene sonra babası gerçeği öğrendi ve yardımlarını geri çekmeye başladı. </p>



<p>1886 yılnda yakın arkadaşı Emile Zola bir roman -l'oeuvre- yayımladı. Bu roman Cézanne' nin hayatını anlattığı sanılan, başarısız bir sanatçının üzerineydi. Bu roman yayımlandıktan sonra arkadaşlıkları bitti. Yine o yıl Hortense ile evlenen Paul, babasının ölümüyle aile mirasını alarak Jas de Bouffan' a taşındı.</p>



<p>1895 yılında Ambroise Vollard galerisinde ilk defa kendi sergisi düzenlendi.</p>



<p>Cézanne yüzerin altındaki şeye doğru uzanan bir çizim tarzını benimsemiştir. Aynı dönemdeki Empresyonist ressamlar yüzeyin üzerindeki anlık ışık görünümünü yakalamak için oldukça hızlı çalışırken, Paul yavaş bir şekilde çalışmıştır. Kendisi '' tıpkı müzelerdeki sanat eserleri gibi sağlam ve dayanıklı bir Empresyonizm yaratmak'' istediği söylemiştir. </p>



<p>Cézanne, Paris' i bir elmayla fethetmek yani natürmortlarıyla ünlü olmak istediğini söylemiştir.</p>



<p>Onun sanatı günümüzde 20. yüzyıl Batı sanatının gelişimi üzerinde önemli bir etkiye sahip olarak görülmektedir. Tarihçiler, önce Kübizmin, sonra da soyutlamanın doğduğu modern sanatın temeli olarak Cézanne'yi kabul etmektedirler. </p>$tag2$ WHERE slug = 'paul-cezanne-kimdir';
UPDATE posts SET content = $tag2$<figure class="wp-block-image aligncenter"><img src="https://upload.wikimedia.org/wikipedia/commons/thumb/4/44/Jean-Auguste-Dominique_Ingres_-_La_Baigneuse_Valpin%C3%A7on.jpg/402px-Jean-Auguste-Dominique_Ingres_-_La_Baigneuse_Valpin%C3%A7on.jpg" alt="Dosya:Jean-Auguste-Dominique Ingres - La Baigneuse Valpinçon.jpg"/></figure>



<p>  Neoklasisizm'in en önemli ressamlardan Fransız Jean Auguste Dominique Ingres'ın Valpinçonlu Yıkanan Kadın tablosundan bahsedeceğim. Resim 1808 yılında yapılmış olup günümüzde Louvre Müzesinde sergilenmektedir. Orijinal ismi 'Femme assise' (Oturan Kadın) olan eserin 19.yüzyıldaki sahiplerinden birinin adı verilmesiyle günümüzde 'La Baigneuse Valpinçon' (Valpinçon Yıkananı) ismiyle biliyoruz. Ressamın 1808 yılında Roma'da Fransız Akademisi'nde okurken Paris'e gönderdiği üç resimden biriydi ancak eleştirmenleri etkileyemedi.1855 yılına geldiğinde eleştirmenler tarafından olumlu notlar almaya başladı. Ingres, Neoklasisizm'in ilk ressamlarından olan Jaques Louis David'in öğrencisiydi. Valpinçon Yıkananı, David'in üslubundaki berraklığı ve klasik ideal anlayışını barındırır. Resimde sade ve sakin bir atmosfer içerisinde arkası donuk oturan çıplak kadın figürü yer almaktadır. Figürün yüzünü göremiyor oluşumuz resme gizemli bir hava katmakla birlikte figürün hareketsizliği resmi durağan bir hale getiriyor. Kullanılan soğuk ve yumuşak renkler resmin durağan havasını pekiştiriyor. Ingres'ın resmettiği bu figür, daha kariyerinin başında ressamın kendisi için ideal güzellik anlayışını bulduğunu gösteriyor. Aynı figürü ileriki yıllarda yaptığı Türk Hamamı ve Küçük Banyo resimlerinde de görüyoruz. Valpinçon Yıkananı; figürün sahip olduğu sırt kıvrımı, dokulardaki ayrıntıcılık, durağanlık ve dağınık ışığıyla Ingres'ın stilinin tipik özellikleri haline geldi. </p>$tag2$ WHERE slug = 'valpincon-yikanani';
UPDATE posts SET content = $tag2$<blockquote class="wp-block-quote"><p>Çeviri kadın gibidir, güzeli sadık olmaz, sadığı güzel...</p><cite>Can Yücel</cite></blockquote>



<p class="has-text-align-justify">En önemli ve popüler modern Türk şairlerimizden biri olan <a href="https://tr.wikipedia.org/wiki/Can_Y%C3%BCcel" class="aioseop-link"><span class="has-inline-color has-vivid-cyan-blue-color">Can Yücel</span></a>'in Shakespeare çevirileri her daim tartışma konusu olmuştur. Kullandığı kaba ve samimi diliyle Türk şiirinde farklı bir tarz yaratan Yücel'in çevirilerini, bazı otoriteler doğru bulurken, bazıları da Shakespeare'e hakaret niteliğinde kötü çeviriler olduğunu savunmakta. Samimi ve Türkçenin nimetlerinden faydalanan bir üslupla çeviri yapan Can Yücel adeta şiiri tekrar kendi yazar ve bu da eleştirilerin hedefi olmasına neden olur. Can Yücel bu konu hakkında fikirlerini <a href="https://www.goodreads.com/book/show/29388807-her-boydan" class="aioseop-link"><span class="has-inline-color has-vivid-cyan-blue-color">Her Boydan</span></a> adlı kitabında şöyle açıklamıştı:</p>



<blockquote class="wp-block-quote"><p>"Çeviri kadın gibidir, güzeli sadık olmaz, sadığı güzel diye bir atasözü var. Çoğu atalar gibi, o Rus atası da yanılmış. Çeviri kadın gibidir, doğru. Doğru ama, güzeli sadık olur onun da. Sadığı güzel mi olur ille, bakın, orasını bilemiyorum. Bu köpeksi kuşkum, belki de, o güvenilir, o sadık bellenmiş çevirmenlerin harî, lafzi, anlamı yakalayacağım derken şiirin tınını kaçıragelmiş olmalarından doğuyor. Oysa şiiri şiir eden tınıdır, o gümledi mi, şiir de gümler…" </p></blockquote>



<p class="has-text-align-justify">Belirttiği gibi şiiri çevirirken önce tınısına ve dokusuna dikkat ediyor Yücel, eğer o tını ve hissiyat kaybedilirse, sadık çevirinin güzel olamayacağından bahsediyor. Ona göre her güzel çeviri sadıktır fakat her sadık çeviri güzel değildir... İşte bazı William Shakespeare 66. Sone çevirileri:</p>



<p><strong>66. Sone (Can Yücel’in çevirisi)</strong></p>



<p>Vazgeçtim bu dünyadan tek ölüm paklar beni,<br>Değmez bu yangın yeri, avuç açmaya değmez.<br>Değil mi ki çiğnenmiş inancın en seçkini,<br>Değil mi ki yoksullar mutluluktan habersiz,<br>Değil mi ki ayaklar altında insan onuru,<br>O kızoğlan kız erdem dağlara kaldırılmış,<br>Ezilmiş, horgörülmüş el emeği, göz nuru,<br>Ödlekler geçmiş başa, derken mertlik bozulmuş,<br>Değil mi ki korkudan dili bağlı sanatın,<br>Değil mi ki çılgınlık sahip çıkmış düzene,<br>Doğruya doğru derken eğriye çıkmış adın,<br>Değil mi ki kötüler kadı olmuş Yemen' e&nbsp;<br>Vazgeçtim bu dünyadan, dünyamdan geçtim ama,<br>Seni yalnız komak var, o koyuyor adama.</p>



<p><strong>66. Sone (Talât Sait Halman’ın çevirisi)</strong></p>



<p>Bıktım artık dünyadan, bari ölüp kurtulsam:<br>Bakın, gönlü ganiler sokakta dileniyor.<br>İşte kırtıpillerde bir süs, bir giyim kuşam,<br>İşte en temiz inanç kalleşçe çiğneniyor,<br>İşte utanmazlıkla post kapmış yaldızlı şan,<br>İşte zorla satmışlar kızoğlankız namusu,<br>İşte gadre uğradı dört başı mamur olan,<br>İşte kuvvet kör-topal, devrilmiş boyu bosu,<br>İşte zorba, sanatın ağzına tıkaç tıkmış.<br>İşte hüküm sürüyor çılgınlık bilgiçlikle,<br>İşte en saf gerçeğin adı saflığa çıkmış,<br>İşte kötü bey olmuş, iyi kötüye köle;<br>Bıktım artık dünyadan, ben kalıcı değilim,<br>Gel gör ki ölüp gitsem yalnız&nbsp;kalır sevgilim.</p>



<p><strong>Sonnet 66</strong></p>



<p>Tired with all these for restful death I cry:<br>As to behold desert a beggar born,<br>And needy nothing trimmed in jollity,<br>And purest faith unhappily forsworn,<br>And gilded honour shamefully misplaced,<br>And maiden virtue rudely strumpeted,<br>And right perfection wrongfully disgraced,<br>And strength by limping sway disabled,<br>And art made tongue-tied by authority,<br>And folly, doctor-like, controlling skill,<br>And simple truth miscalled simplicity,<br>And captive good attending captain ill;<br>Tired with all these, from these would be I gone,<br>Save that, to die, I leave my love alone.</p>



<blockquote class="wp-block-quote"><p>"Açıkça görülüyor ki,&nbsp;Can Yücel&nbsp;en yakın olduğu zaman bile&nbsp;Shakespeare’in dediğini demiyor; ama en uzak olduğu zaman bile onun anlattığını anlatıyor.</p><cite><em>Memet Fuat,Türk eleştirmen, yazar, yayıncı ve eğitimci</em></cite></blockquote>



<blockquote class="wp-block-quote is-style-default"><p>Can yücel, kendi şiirini söyler gibi çevirmiş bu Her Boydan şiirleri. Ha sen söylemişsin ha ben der gibi. İnsanın insanla kaynaşması her zaman güzeldir, şairin şairle kaynaşmasında bir başka sıcaklık, bir başka aydınlık oluyor: bir dille iki dilin tadını almak, bir canla iki canın sevincini duymak gibi bir şey. Bu cömert kaynaşma, bu dünyanın türküsünü benimseme gücü yok mu (ki Can Yücel’de var) o şairi şair eden tılsımı onda aramalı.</p><cite><em>Sabahattin Eyüboğlu, Türk yazar, çevirmen ve akademisyen</em></cite></blockquote>



<p class="has-small-font-size"><em>Kaynakça:</em><br>William Shakespeare, Tüm Soneler, Çeviren ve Hazırlayan Talât Sait Halman, Cem Yayınları, 1993<br>Eyüboğlu Sabahattin, Can Yücel'in Şiir Çevirileri, Yeni Ufuklar Dergisi, Sayı:66, 1957<br>Can Yücel, Her Boydan-Dünya Şiirinden Seçmeler, Türkiye İş Bankası Kültür Yayınları, 2018</p>



