UPDATE posts SET content = $tag2$<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://i2.wp.com/www.loveinartsz.com/wp-content/uploads/2020/05/800px-Édouard_Manet.jpg?fit=659%2C1024&amp;ssl=1" alt="Edouard Manet" class="wp-image-1894" width="269" height="417"/></figure>



<p class="has-text-align-justify">Edouard Manet 23 Ocak 1832' de Paris' te doğmuştur. Ailesi onu hukuk alanında desteklese de onun ilgisi hep sanataydı. Edouard, babasının isteğiyle Deniz Harp Okuluna başvurmuş fakat sınavı kazanamamıştır.  Daha sonra  Deniz Ticaret Filosu' na girmiş ve 1948 yılında Brezilya' ya doğru yola çıkmıştır. Bu yolculukta gördüklerine oldukça şaşırmış ve mektuplarında ''Bu ülkede bütün zenciler köle; hep mağdur durumdalar; beyazların onların üzerindeki güvü inanılmaz; bizim gibi insanlara iğrenç gelen bir köle pazarı gördüm.'' diye yazmıştır.</p>



<p>Manet bir yıl sonra ülkesine döndüğünde babasını ikna ederek sanatçı olma yoluna girmiştir. Manet Paris' te bulunan Thomas Couture adlı sanatçının stüdyosuna gitmeye başlamıştı. </p>



<p>Bu dönemde arkadaş çevresi Paris' in sofistike hayatında yaşayan edebiyatçılar ve sanatçılardan oluşmuştu. </p>



<p>19. yüzyıl Fransız sanatı tema için Fransız akademisyenlerlerin beğendiği klasik yaklaşım yerine Byron gibi çağdaş ve egzotik edebi referanslara dönen Romantik ressam Eugene Delacroix' in öncülüğündeydi.  </p>



<p>Manet kendini Empresyonist olarak görmese de Empresyonist devrimi yönlendiren Monet, Sisley, Renoir gibi sanatçılar onun desteğini almıştır. </p>



<p>Manet tablolarının Salon tarafından kabul edilmesini ve olumlu eleştiri almasını çok istiyordu.  Yaptığı Le Dejeuner sur l' Herbe tablosu onun  Salon tarafından kabul edilmemekle birlikte bir skandala imza attı. Tablo Salon' un alternstifi olan Salon des Refuses'te sergilenmişti. Alışılagelmişin dışında yapılan bu resimdeki sorun kadının çıplak erkeklerin ise giyinik olmasıydı. Resimdeki Parisli adamlar klasik bir Parisli olarak karşımıza çıkıyordu fakat kadın çıplaktı. Manet gerçek insanları modern bir dünyada resmederek geleneklere karşı çıkmıştı.  Ernest Chesneau, Manet' burjuvaziyi şaşırtarak şöhret kazanmaya çalışmakla suçlamıştır. Manet ise eski bir resim olsa adamları da kadın gibi nü çizebileceğini söylemiştir. Manet' in ün kazanmasını bu resim sağlamıştır. </p>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/05/800px-Edouard_Manet_-_Luncheon_on_the_Grass_-_Google_Art_Project.jpg" alt="Kırda Öğlen Yemeği" class="wp-image-1892" width="559" height="434"/><figcaption>Kırda Öğlen Yemeği</figcaption></figure>



<p>Manet 30 Nisan 1883 tarihinde hayatını kaybetmiştir. Bu tarihe kadar sanat tarihine bir çok eşsiz eser bırakmıştır.</p>



<p class="has-small-font-size"><em>Kaynak:  Büyük Ressamlar, Manet, Beta Yayıncılık, 2015, İstanbul</em></p>$tag2$ WHERE slug = 'manet-in-hayati';
UPDATE posts SET content = $tag2$<blockquote class="wp-block-quote"><p><em>“Elde ettiğim zenginlik doğadan geliyor, doğa benim ilham kaynağım.”</em> </p><cite><em>– Claude Monet</em></cite></blockquote>



<p><br>Resimle ilgileniyorsanız Monet’nin “<em>Nilüferler</em>”inden birine mutlaka denk gelmişsinizdir. <em>Nilüferler </em>serisi Monet’nin en ünlü ve özellikle yaşamının son dönemine damga vurmuş eserleridir.</p>



<p>Sanat okulunda aldığı geleneksel sanat derslerinde hayal kırıklığı yaşayan Monet sınıflarla sınırlı kalmayı hiçbir zaman sevmedi. Fransız manzara ressamı Eugene Boudin ile tanıştıktan sonra tüm kariyerini etkileyecek açık havada resim yapma anlayışını benimsedi. Aynı düşünceleri paylaştığı bir grup ressamla İzlenimcilik (empresyonizm) akımının öncüsü oldular. Monet için doğayı resmetmek bir tutkuydu. Işık geçişlerini, yansımaları farklı boyalarla tuvaline aktararak manzaranın özünü yakalamayı ve izleyenlerde de aynı izlenimi uyandırmayı hedeflemiştir.</p>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/05/800px-Claude_Monet_-_Nymphéas_W1852_-_Musée_Marmottan-Monet-1.jpg" alt="" class="wp-image-1971" width="367" height="273"/></figure>



<blockquote class="wp-block-quote"><p><em>“Yöntemler değişir ama sanat aynı kalır; çünkü sanat doğanın etkili ve duygusal bir biçimde yorumlanmasıdır.” </em></p><cite><em>– Claude Monet</em></cite></blockquote>



<h3><strong><em>Nilüferler</em>’in ortaya çıkışı</strong></h3>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/05/04Solomon-jumbo.jpg" alt="" class="wp-image-1952" width="444" height="331"/><figcaption>1920'de son büyük <em>Nilüferler</em>’i resmederken stüdyosunda Monet. <em>“Mad Enchantment”</em>dan&nbsp;<br></figcaption></figure>



<p>Monet yaşadığı birçok yerde bir nevi açık hava stüdyosu olarak kendi bahçelerini oluşturmuştur. 1883 yılında maddi sıkıntılarını aştıktan sonra Paris’in dışında küçük bir kasaba olan Giverny’de bahçeli bir eve yerleşti. Orada nilüferlerle dolu olan ve üzerinden Japon tarzı bir köprü geçen devasa bir yapay gölet yaptırdı. Göletin çevresini söğütler, fundalıklar, bambu ağaçları ve egzotik çiçeklerle kapladı. Bahçenin yan tarafında cam duvarlı bir stüdyo inşa etti ve odanın etrafında serbestçe dönebileceği tekerlekli bir şövale kurdu.&nbsp;Orada nilüferlerini, söğüt yapraklarının suyun yüzeyindeki yansımalarını, Japon tarzı köprüyü&nbsp;ışığın değişimini esas alarak günün birçok saatinde ve birçok farklı şekilde resmetti.&nbsp;</p>



<div class="wp-block-group">
<figure class="wp-block-gallery has-nested-images columns-default is-cropped">
<figure class="wp-block-image size-large"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/05/water-lilies-and-japanese-bridge-claude-monet.jpg" alt="" class="wp-image-1954"/></figure>



<figure class="wp-block-image size-large"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/05/800px-Claude_Monet_-_Water_Lilies_-_Google_Art_Project.jpg" alt="" class="wp-image-1958"/></figure>



<figure class="wp-block-image size-large"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/05/800px-Monet_-_Water_Lilies_1907_19.170.jpg" alt="" class="wp-image-1960"/></figure>



<figure class="wp-block-image size-large"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/05/claude-monet-water-lilies-9_1000x.jpg" alt="" class="wp-image-1962"/></figure>



<figure class="wp-block-image size-large"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/05/0f802b01fea5b0416900e789c63a4cb3.jpg" alt="" class="wp-image-1963"/></figure>
</figure>
</div>



<blockquote class="wp-block-quote"><p><em>“Bahçem en güzel şaheserim.” </em></p><cite><em>– Claude Monet</em></cite></blockquote>



<p>1914'te dönemin başbakanı ve Monet’nin arkadaşı Georges Clemenceau sanatçıyı, nilüferleri gösteren bir dizi büyük tuval üzerinde çalışması için teşvik etti. O andan itibaren 1926’daki ölümüne kadar, Monet'in ana meşguliyeti bu dev tablolar oldu.Giderek artan karamsarlığı, yaptığı resimleri yetersiz bulması, gözlerindeki bozukluk gibi birçok sebeple tabloları tamamlaması çok uzun sürdü. <em>Grande Décoration</em> olarak adlandırdığı büyük nilüfer resimlerini Fransa ulusuna armağan etti. Tablolar bugün hala Paris’deki Musée de l'Orangerie’de sergilenmektedir. Tabloların yapım aşaması, Monet’nin o dönemde yaşadığı sorunlar, çevresine karşı olumsuz sayılabilecek tutumlarının ele alındığı Ross King tarafından yazılmış “<em>Mad Enchantment</em>” adlı kitap bu şaheserlerin ardındaki bazı gerçeklere ışık tutmaktadır.&nbsp;</p>



<p>Monet’nin bu son tablolarında çiçekleri ve suyu tasvir eden fırça darbeleri ve kullandığı renkler, erken İzlenimci tekniklerden önemli ölçüde farklıdır; zaman zaman su yüzeyinin güzelliğini uyandırmak için dışavurumculuğun tutkulu yoğunluğuna ulaşırlar. Gerek kompozisyonun basitleştirilmesi, gerek kontur ve sınırların kaybolması, gerekse saf ve canlı renklerin kullanılması ile gözün tek bir yere odaklanmasını reddeden bu eserler aslında soyut resme giden yolu açmıştır. Bu özellikleri ile kendisinden sonra gelen Post-empresyonist, Ekspresyonist ve Soyut dışavurumcu hareketleri etkilemiştir. Özellikle 1950’lerde Amerika'daki soyut akımın öncüleri Jackson Pollock ve Mark Rothko’nun, Monet’nin bu tablolarından ilham aldığı söylenir.</p>



<figure class="wp-block-gallery has-nested-images columns-default is-cropped">
<figure class="wp-block-image size-large"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/05/Claude_Monet_-_The_Water-lily_Pond_-_Google_Art_Project.jpg" alt="" class="wp-image-1964"/></figure>



<figure class="wp-block-image size-large"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/05/Reflections_of_Clouds_on_the_Water-Lily_Pond-1.jpg" alt="" class="wp-image-1966"/></figure>



<figure class="wp-block-image size-large"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/05/1280px-Claude_Monet_-_Water_Lilies_-_Google_Art_Project_431238.jpg" alt="" class="wp-image-1956"/></figure>
</figure>



<p>1907 yılında görme sorunları yaşamaya başlamış olan Monet 1923'te<a href="https://aklinizikesfedin.com/degisim-korlugu-gorme-yeteneklerinizi-abartmak/" class="aioseop-link"> </a>neredeyse tamamen kör olmuştu. Bu dönemlerde resimlerinde de genel bir kırmızılık hakimdi ve görüntüler ciddi olarak bozulmuştu.&nbsp;1923’te Clemenceau’nun ısrarları sonucu katarakt ameliyatı oldu. Ancak 1926’da, 86 yaşındayken çok sevdiği Giverny’deki evinde akciğer kanserinden yaşamını yitirdi. </p>



<p>Monet hayatının son 30 yılını özellikle nilüferleri resmetmeye adamıştı. Bizlere bugün hala dünyanın en güzel doğa ve çiçek resimleri olan 250’nin üzerinde nilüfer tasviri bırakmıştır.&nbsp;</p>



<p></p>



