UPDATE posts SET content = $tag2$<p class="has-text-align-justify">Türk edebiyatında ampirik okur denildiğinde akla gelecek ilk hikâye Kambur Hafız ve Minare’dir. Hikâyeye geçmeden önce “ampirik okur” kimdir onu açıklamak istiyorum. Ampirik okur -benim için- okuyan, okuduğunu anlamayan, yanlış anlayan okurdur. Yanlış anladığına göre doğru bir okurdur demek çok da mümkün olmaz. Goethe’nin Genç Werther’in Acıları romanı ilk çıktığı dönemde okuyucular tarafından çok beğenilmiş ve Werther ile okuyucular kendilerini bütünleştirmiştir ki o dönem bu kitabı okuyan gençler tıpkı Werther gibi intihar etmeye başlamıştır. Kitap birçok ülkede yasaklanmış ve hatta etkisi o kadar fazla olmuş ki Tıp literatürüne bile girerek kitabın yol açtığı etkiye <strong>Werther Etkisi</strong>&nbsp;adını verilmiş.</p>



<div class="wp-block-image"><figure class="aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/goethe.jpg" alt="" class="wp-image-2069" width="552" height="414"/></figure></div>



<p class="has-text-align-justify">Okuyucuların Werther’ i örnek almasının sebebi onun kurgusal bir karakter olduğuna kanaat getirememeleridir. Bu tıpkı televizyon başındaki büyükannelerimizin dizideki karaktere “Oraya girme be kızım” diye bağırması gibi bir durum. “Umberto Eco, ‘<em>Anlatı Ormanında Altı Gezinti</em>’ adlı kitabında: ‘<em>Okur, bir anlatıyı takip ederken metinle öyle ya da böyle iş birliği yapar. En azından yazarın bıraktığı boşlukları kendince doldurur.</em>’” diyor.&nbsp; Yani okur Yazarın ona açmış olduğu kapıdan girerek anlatıya katılır. Fakat bu anlatının kurgusal olduğunun bilincindedir. Bilincinde olmalıdır. Bu durumun yani romanın kurmaca bir tür olduğunun bilincinde olan okura "Örnek Okur" diyoruz. "<strong>Örnek Okur </strong>oyunda kalmayı bilen kimsedir, metinle doğar, o üsluba uyma yeteneği gösterir, yani başından itibaren kendisine önerilen metne dayalı oyunun kurallarını kabul etmekle bin yıl sonra bile olsa o kitabın ideal okuru olacak olan kişidir."</p>



<p class="has-text-align-justify">&nbsp;Kambur Hafız ve Minare hikâyesinde Hafız Ali karakteri; cahil, okuduğunu anlamayan kişilerin temsilidir. Hatta okuduğunu anlamamanın da ötesinde okuma yazması dahi yoktur, hikâyeyi başka birine okutmuştur. Okuyan kişinin “<em>Hem sonu sonu bir hikâye bu, uyduruk bir şey’</em>’ demesine rağmen Hafız Ali, hikâyenin yazarına ulaşmak ister. Hafız Ali’ nin bu her şeye inanan kendi hikâyesini yazdığını düşünen hali, Umberto Eco’nun Anlatı Ormanlarında Altı Gezinti isimli kitabındaki bir pasajı bize hatırlatıyor: <em>‘’Foulcault Sarkacı adlı romanımı yayımladıktan sonra, yıllardır görmediğim eski bir çocukluk arkadaşım bana şunları yazdı: “Sevgili Umberto, sana yengem ile amcamın dokunaklı öyküsünü anlattığımı anımsamıyordum; ancak bu öyküyü romanın için kullanmış olmanı doğru bulmuyorum.”</em>&nbsp; Bu kısa mektuptan sonra Eco, arkadaşına yanıt vererek onların kendi amcası ve yengesi olduğunu yazmıştır ve şöyle söylemiştir: “<em>Öyküyle öylesine özdeşleşmişti ki, kendi amcası ile yengesinin başından geçen olayları romanda gördüğüne inanmıştı.” </em>Burada Öyküyle özdeşleşmek kelimesi dikkatimi çekti. Neden bir insan öyküyü bu kadar benimser. Öyküdeki karakterlerin kendisi, tanıdıkları olduğunu ya da Genç Werther’i okuyup intihar etmeyi neden düşünür ya da neden intihar eder? Roman ya da öykü dünyasının kurmaca olduğunu bilmemesinden mi kaynaklanıyor bu durum yoksa psikolojik bir nedenden dolayı mı? Bu konular hakkında yapılan araştırmalar elbette vardır. Bence bu soruların cevabı iki türlüde verilebilir. Okuma alışkanlığı olmayan, yanlış okuyan, romanın hayal denizinde boğulan kişiler romanın kurmaca bir tür olduğunu unutuyor ya da bilmiyordur ya da bu durumu psikolojik olarak açıklamak doğru olacaktır. Soyut olanı somut olandan ayırma yetilerini kaybetmektedirler.</p>



<p>&nbsp;Hikâyeye geri dönecek olursak. Ali, cahil bir karakterdir. Üstte belirttiğim gibi romanın kurmaca bir tür olduğunu anlamamaktadır ve hikâyenin kendi hayatını yansıttığını düşünür. Minareye her çıkışında hikâyede Kambur Hafız’ın gördüklerini görmeye başlamıştır. Ali’nin okunan hikâyedeki karakterin gördüklerini görmeye başlaması kendini kahramanın yerine koymasının sebebidir. Ali artık gerçek ile hayali ayırt edememekte ve kafasını iyice bulandırmaktadır. Bu duruma çözüm olarak İstanbul’a giderek yazara hesap sormaya karar vermiştir. Yazarla ilk karşılaşmalarında yazar “Al işte bir Molla Kasım daha’’ şeklinde bir cümle kurmuştur. Yunus Emre ve Molla Kasım kıssasından Molla Kasım’ın Yunus’un şiirlerini yanlış anlayarak suya; balıklara, yakarak; havaya savurduğunu biliyoruz. Yani Molla Kasım’da bir ampirik okurdur ve Yunus bunun bilincindedir. Hikâye içinde hikâye yazan Mustafa Kutlu ampirik okur durumunun farkında olduğunu burada önümüze koymaktadır. Ali ile Mustafa Kutlu konuşurken Ali hikâyeden “<em>benim hikâyem’’</em> şeklinde bahseder. Kendini Kambur Hafız’ın yerine o kadar koymuştur ki hikâyedeki kahramanın kendisi olduğuna ikna olmuştur. Yazar, Ali'ye hikâye olduğunu anlatsa da maalesef başarısız olur ve tamam değiştireceğim diyerek Ali'yi ikna eder. Burada önemli bir detay var. Ali, yazarın yanından ayrıldıktan sonra artık İpragaz arabası, kiraz ağacı, patlıcan tava vs. artık görmemektedir. Bu durum Ali’nin hikâyenin kendine ait olduğunu düşünmesi ve değişeceğine inanmasından kaynaklanmaktadır. Yazarın yanından ayrılırken hala <em>“neyi nasıl yazacağını anladı teres”</em>diye düşünmekte ve hala kurgu olduğunu anlamamaktadır.&nbsp;</p>



<div class="wp-block-image"><figure class="aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/KamburHafız-Tuhaf.jpg" alt="" class="wp-image-2070" width="568" height="493"/><figcaption>Tuhaf Dergi, Haziran-2017</figcaption></figure></div>



<p>Ali cahil olmasaydı çok okuyup çok yazsaydı, romanın kurgu olduğunu bilseydi bu durumla karşılaşır mıydı? Muhtemelen hayır. Fakat kendisine benzetmekten, acaba diye düşünmekten geri kalmazdı. Örnek okur için oyunda kalmayı bilen kimsedir demiştik. Ali durumun farkında olsaydı bu oyunu devam ettirebilirdi. Yazarın karşısına hesap sormaya değil, onunla tesadüf hakkında konuşmak ve belki eklemeler yapmasını istemek için çıkabilirdi. Ampirik okurun hayatında bir şeylerin eksik olduğu okurdur. Örneğin Madam Bovary’ nin heyecan peşinde koşma sebebi okuduğu romanlardaki hayatla kendisini kıyaslayarak kendi hayatının heyecanının eksik olduğunu düşünmesidir. Kendini bir romanda gibi hayal eder ona göre yaşamak ister. Madam Bovary’ de, Ali’ de ne kadar kurgu karakterler olsalar da onlar gibi bu durumu yaşayan insanların temsilidir. Sonuçta Welther’ in acılarına kapılıp intihar edenler ne yazık ki mevcuttur. Ampirik okur, kurmaca olanı alın yazısı sayar. Onunla yaşar. Romanı okurken onun sayfalarında seyahat etmek yerine romanı yaşar, yaşamayı tercih eder. Ampirik okur zor ikna edilir hatta bazen ikna bile edilemez. Aslında ampirik okurun yaşadığı durum tamamen bir rastlantıdan doğmuştur. Kambur bir hafız elbette olabilir, aynı acıları paylaştığımız insanlar, aynı olaydan aynı derecede etkilendiğimiz insanlar olabilir. Bu durum romanlara, öykülere, şarkılara, filmlere konu olabilir. Bu durumda yapılması gereken Ali gibi yazarın yakasına yapışmak değil onun oyununa dâhil olmaktır.</p>



<h6><strong><em>Kaynakça:</em></strong></h6>



<p><em>Anlatı Ormanlarında Altı Gezinti, Umberto Eco, Can Yayınları, 2013.</em></p>



<p><em>Okur Türleri, Füsun Kavrakoğlu, 2015</em></p>$tag2$ WHERE slug = 'kim-bu-ampirik-okur';
UPDATE posts SET content = $tag2$<div class="wp-block-image"><figure class="aligncenter size-large is-resized"><img src="https://i1.wp.com/www.loveinartsz.com/wp-content/uploads/2020/06/Leonardo-Akil-Adam-Hayranlığı-1-scaled.jpg?fit=1024%2C971&amp;ssl=1" alt="" class="wp-image-2074" width="443" height="420"/><figcaption>Adoration of the Magi</figcaption></figure></div>



<p>Hz. İsa doğduğunda Doğu'daki üç kral Bethlehem Yıldızı'nın rehberliğinde Hz. Meryem'e gelerek Hz. İsa'ya hediyeler sunmuşlardı. Bu resim tam olarak bu olayı anlatıyor yani İncil'den bir kesit.</p>



<p>Bu resmin önemli özelliklerinden birisi, Leonardo'nun çalışma tarzını görebilmemiz. Bu resimle birlikte Leonardo'nun sadece bir ressam değil bir bilim adamı olduğunu da hatırlamak mümkün. </p>



<div class="wp-block-image"><figure class="aligncenter size-large is-resized"><img src="https://i0.wp.com/www.loveinartsz.com/wp-content/uploads/2020/06/Leonardo-Akil-Adam-Hayranlığı1.jpg?fit=692%2C1024&amp;ssl=1" alt="" class="wp-image-2075" width="330" height="487"/></figure></div>



<p>Resmin sağ tarafında (üstte) neredeyse iskelete benzeyen figürler görüyoruz. Leonardo, firgürlerin ilk önce iskeletlerini daha sonra kıyafetlerini çizerek renklendirme işlemini yapmaktadır. Sağ tarafta bulunan bu grup filozofları temsil etmektedir. </p>



<div class="wp-block-image"><figure class="aligncenter size-large is-resized"><img src="https://i1.wp.com/www.loveinartsz.com/wp-content/uploads/2020/06/WhatsApp-Image-2020-06-07-at-22.41.19.jpeg?fit=1024%2C725&amp;ssl=1" alt="" class="wp-image-2077" width="518" height="366"/></figure></div>



<p>Resmin tam ortasında Hz. Meryem ve çocuk İsa'yı görmekteyiz. Hz. Meryem'in önünde ise üç kral var. Bu üç krala "magi" ya da "akil adam" denilmektedir. Hz. Meryem ve üç akil adam üçgen bir form oluşturmuş. Üçgen form, Yüksek Rönesans döneminde sıkça kullanılan bir biçim olmuştur.</p>



<figure class="wp-block-gallery columns-2 is-cropped"><ul class="blocks-gallery-grid"><li class="blocks-gallery-item"><figure><img src="https://i0.wp.com/www.loveinartsz.com/wp-content/uploads/2020/06/Leonardo-Akil-Adam-Hayranlığı4.jpg?fit=1024%2C678&amp;ssl=1" alt="" data-id="2079" data-full-url="https://i0.wp.com/www.loveinartsz.com/wp-content/uploads/2020/06/Leonardo-Akil-Adam-Hayranlığı4.jpg?fit=2444%2C1619&amp;ssl=1" data-link="https://www.loveinartsz.com/?attachment_id=2079#main" class="wp-image-2079"/></figure></li><li class="blocks-gallery-item"><figure><img src="https://i0.wp.com/www.loveinartsz.com/wp-content/uploads/2020/06/Leonardo-Akil-Adam-Hayranlığı3.jpg?fit=1024%2C897&amp;ssl=1" alt="" data-id="2080" data-full-url="https://i0.wp.com/www.loveinartsz.com/wp-content/uploads/2020/06/Leonardo-Akil-Adam-Hayranlığı3.jpg?fit=1855%2C1625&amp;ssl=1" data-link="https://www.loveinartsz.com/?attachment_id=2080#main" class="wp-image-2080"/></figure></li></ul></figure>



<p>Bu resim oldukça, yoğun ve karmaşık. Sağ üst köşede bir mücadelenin izleri ve karşı karşıya gelmiş iki at görüyoruz. Sol üst köşede de klasik dönem tarzındaki mimari bir yapı görmekteyiz. Bu yapının merdivenleri lineer bir perspektifte çizilmiş. </p>



<p>Hz. Meryem gözlerini oğlundan ayırmıyor. Gözleri oğlunun başına ve oradanda oğlunun kolunun uzandığı noktaya doğru bakıyor.</p>



<div class="wp-block-image"><figure class="aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/WhatsApp-Image-2020-06-07-at-22.51.04.jpeg" alt="" class="wp-image-2081" width="340" height="381"/></figure></div>



<p>Resimdeki bu üçgen form, lineer çizim ve sisli görünüm bize Leonardo'nun tekniği ve çalışma tarzını ortaya koyuyor. Yüksek Rönesans; denge, istikrar, sükunet ve mükemmeliyet gibi ögeler bu dönem sanatının tipik özelliklerindendir. Bakmakta olduğumuz çizim, asıl resmin altında bulunuyor. Bu alt çizimde kullanılan önemli bir teknik var: ''sfumato'' İtalyanca'da 'sisli' anlamını taşımaktadır. Leonardo'nun kullanmış olduğu bu teknik sayesinde figürler bir bütün olarak gözükmektedir.</p>



