UPDATE posts SET content = $tag2$<p class="has-text-align-justify">Sevim Burak Türk Edebiyatı’nda 1950 kuşağının sıra dışı öykücülerindendir. Yanık Saraylar, Afrika Dansı, Palyaço Ruşen adlı öykü kitapları ile edebiyat dünyasında uzun süre konuşulmuştur. Hikaye yazmanın hayatını, yaşadıklarını haykırmanın bir yöntemi olduğunu dile getiren Sevim Burak ,öykü yazmanın kendisi için bir çeşit sorumluluk olduğunu sık sık ifade etmiştir.</p>



<p class="has-text-align-justify">Sevim Burak’ın eserlerinde sıkça toplumsal düzeni, sıradanlaşan aktiviteleri, bireyler üzerinde baskı kurmayı hedefleyen tüm yapıları kurnaz bir şekilde eleştirdiği görülür. Bu noktada özellikle yıllarca baskılara maruz kalan, ötelenen ve toplumsal eşitsizliklerin arasında kıvranan kadınların isyanını sık sık eserlerinde işlemiştir. Ana akım eserlerin birçoğunda görülen standart zaman algısı erkek otorite etrafında şekillenirken Sevim Burak yazını kadınların deneyimleri, zamanın neresinde oldukları ve zamanı nasıl yönettikleri doğrultusunda şekillenir bu açıdan bakıldığında geleneğin ötesinde, farklı bir pencere açar. Öyle ki düzenin içinde düzen kurmayı hedefleyen yazınların aksine Sevim Burak kuralsız, düzensiz, kesik ve yer yer şiirsel bir dille kadın kahramanların etrafında şekillenen yazını ön plana çıkarır. Tüm bunları yaparken okunma ve anlaşılma kaygısı gütmez çünkü onun eserleri yalnızca kendi otoritesine seslenir. Kendinden başka otoriteye çağrıda bulunma ya da o otorite tarafından anlaşılma arzusu taşımaz. Bu nedenle yazıları ataerkil söylemler taşıyan resmi tarih anlatılarına benzemez ve bu anlatıların eksiklerini ortaya koyma, ifşa etme özellikleri taşır.</p>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/05/SEVIMBURAK-e1561756056320.jpg" alt="Sevim Burak" class="wp-image-1974" width="292" height="419"/></figure>



<p class="has-text-align-justify">Sevim Burak öykülerindeki kadınlar ortak bir kaderi paylaşırlar. Erkek egemen toplumsal düzenin dil ve davranış kodlarına yabancı kaldıkları gibi bu düzende ortaya çıkan zaman algısına da yabancı kalmışlar ve resmi tarihin, toplumun bildiği zaman algısının da dışında kalmışlardır.</p>



<p class="has-text-align-justify">&nbsp; Hikâyelerdeki kadınların ne kadar uğraşırlarsa uğraşsınlar toplumun zaman ve tarih algısına yetişemedikleri ve bunu bir savaş gibi gördükleri anlaşılır. Kadın karakterlerin bu inanılmaz çabası asla mutlu sonla bitmez. Mutlu sonun olmayışı da Sevim Burak’ın kendi hayatı ile değerlendirildiğinde henüz kendini bulamamış bir kadının zorlu çırpınışları olarak değerlendirilebilir. Kadının zaman sahnesinde mutlak doğruya ulaşabilmesi erkek egemenliğin ona sunduğu imkânlar dâhilinde kısıtlı kalmaktadır. Zamana dâhil olabilmek kendi hayatından uzaklaşarak topluma karışabilmek yani kadın olarak hak ettiği noktaya gelebilmek anlamını taşımaktadır. Kadınların bu savaşı sessizce sürdürmesi, kendini kabul ettirmeye çalışması bir benlik arayışı mı yoksa kadının kendi benliğinde kaybolması mı? Bu konunun tartışmaya açık olduğu kesindir.</p>



<p class="has-text-align-justify">Toplumun direttiği bu zamanın içinde sıkışıp kalan kadının çaresizliği ve acizliği küçük mekânlara sıkışması ile daha da bunaltıcı bir hal alır. Kadının kendine ait bu küçük, zamansız dünyasında sorgulamalar ile geçen bir akış vardır. Sevim Burak yer yer şiirler kullanarak kadınların duygusal yönünü öykülerinde ifade etmeye çalışsa da temelde kadın karakterlerin elindeki tek silah bu şiirlerdir. Kadınların sürekli bir yarış halinde oluğu öykülerde kadının daima yetişmesi gereken bir yer, kısıtlı bir zaman ve onu engelleyen, hedefine ulaşmasını istemeyen erkek karakterler vardır. Tüm bu dağınıklığın ve savaşın içinde kendini arayan kadınlar için Sevim Burak öyküleri ilginç bir gerçeklik taşır. Okuyucu gerçekten hayatı ile bütünleştirerek yaklaşırsa muhakkak hayatından tatlar bulacaktır. Çoğu zaman yaşadığımız ama itiraf edemediğimiz derin buhranlar bu öykülerde tüm çıplaklığı ile gözler önüne serilir. İşte tam olarak kadın ruhunun derinliklerinde gezinen bir öykücü olarak karşımıza çıkan Sevim Burak öykülerinin gücünü kendi ve kendi gibi olan tüm kadınların yaşanmışlıklarından alır.</p>



<p class="has-text-align-right"><strong>Kevser Merve Karaboğa</strong></p>$tag2$ WHERE slug = 'sevim-burak-yazininda-zaman-ve-tarihin-icinde-savasan-kadinlar';
UPDATE posts SET content = $tag2$<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://i0.wp.com/www.loveinartsz.com/wp-content/uploads/2020/05/22.jpg?fit=762%2C1024&amp;ssl=1" alt="" class="wp-image-2029" width="619" height="832"/></figure>



<p>Yunan mitolojisinden Apollon ve Daphne’nin hikayesi birçok sanatçıya ilham olmuştur. Şüphesiz ki en bilinen ve en görkemli eserlerden birisi de Bernini’nin Apollon ve Daphne’sidir. Barok dönemin hareketli, dramatik ve güçlü figürlerinin etkisini gördüğümüz bu heykel 1625 yılında Bernini ve yardımcısı Giuliano Finelli tarafından tamamlanmıştır. 243 cm uzunluğundaki mermer heykel Roma’daki Galleria Borghese’de sergilenmektedir. [1] Apollon’un Daphne’yi yakalama anının betimlendiği eserde olayın yaşandığı anın hissi, figürler neredeyse harekete geçecekmiş görünümü verilerek etkileyici bir şekilde yansıtılmıştır. Daphne’nin yüzündeki endişe ve korku oldukça gerçekçidir. Daphne'nin defne ağacına dönüşümü; ağacın yapraklarının, dallarının ve gövdesinin Daphne'nin vücuduna uyumla karıştığı bu sahnede en ince detaylarına kadar tasvir edilmiştir. </p>



<div class="wp-block-jetpack-tiled-gallery aligncenter is-style-rectangular"><div class="tiled-gallery__gallery"><div class="tiled-gallery__row"><div class="tiled-gallery__col" style="flex-basis:62.62883%"><figure class="tiled-gallery__item"><img alt="" data-height="950" data-id="2030" data-link="https://www.loveinartsz.com/?attachment_id=2030#main" data-url="https://www.loveinartsz.com/wp-content/uploads/2020/05/R1327.jpg" data-width="749" src="https://i1.wp.com/www.loveinartsz.com/wp-content/uploads/2020/05/R1327.jpg?ssl=1" data-amp-layout="responsive"/></figure></div><div class="tiled-gallery__col" style="flex-basis:37.37117%"><figure class="tiled-gallery__item"><img alt="" data-height="405" data-id="2034" data-link="https://www.loveinartsz.com/?attachment_id=2034#main" data-url="https://www.loveinartsz.com/wp-content/uploads/2020/06/lead_720_405.jpg" data-width="720" src="https://i1.wp.com/www.loveinartsz.com/wp-content/uploads/2020/06/lead_720_405.jpg?ssl=1" data-amp-layout="responsive"/></figure><figure class="tiled-gallery__item"><img alt="" data-height="563" data-id="2033" data-link="https://www.loveinartsz.com/?attachment_id=2033#main" data-url="https://www.loveinartsz.com/wp-content/uploads/2020/06/30558377963_560ac5e7a3_b.jpg" data-width="1023" src="https://i2.wp.com/www.loveinartsz.com/wp-content/uploads/2020/06/30558377963_560ac5e7a3_b.jpg?ssl=1" data-amp-layout="responsive"/></figure><figure class="tiled-gallery__item"><img alt="" data-height="1000" data-id="2035" data-link="https://www.loveinartsz.com/?attachment_id=2035#main" data-url="https://www.loveinartsz.com/wp-content/uploads/2020/06/image-asset.jpeg" data-width="1000" src="https://i2.wp.com/www.loveinartsz.com/wp-content/uploads/2020/06/image-asset.jpeg?ssl=1" data-amp-layout="responsive"/></figure></div></div></div></div>



<p>Heykelin esin kaynağı olan hikaye şöyledir:&nbsp;</p>



<p>“Apollon güneşin, ışığın, şiirin, müziğin, okun ve, kehanetin tanrısıdır. Daphne ise nehir tanrısı Peneus’un kızı, bakirelik yemini etmiş bir su perisidir. Günlerden bir gün Apollon gökyüzünde gezerken kendisi gibi okçu olan aşk tanrısı Eros ile karşılaşır. Eros o sırada insanları aşık etmek için kullandığı ok ve yayı ile ilgilenmektedir. Yakın zamanda bir ejderha öldürmüş ve zaferinden dolayı kibirlenmiş olan Apollon Eros’u küçümseyen sözler söyler. Eros ise Apollon’a bir ders vermeye karar verir. Apollon bir gün ormanda yalnız başında dolaşmakta olan güzeller güzeli su perisi Daphne'yi görür. Tanrıçaları bile kıskandıran bir güzelliğe sahip olan su perisini seyretmeye başlar. İşte o sırada Eros iki ok hazırlar: Apollan’a bir ok fırlatıp, onu tam kalbinden vurarak Daphne’ye aşık olmasını sağlar. Diğer oku ise Daphne’ye fırlatarak onun aşk kapılarını sonsuza dek kapatır. Apollon Daphne’ye yaklaşır ama Daphne var gücüyle kaçmaya başlar. Apollon çaresizlik içinde Daphne’nin peşinden koşar. Artık daha fazla kaçamayacağını anlayan Daphne babası Peneus’a seslenir: “<em>Beni yaralayan güzelliği yok et ya da hayatımı mahveden bedeni değiştir.</em>"[2] (Kimi kaynaklara göre <em>‘Ey toprak ana, beni ört beni sakla beni koru!’</em> diye yalvarır [3]) Babası onun yakarışına yanıt verir. Daphne’nin bedeni kabuk bağlar; saçları yapraklara; ince, narin kolları uzayıp dallara dönüşür. </p>



<p>Aşkını kalbinde taşımaya kararlı olan Apollon ise Daphne’yi onurlandırmak için şu sözleri söyler: “<em>Madem gelinim olmayacaksın, öyleyse Defne ağacım olmalısın. Seninle saçlarım çelenklenecek, lirim sen, oklarım sen olacaksın. Neşeli sesler zaferlerini alkışladığında Romalı generallerin yanında olacaksın, Kapitol onların uzun alaylarına tanıklık edecek. Augustus'un kapısının önünde sadık bir gardiyan olup, meşeden yapılmış tacına göz kulak olacaksın. Ve tıpkı kesilmemiş saçlarımla hep genç kalan başım gibi, sen de ölmeyen yapraklarının güzelliğini giyeceksin.” </em>[2]&nbsp; </p>



<p>Günümüzde zafer kazanmış Roma hükümdarlarının tasvir edildiği birçok sanat eserinde (öyle ki neredeyse Jul Sezar'la özdeşleşmiştir) ve çeşitli Apollon heykellerinde defne yapraklı tacı görürüz.  [5]</p>



<p>Rivayet odur ki bu olayın yaşandığı yer, Antakya'nın defne ağaçlarıyla ünlü Harbiye bölgesidir. Harbiye’deki sayısız şelalenin de Defne’nin gözyaşları olduğuna inanılır.” [3,4]</p>



