UPDATE posts SET content = $tag2$<blockquote class="wp-block-quote"><p><em>Ey yiğit, bu dünya bir gölge gibidir; onun peşine düşersen, kaçar; sen kaçarsan, o sana koşar.</em></p><cite>1409. beyit</cite></blockquote>



<p class="has-text-align-justify">11. yüzyıl&nbsp;<a href="https://tr.wikipedia.org/wiki/Karahanl%C4%B1lar">Karahanlı</a>&nbsp;Türklerinden <a href="https://tr.wikipedia.org/wiki/Yusuf_Has_Hacib">Yûsuf Has Hâcib</a>, Balasagun’da soylu bir ailede dünyaya gelmiştir. Eserini bir buçuk yılda Balasagun’da yazıp Kâşgar’da tamamlayarak (6645. beyit) 1069-70 yılında Karahanlılar’ın hakanı Süleyman Arslan Hakan oğlu Tavgaç Uluğ Buğra Han’a sunmuştur. Eser,&nbsp;<a href="https://tr.wikipedia.org/wiki/Karahanl%C4%B1ca">Karahanlıca</a>&nbsp;olarak da isimlendirilen Hakaniye lehçesi ile yazılmıştır. Elimizde <a href="https://islamansiklopedisi.org.tr/kutadgu-bilig">Kutadgu Bilig</a>’in şu ana kadar bilinen, biri Uygur, ikisi Arap harfleriyle yazılmış üç nüshası vardır.</p>



<div class="wp-block-image"><figure class="aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/hacip.jpeg" alt="" class="wp-image-2086" width="771" height="508"/><figcaption><em>Balasagunlu Yûsuf Has Hâcib</em> (Resim: Turktoyu.com)<br></figcaption></figure></div>



<p class="has-text-align-justify">Kutadgu Bilig&nbsp;(kut+ad-gu bil-i-g “mesut olma bilgisi”), insana her iki dünyada saadete ermek için takip edilecek yolu göstermek amacıyla kaleme alınmış bir eser olup iddia edildiği gibi mansıp sahiplerine ahlak dersi veren kuru bir öğüt kitabı değil, insan hayatının anlamını tahlil ederek onun cemiyet ve dolayısıyla devlet içindeki görevlerini belirleyen bir hayat felsefesi sistemidir. Yûsuf Has Hâcib birbirine çok sıkı bağlarla bağlı bulunan fert, cemiyet ve devlet hayatının ideal bir biçimde düzenlenmesinde zaruri olan zihniyet, bilgi ve faziletlerin nelerden ibaret olduğu, bunların nasıl elde edileceği ve nasıl kullanılacağı üzerinde sanatkarane bir şekilde durmuştur.</p>



<div class="wp-block-image"><figure class="aligncenter size-large is-resized"><img src="https://i2.wp.com/www.loveinartsz.com/wp-content/uploads/2020/06/kutadgu-bilig-1.jpg?fit=1024%2C751&amp;ssl=1" alt="" class="wp-image-2087" width="718" height="526"/><figcaption><em>Kutadgu Bilig’in Kahire nüshasının ilk iki sayfası</em></figcaption></figure></div>



<p class="has-text-align-justify"><em>Kutadgu Bilig</em>&nbsp;dört esas üzerine düzenlenmiş olup bunlardan doğru kanun Kün-Toğdı (hakan), saadet (kut) Ay-Toldı (vezir), akıl Ögdülmiş (vezirin oğlu), hayatın sonu (âkıbet) Odgurmış (zâhid) tarafından temsil edilmektedir. Bu nedenle Kutadgu Bilig'in alegorik bir eser olduğunu söylemek, kesinlikle doğru olur. </p>



<div class="wp-block-image"><figure class="aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/Ekran-Alıntısı.png" alt="" class="wp-image-2092" width="720" height="192"/></figure></div>



<p>Güncelliğini ve değerini yaklaşık bin yıldan beridir korumayı başaran bu ölümsüz eserin, herkese hitap eden ve insan yaşamına dokunan birkaç alıntısıyla sizi baş başa bırakıyoruz.</p>



<blockquote class="wp-block-quote"><p>Dünya malı ne kadar toplanırsa toplansın, tükenir, bir gün biter; söz kaleme alınırsa, kalır, dünyayı dolaşır.</p><cite>114. beyit</cite></blockquote>



<blockquote class="wp-block-quote"><p>Bilgisiz insan hep hastalıklı olur; hastalık tedavi edilemezse, insan çabuk ölür.</p><cite>157. beyit</cite></blockquote>



<blockquote class="wp-block-quote"><p>Gençlik kaçar ve hayat uçar; bu rüya gibi dünyadan kendin çabuk göçersin.</p><cite>231. beyit</cite></blockquote>



<blockquote class="wp-block-quote"><p>Ne kadar iyi ve yakın bir insan olursa-olsun, düşün, insana başkası kendisinden daha candan olabilir mi?</p><cite>517. beyit</cite></blockquote>



<blockquote class="wp-block-quote"><p>İnsan kimi severse, onun kusuru fazilet olur; kimi sevmezse, onun fazileti kusur görünür</p><cite>534. beyit</cite></blockquote>



<blockquote class="wp-block-quote"><p>Doğan herkes ölmeye, yükselen her şey düşmeye mahkumdur.</p><cite>1086. beyit</cite></blockquote>



<blockquote class="wp-block-quote"><p>Her yokuşun bir inişi, her tepenin bir çukuru, her sevincin bir kederi ve her acıya karşı bir lezzet vardır.</p><cite>1087. beyit</cite></blockquote>



<blockquote class="wp-block-quote"><p>Yere ne ekilirse, yine o biter; ne verilirse, karşılığında aynı şey alınır.</p><cite>1394. beyit</cite></blockquote>



<blockquote class="wp-block-quote"><p>Ey yiğit, bu dünya bir gölge gibidir; onun peşine düşersen, kaçar; sen kaçarsan, o sana koşar.</p><cite>1409. beyit</cite></blockquote>



<blockquote class="wp-block-quote"><p>Kara toprak ile mavi gök, öç almak için, birleşse bile, Tanrı'nın verdiğine insan mâni olamaz.</p><cite>1800. beyit</cite></blockquote>



<p></p>



<p><em>Kaynakça:<br>Yusuf Has Hacip, Kutadgu Bilig, Çev: Ord. Prof Dr. Reşid Rahmeti Arat, Kabalcı Yayınları, İstanbul, 2018<br>Reşid Rahmeti Arat, Kutadgu Bilig, Türk Dil Kurumu Yayınları, Ankara, 1999<br>www.islamansiklopedisi.org.tr/kutadgu-bilig</em><br><br></p>$tag2$ WHERE slug = 'turk-devletcilik-sanati-kutadgu-bilig';
UPDATE posts SET content = $tag2$<p>Michelangelo'nun erken dönem eserlerinden biri olan Pieta heykeli, onun daha yirmi üç yaşında yaptığı ve üzerine adını yazdığı tek heykeldir.</p>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/Michelangelo_Pieta-1.jpg" alt="" class="wp-image-2337" style="aspect-ratio:0.9581239530988275;width:338px;height:auto"/></figure>



<h2 class="wp-block-heading">Michelagelo Pieta Heykelini Neden İmzaladı?</h2>



<p>Erken dönem eserlerinden biri olan Pieta heykeli, Michelangelo'nun gurur duyduğu ve herkesten övgü beklediği bir eserdi. Eser ilk defa seyircilerle buluştuğunda Michelangelo'da oradaydı. Gizli gizli izleyicilerin tepkilerini dinliyordu. Ancak Michelangelo'yu sinirlendiren bir şey vardı. Seyirciler bu esere övgü yaparken eserin sahibi için farklı bir isim söylüyordu. Duyduklarına adeta deliren Michelangelo gidip eşyalarını alarak gece vakti kiliseye girdi. Yakalanma korkusuyla heykelin görünen yerine imzasını attı;  <strong>MICHAEL ANGELUS BONAROTUS FLORENTINUS FACIEBAT</strong> / Floransalı Michelangelo Bounarroti tarafından yapıldı.</p>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/michelangelo-imza.jpg" alt="" class="wp-image-2330" style="width:477px;height:357px"/></figure>



<h2 class="wp-block-heading">Pieta Heykelinin Detayları</h2>



<p>On beşinci yüzyıldan sonra sıkça işlenen bir konu olan Pieta, kucağında ölü İsa’yı tutan Meryem’in heykelidir. Michelangelo bu eseri Roma’da yaşayan Fransız Piskopos Jean de Bilheres'in siparişi üzerine yapmıştı. Şu an Vatikan'da Aziz Petrus Bazilikası'nda bulunuyor.</p>



<p> Eserin farklı bir havası var. İlk bakışta karşımıza çıkmasını beklediğimiz şey hüzün ve acı olmasına rağmen, İsa'nın yüzünde çektiği acılardan bir iz yok. Yeni doğmuş bir bebek, annesinin kucağında uyuyor gibi... Meryem'in oğlunu bırakmak istemediği her halinden belli. </p>



<p>Michelangelo, Meryem'i 20'li yaşlarında genç bir kız olarak tasvir etmiş oysa İsa çarmıha gerildiğinde annesi ellili yaşlardaydı. Michelangelo bunun sebebini, Meryem'in bakireliğine vurgu olarak belirtmiştir. Ayrıca Meryem'in kafası vücuduna oranla daha küçüktür bu da yine Michelangelo'ya göre ölmüş evladını kaybeden bir annenin devleşmesidir. </p>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/1pieta4-872x1024-1.jpg" alt="" class="wp-image-2331" style="width:497px;height:581px"/></figure>



<p>Meryem'in hüznüne dikkatli bakalım. Meryem oğlunu çarmıhtan yeni almış ve ölü bedenini, bir bebeği tutar gibi tutuyor. Ölü bedenin ağırlıyla dizleri açılmış fakat durumdan şikayetçi değil aksine oğlunu bırakmak istemediği için sol eliyle İsa'nın kolunun altını nasıl kavradığını ve oradaki cildin nasıl gerginleştiğini görürüz. Bunlar evladını yeni kaybetmiş bir annenin sessiz çığlıkları...</p>



<figure class="wp-block-image aligncenter size-large"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/Michelangelo_Pieta2w.jpg" alt="" class="wp-image-2332"/><figcaption class="wp-element-caption">Pieta el detayı</figcaption></figure>



<p>Michelangelo, bu heykeldeki iki insan vücudunu mermerden yapmış olsa da sanki bir ete dönüştürmüş. Vücudun ağırlığını ve cansız bir bedene ait olduğunu anlayabiliyoruz. Meryem'in acısı yüzündeki ifadeye yansımış.  Son derece güzel ve genç. Bu gençliğe rağmen ölü bir bedenin ağırlığını taşıyabiliyor. Eserde iki önemli tezatlıktan biri bu. Diğeri ise figürlerden birinin hareketsizliği diğerinin hareketliliği. Yani yaşam ve ölüm...</p>



<p>Mermerin işlemesi çok önemli. Meryem'in elbisesinin kumaşındaki drapeler, İsa'nın bacakları, figürlerin üzerindeki yüzeyler,heykelin canlı bir şekilde durmasını sağlıyor. İsa'nın başı geride, ayağı havada savunmasız bir şekilde yatıyor. Meryem'in ise sol eli açık durumu sorguluyor.</p>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/İsa.jpg" alt="" class="wp-image-2333" style="width:321px;height:336px"/></figure>



<h2 class="wp-block-heading">Piete Heykeli Boyutları</h2>



<p>Heykel, St. Peters Bazilikasına göre çok küçük (174 x 195 cm). Çünkü ilk yapıldığı zaman Kardinal için sipariş verilmiş ancak daha sonra eski St. Peters'a yerleştirilmiş. St. Peters kilisesi de önceden daha küçükmüş. Bu sebeple heykel mimariye göre daha küçük gözükmektedir. Her ne kadar bulunduğu yere göre küçük gibi gözükse de önemi ve izleyicide uyandırdığı duygular açısından oldukça büyük bir eser olarak tarihte yerini almıştır. </p>



<p>Bazilikanın devasa güzelliğini ve Pietà'yı görmek isterseniz <a href="http://www.vatican.va/various/basiliche/san_pietro/vr_tour/index-en.html" target="_blank" rel="noopener nofollow" title=""> buradan</a> ziyaret edebilirsiniz.</p>



<h5 class="wp-block-heading"><em>Kaynakça:</em></h5>



<ul>
<li class="has-small-font-size">Khan Academy</li>



<li class="has-small-font-size"><em>Sanatın Büyük Ustaları/ Michelangelo, Hayalperest Yayınları</em></li>
</ul>



<p class="has-text-align-center has-ast-global-color-7-background-color has-background has-small-font-size">Tüm yazılarımızı incelemek için <a href="http://www.loveinartsz.com" target="_blank" rel="noopener" title="">ana sayfamızı</a> ziyaret edin .</p>$tag2$ WHERE slug = 'michelangelonun-pieta-heykeli';
UPDATE posts SET content = $tag2$<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://i2.wp.com/www.loveinartsz.com/wp-content/uploads/2020/06/Eugène_Delacroix_-_La_liberté_guidant_le_peuple-1-scaled.jpg?fit=1024%2C811&amp;ssl=1" alt="" class="wp-image-2217" width="496" height="392"/><figcaption>Eugène Delacroix'in&nbsp;<em>"La liberté guidant le peuple"</em>&nbsp;(<em>Halkın rehberi özgürlüktür</em>)</figcaption></figure>



<p class="has-text-align-justify">Tarihsel açıdan yapıldığı dönem için son derece radikaldir. Resmin cumhuriyetçi devrime vurguladığı mesaj çok bariz. Resimde Paris sokaklarındaki 1830 devrimini görüyoruz. Burada bir barikat görüyoruz derme çatma bir barikat, o dönemde şehir ortaçağ görünümünde yani sokaklar dar ve dolambaçlı bu da Fransız birliklerinin yolunun kesilmesini kolaylaştırıyor. Resimde gerçek olanla hayali olan iç içe geçmiştir. Kadın figürü özgürlüğü simgeliyor, elinde üç renkli Fransız bayrağını taşıyor bayrak aynı zamanda eşitlik, kardeşlik ve özgürlüğü simgeliyor yani devrimin üç temel kavramını. Tarihin bu döneminde monarşi rejimi hakimdi oldukça sert ve katı bir yönetim tarzıydı. 1830 Temmuz devrimiyle Kral X. Charles tahttan indiriliyor ve liberal monarşi dönemi başlıyor. Göreve orta sınıfın gereksinimlerine daha ılımlı yaklaşan bir kral getiriliyor. Arada bir dönem var protesto gösterilerinin çok ötesinde olaylar yaşanıyor, Paris sokakları savaş alanına dönüyor, bu günlere şanlı üç gün deniliyor.</p>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://i2.wp.com/www.loveinartsz.com/wp-content/uploads/2020/06/DETAY-1.jpg?fit=1024%2C504&amp;ssl=1" alt="" class="wp-image-2218" width="559" height="276"/></figure>



<p class="has-text-align-justify">X. Charles Fransa’dan kaçıyor ve tahta kuzeni Louis Philippe oturuyor. Delacroix olan bitenleri penceresinden seyrediyor, resimde her iki taraftan da yerde yatan ölüleri görüyoruz, soldaki yerde yatan figür zulme uğramış yakından bakarsanız gece giysisiyle olduğunu fark edeceksiniz. Baskıcı iktidar muhaliflerin evlerini basıyor, ölesiye dövüyorlar ve sonrada sürükleyerek evlerden çıkartıp sokaklarda teşhir ediyorlar. Resimde sağ alt tarafta kraliyet kuvvetlerinden biri var ölmüş veya ağır yaralı, kraliyet kuvvetlerinin yenilmez olmadığını göstermek için çizildiğini vurguluyor.</p>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://i2.wp.com/www.loveinartsz.com/wp-content/uploads/2020/06/DETAY2.jpg?fit=1024%2C381&amp;ssl=1" alt="" class="wp-image-2219" width="649" height="241"/></figure>



<p class="has-text-align-justify">Özgürlük büyük adımlarda ilerliyor inanılmaz derecede güçlü ve Delacroix bu figüre gerçekçi bir hava vermiş. Bu gerçekçi tarz verilen mesaj açısından da önemli eğer burada antik yunan sanatındaki tarzda idealize edilmiş bir kadın figürü görseydik tüm sahne gerçekçiliğini yitirirdi ve özgürlüğü güçlü algılayamazdık.</p>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/detay3.jpg" alt="" class="wp-image-2220" width="509" height="276"/></figure>



<p class="has-text-align-justify">Özgürlüğü profilden görüyoruz tamamen aydınlanmış ışığın vuruşu sanatçının tarzını yansıtıyor. Delacroix resme çok değişik tipteki kişileri bilinçli olarak koymuş şapkalı adam bir burjuva orta sınıftan hemen yanındaki gömlekli adamsa bir işçi hep birlikte monarşiye başkaldırıyorlar.</p>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://i1.wp.com/www.loveinartsz.com/wp-content/uploads/2020/06/detay.jpg?fit=1024%2C750&amp;ssl=1" alt="" class="wp-image-2225" width="610" height="446"/></figure>



<p>Tahta geçen yeni kralın, Louis Philippe'in hükümeti resmi satın alıyor. Resmin verdiği mesajdan rahatsız oluyorlar ve resmi kaldırıyorlar. Resim 1848 devriminden sonra tekrar sergileniyor, sergilendiği yer Paris Louvre müzesi.</p>



<p class="has-text-align-right"><strong><em>Doğan Çiçek</em></strong></p>$tag2$ WHERE slug = 'halkin-rehberi-ozgurluktur-eugene-delacroix';
UPDATE posts SET content = $tag2$<figure class="wp-block-image aligncenter is-resized"><img src="https://uploads4.wikiart.org/00220/images/gian-lorenzo-bernini/ecs.jpeg!Large.jpeg" alt="The Ecstasy of St. Teresa, 1647 - 1652 - Gian Lorenzo Bernini" width="398" height="536"/></figure>



<p class="has-text-align-justify">Bu yazımda sizlere Barok dönemin en etkileyici sanatçılarından biri olan Gian Lorenzo Bernini'nin tüm yeteneklerini ortaya koyduğu Azize Teresa'nın Vecdi'ni anlatacağım. </p>



<p class="has-text-align-justify">Heykeltıraş,ressam ve mimar olan Bernini'nin bu eseri aslında onun tasarımı olan bir sunağın odak noktasındaki heykelidir.Roma'da Santa Maria della Vittoria Kilisesi'nin Cornaro Şapeli'ne yapılış olan sunak 1647'de Venedik kardinali Federico Cornaro tarafından sipariş edilmiş,1652'de bitirilmiştir. Sunak Avilalı Azize Teresa'ya adanmışıtır, bunun nedeni eserin Karşı Reformasyon döneminde yapılmasıdır ve Avilalı Teresa'nın bu dönemin etkin isimlerinden biri olmasıdır. Beyaz mermerden yapılmış olan heykel üçgen alınlıklı,çift korint sütunlu oval bir nişin içerisinde yer alır. </p>


<!-- wp:block {"ref":2008} /-->


<p class="has-text-align-justify">Heykelin konusu ise Avilalı Teresa'nın otobiyografisinde yazdığı bir melekle karşılaşma anıdır. Bernini'nin tasvir ettiği olay şu şekildedir : <em>"Yanımda, solda, bir melek vücut buldu.... Uzun boylu değil kısaydı ve çok güzeldi; yüzü o kadar kızarmıştı ki hepsi ateş gibi yanan meleklerin en üst seviyedekilerinden birisi gibi gözüküyordu... Ellerinde büyük altın bir mızrak gördüm, mızrağın demir ucunda bir ateş noktası vardı. Bunu kalbime birkaç kere sapladı ve iç organlarımı parçaladı. Mızrağı çıkardığında, organlarımı da çıkarıyormuş gibi hissettim ve Tanrının büyük sevgisiyle tükenmiş şekilde kaldım. Acı o kadar fazlaydı ki, pek çok kez inledim. Bu yoğun acının neden olduğu tatlılık o kadar aşırıydı ki, kişi bunun sonlanmasını isteyemezdi veya ruhu Tanrı'dan başka bir şeyle dolu olamazdı. Bu fiziksel değil, ruhsal bir acıydı; her ne kadar vücudun bir rolü olsa da—önemli bir rolü olsa da."</em>Bulut şeklinde oyulmuş mermerin üzerinde havada asılıymış gibi duran melek ve Azize Terasa bulunur.Meleğin yüzünde tebessümüyle ve elinde bir mızrakla Azize Teresa'ya bakarken görüyoruz.Azize Teresa ise bulutun üstünde yoğun drapeli elbisesinin ağırlığı altında vecd haldedir.Azize Teresa aldığı tanrısal zevki erotik bir dille anlatması Bernini'ye ilham oluyor ve alınan zevki somutlaştırarak figüre cinsel haz alan bir yüz ifadesi veriyor.Böylelikle o güne kadar başarılamayan uhrevi yoğunluk hissini aktarabiliyor.Bernini sadece heykel üzerinde değil tasarladığı şapele de uhreviliğin dokunulmazlığını desteklemiştir.Arka planda altın kaplı ışık çağlayanı heykel grubunun üstüne inen kutsal bir ışık görevi görmüş ve nişe gizlenen sarı sırlı camdan gün ışığının ışık çağlayanına düşmesini sağlamış. Şapelin iki yan duvarında rölyeflere yerleştirilmiş heykeller bulunur,bizler gibi onlar da bu kutsal sahnesinin izleyicisidir.  Tanık olduğumuz ancak ait olmadığımız bu eserle Bernini sadece Barok dönemin değil sanat tarihinin en etkileyici işlerinden birini ortaya koymuştur.</p>



<figure class="wp-block-image aligncenter is-resized"><img src="https://i.pinimg.com/originals/90/f3/a6/90f3a69ce086c3f7467141385d9ff7bf.jpg" alt="Image result for bernini st teresa face | Bernini sculpture" width="328" height="447"/></figure>



<p></p>



<p><em> </em></p>$tag2$ WHERE slug = 'azize-teresanin-vecdi';
UPDATE posts SET content = $tag2$<p class="has-text-align-justify">You may have heard the name of Medusa, or the curse whispered in your ear. The woman who turned the minister into stone ...</p>



<figure class="wp-block-image aligncenter size-medium is-style-default"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/05/IMG_20200210_123249-330x400.jpg" alt="Medusa, Gian Loranzo Bernini, 1644-1648" class="wp-image-1983"/><figcaption>Medusa, Gian Loranzo Bernini, 1644-1648<br></figcaption></figure>



<p>In the ages when the universe was divided by the Gods, a girl named Medusa lived with a beauty that made everyone jealous and at the same time fell in love with all the gods. Medusa was such a beautiful girl that it was not possible to find another woman who could compete with her beauty on earth. That's why they say All women on earth were jealous of Medusa because of this beauty. This beautiful Medusa devoted herself to the Gods and lived with her two sisters in a temple of the goddess Athena, the favorite daughter of the chief god Zeus. Out of these three sisters, who are the daughters of Phorkus and Keto, the other two were immortal, except for Medusa. Athena, who saw this beautiful girl living in her own temple, was also impressed by the beauty of the girl, but did not care so much because she found herself more beautiful and much more intelligent. Athena was with the great lord of the seas, Poseidon, the brother of Chief Zeus. The mighty and immortal, the great God Poseidon was also aware of this beautiful girl who lived in the temple of his wife Athena, but she was hiding her interest because she was afraid of being underestimated because she fell in love with a mortal in the sight of the Gods. One day Athena, with the permission of the chief God Zeus who knew everything, Poseidon's interest in Medusa. Poseidon denied this vigorously and swore to Goddess Athena that there were no more beautiful and charming creatures on earth and in the sky. Athena did not enlarge the incident too much, believing what Poseidon said. Poseidon could not get Athena to say so, but she could never get out of her mind, Medusa, the beautiful worlds. Due to his passion for Medusa, Poseidon seemed to miss his mind. In the end, the great god of the seas succumbed to this passion and one day he entered the beautiful Medusa by force in the temple of his beloved Athena, whom he secretly entered. Medusa, the beauty of the worlds, remained in ruins in the temple, but Athena did not take much time to hear about this event.ondan daha güzel ve alımlı hiçbir canlının olmadığı üzerine yeminler etmiş. Athena da Poseidon'un bu söylediklerine inanarak olayı çok fazla büyütmemiş. Poseidon Athena'ya öyle demiş demesine ancak yine de bir türlü çıkaramıyormuş aklından dünyalar güzeli Medusa'yı. Medusa tutkusu yüzünden Poseidon aklını kaçıracak gibi oluyormuş. Sonunda denizlerin büyük tanrısı bu tutkusuna yenik düşmüş ve bir gün gizlice girdiği sevgilisi Athena'nın tapınağında, güzeller güzeli Medusa'ya zorla sahip olmuş. Dünyalar güzeli Medusa harap bir halde tapınakta kalmaya devam ediyormuş ama bu olayı Athena'nın duyması da fazla zaman almamış.</p>



<figure class="wp-block-image aligncenter size-large is-resized is-style-default"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/05/medusa.jpg" alt="Perseus with the Head of Medusa, Benvenuto Cellini, 1545-1554" class="wp-image-1990" width="280" height="426"/><figcaption>    <em>Perseus with the Head of Medusa, Benvenuto Cellini, 1545-1554</em></figcaption></figure>



<p>Athena felt humiliated in the face of this powerful Poseidon did. This feeling turned into deep jealousy and then a great nerve. He became so angry, so angry that he decided to punish Medusa very painfully and said to herself, "I will not kill him so suddenly, I must make them suffer greatly first. Just like I have suffered." Translation to ifrite. The worlds of Medusa and her sisters were so ugly that no one could tolerate looking. Every string of her beautiful hair, which turned all the people of Medusa into a jazz, and even the slightest wind, had all her hairs turned into a snake. Nevertheless, Athena's nerve, which did not settle, made everyone who tried to look at Medusa anyway turn those looks into stone, and she was exiled to Hyperborea, the northernmost of the world. Athena did not settle with this punishment, and he decided to cut off Medusa's head in collaboration with Perseus, the son of King of Argos King Akrisios, son of Zeus, namely Perseus, to kill Medusa. Perseus immediately fulfilled this desire of his half-sister, as he gleamed sparkles and threw the sharp sword that dazzled people's eyes, and separated the poor Medusa's snake-haired head from her body.</p>



<figure class="wp-block-image aligncenter size-large is-resized is-style-default"><img src="https://i2.wp.com/www.loveinartsz.com/wp-content/uploads/2020/05/Rubens_Medusa-scaled.jpeg?fit=1024%2C589&amp;ssl=1" alt="" class="wp-image-1984" width="479" height="275"/><figcaption><em>The Head of Medusa, Peter Paul Rubens, 1617-1618</em></figcaption></figure>



<p>This is how the story is told. Didn't Athena think she was guilty while cursing Medusa? I do not think so…</p>



<p>We have witnessed this story many times on the dusty shelves of history. Paintings, sculptures, books portrayed the killing of Medusa many times. It is not known why history became a crime partner, but Italian artist Luciano Garbati completely destroyed this unquestioned attitude of history. He created a brand new story with the head of Perseus, which Medusa held. According to this statue, Medusa is the winner / killer and Perseus is on the slain side. This sculpture made by Luciano Garbati in 2008 made a great impression in the world and people liked this new Medusa even more.</p>



<div class="wp-block-jetpack-tiled-gallery aligncenter is-style-square"><div class="tiled-gallery__gallery"><div class="tiled-gallery__row columns-2"><div class="tiled-gallery__col"><figure class="tiled-gallery__item"><img alt="" data-height="1000" data-id="1986" data-link="https://www.loveinartsz.com/?attachment_id=1986#main" data-url="https://www.loveinartsz.com/wp-content/uploads/2020/05/medusa01.jpg" data-width="1500" src="https://i0.wp.com/www.loveinartsz.com/wp-content/uploads/2020/05/medusa01.jpg?ssl=1&amp;resize=1000%2C1000" data-amp-layout="responsive"/></figure></div><div class="tiled-gallery__col"><figure class="tiled-gallery__item"><img alt="" data-height="1000" data-id="1987" data-link="https://www.loveinartsz.com/?attachment_id=1987#main" data-url="https://www.loveinartsz.com/wp-content/uploads/2020/05/medusa02-1.jpg" data-width="1500" src="https://i0.wp.com/www.loveinartsz.com/wp-content/uploads/2020/05/medusa02-1.jpg?ssl=1&amp;resize=1000%2C1000" data-amp-layout="responsive"/></figure></div></div><div class="tiled-gallery__row columns-2"><div class="tiled-gallery__col"><figure class="tiled-gallery__item"><img alt="" data-height="1000" data-id="1985" data-link="https://www.loveinartsz.com/?attachment_id=1985#main" data-url="https://www.loveinartsz.com/wp-content/uploads/2020/05/medusa06.jpg" data-width="1500" src="https://i0.wp.com/www.loveinartsz.com/wp-content/uploads/2020/05/medusa06.jpg?ssl=1&amp;resize=1000%2C1000" data-amp-layout="responsive"/></figure></div><div class="tiled-gallery__col"><figure class="tiled-gallery__item"><img alt="" data-height="1000" data-id="1988" data-link="https://www.loveinartsz.com/?attachment_id=1988#main" data-url="https://www.loveinartsz.com/wp-content/uploads/2020/05/medusa04.jpg" data-width="1500" src="https://i0.wp.com/www.loveinartsz.com/wp-content/uploads/2020/05/medusa04.jpg?ssl=1&amp;resize=1000%2C1000" data-amp-layout="responsive"/></figure></div></div></div></div>



<p>The important thing here was why Medusa got revenge. Medusa was abused, by the symbol of power. What could he do? He was just a mortal. It was not enough that he had been raped, he was cursed and then killed by his fellow man. He couldn't make his voice, couldn't look in anyone's eyes. She lived with those who escaped her until the end of her life, trying to kill her. What a familiar story that was raped and killed, right?</p>



