UPDATE posts SET content = $tag2$<blockquote class="wp-block-quote"><p><em>“The wealth I have come from nature, nature is my inspiration.”</em></p><cite><em>– Claude Monet</em></cite></blockquote>



<p><br>If you are interested in painting, you have definitely come across one of Monet's "Water Lilies". The water lilies series are Monet's most famous works that marked the last period of his life.</p>



<p>Disappointed in traditional art classes at the art school, Monet never liked being limited to classrooms. After meeting the French landscape painter Eugene Boudin, he adopted the understanding of painting outdoors, which would affect his entire career. They became the pioneer of Impressionism (impressionism) movement with a group of painters who shared the same thoughts. For Monet, painting nature was a passion. It aims to capture the essence of the landscape by transferring the light transitions and reflections to the canvas with different paints and to give the same impression to the viewers.</p>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/05/800px-Claude_Monet_-_Nymphéas_W1852_-_Musée_Marmottan-Monet-1.jpg" alt="" class="wp-image-1971" width="367" height="273"/></figure>



<blockquote class="wp-block-quote"><p><em>“Methods change but art remains the same; because art is an effective and emotional interpretation of nature. ”</em></p><cite><em>– Claude Monet</em></cite></blockquote>



<h3><strong><em>Nilüferler</em>’in ortaya çıkışı</strong></h3>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/05/04Solomon-jumbo.jpg" alt="" class="wp-image-1952" width="444" height="331"/><figcaption>1920'de son büyük <em>Nilüferler</em>’i resmederken stüdyosunda Monet. <em>“Mad Enchantment”</em>dan&nbsp;<br></figcaption></figure>



<p>Monet has created its own gardens as a kind of open air studio in many places where it lives. After overcoming financial difficulties in 1883, he settled in a garden house in Giverny, a small town outside Paris. There he built a huge artificial pond full of water lilies and a Japanese-style bridge over it. He covered the pond with willows, shrubs, bamboo trees and exotic flowers. He built a glass-walled studio on the side of the garden and installed a wheelchair easel, which he could rotate freely around the room. There he painted his water lilies, the reflections of willow leaves on the surface of the water, the Japanese-style bridge at many hours of the day and in many different ways, based on the change of light.</p>



<div class="wp-block-group">
<figure class="wp-block-gallery has-nested-images columns-default is-cropped">
<figure class="wp-block-image size-large"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/05/water-lilies-and-japanese-bridge-claude-monet.jpg" alt="" class="wp-image-1954"/></figure>



<figure class="wp-block-image size-large"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/05/800px-Claude_Monet_-_Water_Lilies_-_Google_Art_Project.jpg" alt="" class="wp-image-1958"/></figure>



<figure class="wp-block-image size-large"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/05/800px-Monet_-_Water_Lilies_1907_19.170.jpg" alt="" class="wp-image-1960"/></figure>



<figure class="wp-block-image size-large"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/05/claude-monet-water-lilies-9_1000x.jpg" alt="" class="wp-image-1962"/></figure>



<figure class="wp-block-image size-large"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/05/0f802b01fea5b0416900e789c63a4cb3.jpg" alt="" class="wp-image-1963"/></figure>
</figure>
</div>



<blockquote class="wp-block-quote"><p><em>"My garden is my most beautiful masterpiece."</em></p><cite><em>– Claude Monet</em></cite></blockquote>



<p>In 1914, the then prime minister and Monet's friend, Georges Clemenceau, encouraged the artist to work on a series of large canvases showing water lilies. From that moment until his death in 1926, Monet's main occupation was these giant paintings. It took too long to complete the paintings due to many reasons such as increasing pessimism, finding the paintings he made insufficient, and his eyes deteriorating. He gifted the great water lily paintings he called the Grande Décoration to the nation of France. The paintings are still on display at the Musée de l'Orangerie in Paris. The book "Mad Enchantment" written by Ross King, which covers the stage of construction of the paintings, the problems Monet experienced at that time, and his negative attitudes towards his environment, sheds light on some of the facts behind these masterpieces.</p>



<p>In these last paintings of Monet, brush strokes and colors depicting flowers and water are significantly different from early Impressionist techniques; from time to time they reach the passionate intensity of expressionism to evoke the beauty of the water surface. These works, which refused to focus the eye in one place, by simplifying the composition, disappearing contours and borders, and using pure and vivid colors, actually paved the way to abstract painting. With these features, Post-impressionist, Expressionist and Abstract expressive movements that came after him influenced. Especially in the 1950s, the pioneers of the abstract movement in America, Jackson Pollock and Mark Rothko are said to be inspired by these paintings of Monet.</p>



<figure class="wp-block-gallery has-nested-images columns-default is-cropped">
<figure class="wp-block-image size-large"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/05/Claude_Monet_-_The_Water-lily_Pond_-_Google_Art_Project.jpg" alt="" class="wp-image-1964"/></figure>



<figure class="wp-block-image size-large"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/05/Reflections_of_Clouds_on_the_Water-Lily_Pond-1.jpg" alt="" class="wp-image-1966"/></figure>



<figure class="wp-block-image size-large"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/05/1280px-Claude_Monet_-_Water_Lilies_-_Google_Art_Project_431238.jpg" alt="" class="wp-image-1956"/></figure>
</figure>



<p>Monet, who started having vision problems in 1907, was almost completely blind in 1923. In this period, there was a general redness in his paintings and the images were seriously spoiled. Cataract surgery took place in 1923 as a result of Clemenceau's insistence. However, in 1926, when he was 86 years old, he died of lung cancer in his beloved home in Giverny.</p>



<p>Monet devoted the last 30 years of his life to painting water lilies in particular. It has left over 250 lotus images that are still the most beautiful pictures of nature and flowers in the world.</p>



<p></p>



<p class="has-normal-font-size"><em>Kaynaklar:</em></p>



<p class="has-small-font-size"><em>&nbsp;</em><a href="https://myartpoint.com/2018/08/03/claude-monets-love-affair-with-nature/" class="aioseop-link"><em>https://myartpoint.com/2018/08/03/claude-monets-love-affair-with-nature/</em></a></p>



<p class="has-small-font-size"><a href="https://en.wikipedia.org/wiki/Claude_Monet" class="aioseop-link"><em>https://en.wikipedia.org/wiki/Claude_Monet</em></a></p>



<p class="has-small-font-size"><a href="https://www.reproduction-gallery.com/oil-painting/1568351806/water-lilies-detail-1-by-claude-monet/" class="aioseop-link"><em>https://www.reproduction-gallery.com/oil-painting/1568351806/water-lilies-detail-1-by-claude-monet/</em></a></p>



<p class="has-small-font-size"><a href="https://www.artic.edu/artworks/16568/water-lilies"><em>https://www.artic.edu/artworks/16568/water-lilies</em></a><em> ,</em><a href="https://www.claude-monet.com/waterlilies.jsp" class="aioseop-link"><em>https://www.claude-monet.com/waterlilies.jsp</em></a></p>



<p class="has-small-font-size"><a href="https://www.nytimes.com/2016/12/02/books/review/the-story-of-claude-monets-water-lily-masterworks.html" class="aioseop-link">https://www.nytimes.com/2016/12/02/books/review/the-story-of-claude-monets-water-lily-masterworks.htm</a></p>



<p class="has-small-font-size"> <a href="https://www.ideelart.com/magazine/monet-and-american-abstract-expressionists">https://www.ideelart.com/magazine/monet-and-american-abstract-expressionists</a>&nbsp;</p>



<p class="has-small-font-size"><a href="https://en.wikipedia.org/wiki/Water_Lilies_(Monet_series)" class="aioseop-link">https://en.wikipedia.org/wiki/Water_Lilies_(Monet_series)</a></p>$tag2$ WHERE slug = 'claude-monet-and-water-lilies';
UPDATE posts SET content = $tag2$<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://i2.wp.com/www.loveinartsz.com/wp-content/uploads/2020/05/800px-Édouard_Manet.jpg?fit=659%2C1024&amp;ssl=1" alt="Edouard Manet" class="wp-image-1894" width="269" height="417"/></figure>



<p class="has-text-align-justify">Edouard Manet was born on January 23, 1832 in Paris. Although his family supported him in the field of law, his interest was always in art. Edouard applied to the Naval War School at the request of his father but could not pass the exam. Later he entered the Maritime Fleet and set out for Brazil in 1948. He was quite surprised at what he saw on this journey and said in his letters: "All the black people in this country are slaves; they are always victimized; whites' trust in them is incredible; I saw a slave market that was disgusting to people like us. ''</p>



<p>When Manet returned to his country a year later, he convinced his father and started to become an artist. Manet started going to the studio of the artist Thomas Couture in Paris.</p>



<p>In this period, the circle of friends consisted of literati and artists living in the sophisticated life of Paris.</p>



<p>The 19th century French art was led by the romantic painter Eugene Delacroix, who returned to contemporary and exotic literary references such as Byron, instead of the classical approach favored by French scholars for the theme.</p>



<p>MAlthough Manet does not consider himself an Impressionist, artists such as Monet, Sisley and Renoir, who led the Impressionist revolution, received his support.</p>



<p>He wanted so much that Manet paintings were accepted by Salon and received positive criticism. His painting Le Dejeuner sur l 'Herbe was not accepted by Salon, but he signed a scandal. The table was exhibited in Salon des Refuses, which is the Alternstif of Salon. The problem with this unusual painting was that women were naked and men were dressed. The Parisian men in the picture appeared as a classic Parisian, but the woman was naked. Manet opposed traditions by portraying real people in a modern world. Ernest Chesneau accused Manet of trying to gain fame by surprising the bourgeoisie. Manet, on the other hand, said that even though it was an old painting, men could draw nudes just like women. This picture helped Manet gain fame.</p>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/05/800px-Edouard_Manet_-_Luncheon_on_the_Grass_-_Google_Art_Project.jpg" alt="Kırda Öğlen Yemeği" class="wp-image-1892" width="559" height="434"/><figcaption>Lunch in the countryside</figcaption></figure>



<p>Manet died on April 30, 1883. He has left many unique works of art history until this date.</p>



<p class="has-small-font-size"><em>Source:  Büyük Ressamlar, Manet, Beta Yayıncılık, 2015, İstanbul</em></p>$tag2$ WHERE slug = 'who-is-edouard-manet';
UPDATE posts SET content = $tag2$<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://i2.wp.com/www.loveinartsz.com/wp-content/uploads/2020/06/Eugène_Delacroix_-_La_liberté_guidant_le_peuple-1-scaled.jpg?fit=1024%2C811&amp;ssl=1" alt="" class="wp-image-2217" width="496" height="392"/><figcaption>Eugène Delacroix'in&nbsp;<em>"La liberté guidant le peuple"</em> (Liberty Leading the People)</figcaption></figure>



<p class="has-text-align-justify">It is extremely radical for the period when it was made historically. The message that the picture emphasizes on the republican revolution is very obvious. In the picture we see the 1830 revolution on the streets of Paris. Here we see a barricade, a makeshift barricade, the city's medieval appearance at that time, the streets are narrow and roundabout, which makes it easier to cut the way of the French troops. In the picture, what is real and what is imaginary are intertwined. The female figure symbolizes freedom, carries the tricolor French flag in its hand, and at the same time symbolizes equality, fraternity and freedom, that is, three basic concepts of the revolution. In this period of history, the monarchy regime was dominant, a rather harsh and strict management style. With the revolution of July 1830, King Charles X was deposed and the period of liberal monarchy begins. A king who is more moderate in the needs of the middle class is appointed to the task. Occasionally there are events far beyond protests, Paris streets return to the battlefield, these days are called three glorious days.</p>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://i2.wp.com/www.loveinartsz.com/wp-content/uploads/2020/06/DETAY-1.jpg?fit=1024%2C504&amp;ssl=1" alt="" class="wp-image-2218" width="559" height="276"/></figure>



<p class="has-text-align-justify">Charles X fled France and his wooden cousin, Louis Philippe, was sitting. Delacroix watches what is going on through the window, we see the dead on the ground from both sides, if you look closely at the figure on the left, you will notice that it is in evening wear. The repressive power raids the houses of opponents, beat them to death, and then drag them out of the houses and display them on the streets. In the picture, there is one of the royal forces in the lower right, emphasizes that the royal forces are drawn to show that the royal forces are not invincible.</p>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://i2.wp.com/www.loveinartsz.com/wp-content/uploads/2020/06/DETAY2.jpg?fit=1024%2C381&amp;ssl=1" alt="" class="wp-image-2219" width="649" height="241"/></figure>



<p class="has-text-align-justify">Freedom is progressing in huge steps, incredibly powerful, and Delacroix has given this figure a realistic feel. This realistic style is also important in terms of the message, if we saw a woman figure idealized in the style of ancient Greek art, the whole scene would lose its realism and we could not perceive freedom strongly.</p>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/detay3.jpg" alt="" class="wp-image-2220" width="509" height="276"/></figure>



<p class="has-text-align-justify">We see freedom from the profile, the hit of the fully illuminated light reflects the style of the artist. Delacroix consciously put many different types of people on the picture, and the man in a shirt right next to the bourgeois middle class, a worker is rebelling against the monarchy.</p>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://i1.wp.com/www.loveinartsz.com/wp-content/uploads/2020/06/detay.jpg?fit=1024%2C750&amp;ssl=1" alt="" class="wp-image-2225" width="610" height="446"/></figure>



<p>The new king's throne, Louis Philippe's government is buying the picture. They are disturbed by the message of the picture and remove the picture. The painting is exhibited again after the revolution of 1848, the place where it is exhibited is the Paris Louvre museum.</p>



<p class="has-text-align-right"><strong><em>Doğan Çiçek</em></strong></p>$tag2$ WHERE slug = 'liberty-leading-the-people-eugene-delacroix';
UPDATE posts SET content = $tag2$<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://i0.wp.com/www.loveinartsz.com/wp-content/uploads/2020/05/Autoportrait_au_béret_par_Paul_Cézanne-1-scaled.jpg?fit=853%2C1024&amp;ssl=1" alt="Paul Cézanne Kimdir?" class="wp-image-1847" width="369" height="441"/></figure>



<p class="has-text-align-justify">Paul Cézanne Paul Cézanne was born on January 19, 1839 in Aix-en Provence, a provincial region of France.</p>



<p class="has-text-align-justify">Paul's father was dealing with a fedora, and when he earned too much from this business, he founded the Cézanne and Cabassol Bank. Paul's coming from a wealthy family led to a good development in his educational life. He entered Collage Bourbon in Aix where he met his close friend Emile Zola.</p>



<p class="has-text-align-justify">Paul had enrolled at Aix University to study law with the encouragement of his father, but it clearly seemed that he would not follow his family and read law. Emile Zola encouraged him on this and Paul decided to go to Paris and become an artist. But after moving to Paris, he had a very unhappy period because he could not keep up with the sophisticated life of Paris and felt lonely. He then returned to Aix, but he did not stay there for a long time and returned to Paris with encouragement again.</p>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://i1.wp.com/www.loveinartsz.com/wp-content/uploads/2020/05/Le_Père_du_peintre_lisant_LÉvénement_par_Paul_Cézanne-scaled.jpg?fit=612%2C1024&amp;ssl=1" alt="" class="wp-image-1848" width="310" height="518"/><figcaption>father of the artist</figcaption></figure>



<p class="has-text-align-justify">Paul often went to the Louvre Museum and imitated great artists. He made his first works influenced by his masters and great masters of that period. Cézanne made new friends in Paris. He joined the intellectuals at Cafe Guerbois in the Batignolles district of Paris. Cézanne met Camille Pissarro here, and thanks to him, Manet met names like Monet Renoir. One of the artists rejected by the Official Hall was Cézanne. He sent many pictures to Salon but all of them were rejected. In the beginning of his career, his works were exhibited in the same place as Manet, Pissarro and Whistler.</p>



<p>When Cézanne settled in the same house with her boyfriend Hortense Fiquet, she did not tell her family about this because she did not want her father to cut her pocket money. For this reason, he had hidden his new family from his family in Aix. Eight years after he started living with Hortense, his father learned the truth and began to withdraw his help.</p>



<p>In 1886, his close friend Emile Zola published a novel, l'oeuvre. This novel was based on an unsuccessful artist, believed to have told about Cézanne's life. Their friendship ended after this novel was published. Also married to Hortense that year, Paul moved to Jas de Bouffan by taking the family legacy after his father's death.</p>



<p>In 1895, his first exhibition was held at the Ambroise Vollard gallery.</p>



<p>Cézanne has adopted a drawing style that extends to the thing under the float. While the Impressionist painters of the same period worked quite fast to capture the instant light appearance on the surface, Paul worked slowly. He said that he wanted to "create a strong and durable Impressionism, just like works of art in museums".</p>



<p>Cézanne said that he wanted to conquer Paris with an apple, that is, to be famous for his still life.</p>



<p>His art is seen today as having a significant influence on the development of 20th century Western art. Historians accept Cézanne as the basis of modern art, in which Cubism was born and then abstraction was born.</p>$tag2$ WHERE slug = 'who-is-paul-cezanne';
UPDATE posts SET content = $tag2$<p><em>"For an impressionist, it is not directly drawing nature, drawing it as it seems, but reviving the sensations it creates."&nbsp;</em>-Paul Cézanne</p>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/05/Claude_Monet_Impression_soleil_levant-1-1024x797.jpg" alt="" class="wp-image-1792" width="556" height="433"/><figcaption>&nbsp;<em>Sunrise, </em>Claude Monet ,1872&nbsp; (1)</figcaption></figure>



<p>A group of painters, who would later be called impressionists, began to meet regularly at Café Guerbois in Paris to exchange ideas from 1862. Although their style was different, the philosophy they shared was common. They reacted to the style and subject constraints of the authoritarian Academy of Fine Arts, which ruled the art world at that time. They advocated leaving the rooms and painting outdoors. Edouard Manet, one of the pioneers of realism, was among the most influenced people.</p>



<p>The Academy organized Hall exhibitions every year, and it was not possible for a work other than the subjects and styles that they determined. In 1863, Manet and Gustave Courbet wanted to display their works in the Salon, but the jury rejected this request. Since many works were rejected at that time, III. Napoleon opened the Hall of Rejection (Salon des Refusés), stating that the public should have a say in the evaluation of the works. Although many people went to this exhibition just to make fun of it, it was the first time that the idea that art could go out of approved styles and that artists could also exhibit their works outside the Hall. Upon this, independent art communities started to form.</p>



<p>In 1873, a group of Anonymous Artists, Painter Sculptors and Engravers was formally established by painters participating in the meetings, Claude Monet, Pierre-Auguste Renoir, Camille Pissarro, and Alfred Sisley. Later, names such as Paul Cézanne and Edgar Degas joined the community. They held their first independent exhibitions in 1874. Like many visitors, art critic Leroy found this exhibition insufficient and helpless, and in his sarcastic criticism Monet's painting meant Impression: Sunrise, referring to the exhibition as "Impressionists' exhibition". However, Monet and his friends gave this name to Leroy, and gave the same name to the exhibition they will organize a few years later. They held eight exhibitions between 1874 and 1876.</p>



<p><em>“… We had no black one morning, we used a navy blue instead, and that was the impressionism at that moment.”&nbsp;</em>-Pierre-Auguste Renoir</p>



<p>The artists were creating their works by being influenced by the philosophy of Realism, Japanese Ukiyo-e prints, scientific color theories, and techniques of using light developed with the invention of photography. Their aim was to free and modernize art from its continuing monotony. They depict ordinary moments from everyday life outdoors, leaving pronounced brush strokes, using pure colors that emphasize the effects of light rather than meticulously crafted details. No object was painted flat in one color. Colorful shadows resulted in flickering color effects. They believed that they caught the transience of the moment by focusing on the change of light in their paintings, which they mostly completed outdoors. They argued that the artist should bring the subjective interpretations to the forefront, based on the feelings and thoughts aroused in himself, not the truth, but the realism and objectivity.</p>



<figure class="wp-block-gallery aligncenter has-nested-images columns-2">
<figure class="wp-block-image"><img src="https://i0.wp.com/www.loveinartsz.com/wp-content/uploads/2020/05/Renoir_-_The_Two_Sisters_On_the_Terrace-1.jpg?fit=824%2C1024&amp;ssl=1" alt="" class="wp-image-1796"/><figcaption><em>Two Sisters (On the Terrace)</em>, Pierre-Auguste Renoir, 1881 (2)</figcaption></figure>



<figure class="wp-block-image"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/05/Alfred-Sisley-Landscape-on-the-Banks-of-the-Seine-1875.jpg" alt="" class="wp-image-1795"/><figcaption><em>Landscape on the Banks of the Seine, </em>Alfred Sisley, 1875 (3)</figcaption></figure>



<figure class="wp-block-image"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/05/p1-945x756-1.jpg" alt="" class="wp-image-1794"/><figcaption><em>The Boulevard Montmartre on a Winter Morning, </em>Camille Pissarro,1897 (4)<br></figcaption></figure>



<figure class="wp-block-image"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/05/the-seine-at-bercy-1878.jpgLarge.jpg" alt="" class="wp-image-1798"/><figcaption><em>The Seine at Bercy, </em><a href="https://www.wikiart.org/en/paul-cezanne" rel="nofollow">Paul Cezanne,</a><a class="aioseop-link" href="https://www.wikiart.org/en/paul-cezanne"> 1878</a> (5)</figcaption></figure>
</figure>



<p>Despite the criticism and opposition they faced, they insisted on their ideas. The works of the Impressionists, one of the leading groups in the development of modern painting art, started to be accepted by the public over time.</p>



<p class="has-small-font-size">Source<em>: Hodge Susie, Gerçekten Bilmeniz Gereken 50 Sanat Fikri, Domingo yayınları, İstanbul 2013 (sy. 76-79)</em></p>



<p class="has-small-font-size"><em>Images:</em></p>



<div class="wp-block-group alignwide">
<p class="has-small-font-size">1: <a href="https://en.m.wikipedia.org/wiki/Impressionism">https://en.m.wikipedia.org/wiki/Impressionism</a>&nbsp;&nbsp;</p>



<p class="has-small-font-size">2: <a href="https://www.britannica.com/biography/Pierre-Auguste-Renoir/Rejection-of-Impressionism" class="aioseop-link">https://www.britannica.com/biography/Pierre-Auguste-Renoir/Rejection-of-Impressionism</a></p>



<p class="has-small-font-size">3: <a href="https://eportfolios.capilanou.ca/annikamcfarlane/2018/11/02/camille-pissarro/" class="aioseop-link">https://eportfolios.capilanou.ca/annikamcfarlane/2018/11/02/camille-pissarro/</a></p>



<p class="has-small-font-size">4: <a href="https://drawpaintacademy.com/alfred-sisley/" class="aioseop-link">https://drawpaintacademy.com/alfred-sisley/</a>&nbsp; </p>



<p class="has-small-font-size">5: <a href="https://www.wikiart.org/en/paul-cezanne/the-seine-at-bercy-1878" class="aioseop-link">https://www.wikiart.org/en/paul-cezanne/the-seine-at-bercy-1878</a></p>
</div>$tag2$ WHERE slug = 'what-is-impressionism';
UPDATE posts SET content = $tag2$<figure class="wp-block-image aligncenter is-resized"><img src="https://upload.wikimedia.org/wikipedia/commons/thumb/6/6b/Parmigianino_-_Madonna_dal_collo_lungo_-_Google_Art_Project.jpg/1200px-Parmigianino_-_Madonna_dal_collo_lungo_-_Google_Art_Project.jpg" alt="Uzun Boyunlu Meryem - Vikipedi
Madonna with the lonf neck" style="width:454px;height:730px"/></figure>



<p class="has-text-align-justify">In this article, I will describe Madonna with the long neck, one of the most important works of Parmigianino, but first of all, I would like to explain the changes in painting and sculpture with the end of the Renaissance. With the Renaissance, it was thought that art had reached the highest point that could be reached, but the Mannerism and Renaissance rules disappeared and the artists put forward their aesthetic understanding. The figures have moved away from naturalness and realism and their proportions have deteriorated; asymmetric compositions were preferred to give up the stable compositions where balance was achieved. Perspective depths of unrealistic pictures were also made.</p>



<p class="has-text-align-justify">If we return to our work, the original name of Long-Necked Virgin Mary is Madonna dal Collo Lungo and it is oil painting on the panel. In 1534, Elena Baiardo, one of Parma's ruling family, ordered the altar board of the Santa Maria dei Servi, the family chapel, to Parmalı Parmigianino. The painting, the production of which began in 1534, is left unfinished with the death of Parmigianino in 1540. Today it is exhibited in Galleria degli Uffizi in Florence.</p>



<h2 class="wp-block-heading">Details of the picture</h2>



<p class="has-text-align-justify"> The picture shows Madonna in the middle, the angel group on the left and Saint Jerome on the right. Parmigianino chose to disrupt the proportions of Mary's body in order to show grace in the Mannerist understanding; He depicted a long-necked, small-toe body with an imposing body and fingers that seemed like long bones. Mary's flying dress has taken on the task of balancing the background and foreground. </p>



<figure class="wp-block-image size-large"><img src="https://www.loveinartsz.com/wp-content/uploads/2021/04/madonna-with-long-neck-detay-.png" alt="Madonna with the long neck" class="wp-image-7046"/></figure>



<p class="has-text-align-justify">The child has a rather large body in the lap of Mary in Jesus. The fact that the angels are stacked on one side is also proof that the picture has left the anxiety of balanced composition heard during the Renaissance period. There is a dark columnar landscape on the background of the painting and it is actually planned as a row of columns. the figure, which is shown quite small, holds a scroll. The reason why St. Jerome is in the picture is because he is a Virgin Mary follower. To the left of the saint is an unfinished figure whose feet are depicted.</p>



<h2 class="wp-block-heading">Where is the Madonna with the long neck on display?</h2>



<p>The painting called The Tall Mary, made by Parmigianino, is currently in the Ufizi Gallery in Florence, Italy. This painting, whose construction date is 1535-1540, belongs to the Renaissance period and was made using the maniyerism movement. Parmigianino's work led to the emergence of mannerism in the light of the Renaissance. According to the Mannerism movement, all the works made during the Renaissance showed the perfect human model, but it should not have been like this. Especially by playing with the height of the figures, they brought the incompatibility to the fore. </p>



<p>Many Madonna paintings and sculptures have been made throughout the history of art. The best known of these are <a href="https://www.loveinartsz.com/michelangelos-pieta-sculpture/">Michelangelo's Pieta</a> statue and Rafello's paintings of Christ and Mary. Madonna literally represents the Virgin Mary and is depicted as embracing Jesus in art history.</p>



<ul>
<li> Name of the painting: Madonna with the Long Neck - Madonna and Child with Angels (1534-1540)</li>



<li>Where:<a href="https://www.uffizi.it/en/the-uffizi" rel="nofollow" title=""> Uffizi</a>, Florence, Italy </li>



<li>Size: 216.5cm x 132.5cm</li>
</ul>$tag2$ WHERE slug = 'madonna-with-the-long-neck-parmigianino';
UPDATE posts SET content = $tag2$<figure class="wp-block-image is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/01/75d55fdaca455fb1d0a159f192d826d5-1.jpg" alt="" style="aspect-ratio:1.3436928702010968;width:395px;height:auto"/></figure>



<p>Benvenuto Cellini, which is one of the important representatives of the trend of maniaism, reflects the features of the maniaist style, namely elegant, complex, mysterious and the artist's full skill to Perseus statue.</p>



<figure class="wp-block-image size-large is-resized"><img src="http://loveinartsz.com/wp-content/uploads/2020/01/42c6bb91796e8cf20ec171b608454fb7-1.jpg" alt="" class="wp-image-269" style="aspect-ratio:0.6674082313681868;width:393px;height:auto"/></figure>



<p> The sculpture, which was built in about 1545-1554, is located in Piazza della Signoria, where it was first built. This statue was made by Duke I. Cosimo. Since the name of Cosimo de Medici will be understood, he belongs to the famous Medici Family.</p>



<p>The subject of the statue is quite clear; Tell the legend of Perseus and Medusa in Greek Mythology. Perseus is the hero who defeated Medusa. Medusa, on the other hand, was cursed by Hera because she tried to seduce Zeus while she was a beautiful and charming person, and those who looked at her turned into stone.</p>



<p>In the continuation of the story, Perseus was prepared to fight Medusa by Athena and Hermes. Athena gave her a mirror-like armor, and Hermes gave her winged hoods and sandals.</p>



<figure class="wp-block-gallery has-nested-images columns-default is-cropped">
<figure class="wp-block-image size-large"><img src="http://loveinartsz.com/wp-content/uploads/2020/01/640px-Perseus_Armed_by_Mercury_and_Minerva_by_Paris_Bordone_-_BMA-1.jpg" alt="" class="wp-image-276"/></figure>
<figcaption class="blocks-gallery-caption wp-element-caption"> Paris Bordone, Hermes ve Athena Tarafından Savaşa Hazırlanan Perseus </figcaption></figure>



<p>Perseus kept his armor towards Medusa during the war, making him come to the eye and Medusa turned into stone. Perseus went to fight another monster by cutting Medusa's head and defeated the monster by holding the cut head against him.</p>



<figure class="wp-block-image size-large is-resized"><img src="http://loveinartsz.com/wp-content/uploads/2020/01/00091401.jpg" alt="" class="wp-image-273" style="aspect-ratio:1.2061248527679622;width:621px;height:auto"/><figcaption class="wp-element-caption">Sebastiano Ricci, Perseus Medusa' nın Kafası ile Phineus' un Karşısında</figcaption></figure>



<p><em>Legend briefly like this now let's get back to the statue.</em></p>



<p>Duke I. Cosimo liked the sculptural project of Cellini, but said that bronze casting would not work in such a detailed sculpture, it was difficult to dissolve. Cellini told him that he was a successful sculptor and that he could overcome it. After starting Cellini sculpture, he sees Cosimo is right because the bronze flows very slowly and does not fill the mold. For this reason, he asks his helpers to burn all the wooden materials in the house and reproduce the fire, but this was not enough. Finally, he managed to pour the bronze into the mold by burning the silver and metals.</p>



<p>It would not be wrong to say that sculpture is a complete reflection of the legend. It is possible to see the details of Hermes' winged cap and sandals, and the cut head of Medusa in the statue.</p>



<figure class="wp-block-image size-large is-resized"><img src="http://loveinartsz.com/wp-content/uploads/2020/01/57e8a59e424257342e103d3642450b5b.jpg" alt="" class="wp-image-271" style="aspect-ratio:0.6642857142857143;width:286px;height:auto"/></figure>



<p>For the location of the statue, we said Piazza della Signoria. Here the statue looks at Michelangelo's David statue (a copy of the original statue) and Bandinelli's Hercules statue. These two statues were symbols of the republic in Florence. They represented a Florence, where the power was in the hands of its citizens.</p>



<p>Look at David and Hercules. It is as if they turned to stone by looking at Medusa in the hands of Perseus.</p>



<figure class="wp-block-image size-large is-resized"><img src="http://loveinartsz.com/wp-content/uploads/2020/01/Adsız-1-1024x469.png" alt="" class="wp-image-274" style="aspect-ratio:2.183368869936034;width:548px;height:auto"/></figure>



<p>In a sense, with the Perseus sculpture of Medici in a humorous way, the impression of repeating these republic sculptures and enemies once again occurred.</p>



<p>These sculptures, in terms of their location and placement, actually said to us, “Something would be so beautiful that it could cut your breath and turn it into stone. A minister gives a political message such as "can be massacred with beauty". Under the aesthetic and artistic aspect of the sculptures, there may be hidden political messages in details such as their location and how they are made.</p>



<p>Cellini also proved his talent by placing his own portrait on the back of Perseus' head.</p>



<figure class="wp-block-image size-large is-resized"><img src="http://loveinartsz.com/wp-content/uploads/2020/01/421c55d70cf89776cccfe7848676c0a6.jpg" alt="" class="wp-image-278" style="aspect-ratio:0.906288532675709;width:445px;height:auto"/></figure>



<div class="wp-block-group">
<p>Source: Khan Academy</p>
</div>$tag2$ WHERE slug = 'details-and-story-of-perseus-sculpture';
UPDATE posts SET content = $tag2$<blockquote class="wp-block-quote"><p><em>O brave, this world is like a shadow; if you follow him, he runs away; If you run, he runs to you.</em></p><cite>1409. beyit</cite></blockquote>



<p class="has-text-align-justify">Yûsuf Has Hâcib, one of the 11th century Karahanli Turks, was born in a noble family in Balasagun. He wrote his work in Balasagun in a year and a half and completed it in Kashgar (6645th couplet) and presented to Tavgaç Uluğ Buğra Han, the son of Süleyman Arslan Hakan, the head of the Karahanites. The work was written in the Hakaniye dialect, also called Karahanlıca. We have three copies of Kutadgu Bilig known to date, one in Uighur and two in Arabic letters.</p>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/hacip.jpeg" alt="" class="wp-image-2086" width="771" height="508"/><figcaption><em>Balasagunlu Yûsuf Has Hâcib</em> (Image: Turktoyu.com)<br></figcaption></figure>



<p class="has-text-align-justify">Kutadgu Bilig (kut + ad-gu bil-ig “knowledge of being happy”) is a work written in order to show people the path to be followed in both worlds, not a dry book of advice, as it is alleged, but a human teaching book. It is a system of life philosophy that determines the meaning of his life and determines his duties in society and therefore in the state. Yûsuf Has Hâcib has artfully focused on what is the mentality, knowledge and virtues that are essential for the ideal organization of society and state life, which are closely connected to each other, how to obtain and use them.</p>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://i2.wp.com/www.loveinartsz.com/wp-content/uploads/2020/06/kutadgu-bilig-1.jpg?fit=1024%2C751&amp;ssl=1" alt="" class="wp-image-2087" width="718" height="526"/><figcaption><em>Kutadgu Bilig’in Kahire nüshasının ilk iki sayfası</em></figcaption></figure>



<p class="has-text-align-justify"><em>Kutadgu Bilig is organized on four principles, and the correct law is represented by Kün-Toğdı (hakan), saadet (kut) Ay-Toldı (vizier), wise Ögdülmiş (vizier's son), end of life (vengeance) Odgurmış (zâhid). Therefore, it would be absolutely correct to say that Kutadgu Bilig is an allegorical work.</em></p>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/Ekran-Alıntısı.png" alt="" class="wp-image-2092" width="720" height="192"/></figure>



<p>We leave you alone with a few excerpts of this immortal work, which has managed to maintain its current and value for nearly a thousand years, appealing to everyone and touching human life.</p>



<blockquote class="wp-block-quote"><p>No matter how much world goods are collected, they are exhausted, one day is over; If the word is written, it remains, travels the world.</p><cite>114. couplet</cite></blockquote>



<blockquote class="wp-block-quote"><p>The ignorant person is always sick; If the disease cannot be cured, the person dies quickly.</p><cite>157. couplet</cite></blockquote>



<blockquote class="wp-block-quote"><p>Youth escapes and life flies; You quickly emigrate from this dreamy world.</p><cite>231. couplet</cite></blockquote>



<blockquote class="wp-block-quote"><p>No matter how good and close a person is, think, can someone else be more cordial than him?</p><cite>517. couplet</cite></blockquote>



<blockquote class="wp-block-quote"><p>Whoever loves man, his defect becomes virtuous; who does not like, his virtue is flawed.</p><cite>534. couplet</cite></blockquote>



<blockquote class="wp-block-quote"><p>Everyone born is doomed to die, and everything that rises to fall.</p><cite>1086. couplet</cite></blockquote>



<blockquote class="wp-block-quote"><p>Every slope has a descent, every hill has a pit, a sorrow of every joy, and a taste for every pain.</p><cite>1087. couplet</cite></blockquote>



<blockquote class="wp-block-quote"><p>Whatever is planted on the ground, it ends again; whatever is given, the same thing is taken in return.</p><cite>1394. couplet</cite></blockquote>



<blockquote class="wp-block-quote"><p>O brave, this world is like a shadow; if you follow him, he runs away; If you run, he runs to you.</p><cite>1409. couplet</cite></blockquote>



<blockquote class="wp-block-quote"><p>Black earth and blue sky, even for revenge, cannot be prevented by God.</p><cite>1800. couplet</cite></blockquote>



<p></p>



<p><em>Source:<br>Yusuf Has Hacip, Kutadgu Bilig, Çev: Ord. Prof Dr. Reşid Rahmeti Arat, Kabalcı Yayınları, İstanbul, 2018<br>Reşid Rahmeti Arat, Kutadgu Bilig, Türk Dil Kurumu Yayınları, Ankara, 1999<br>www.islamansiklopedisi.org.tr/kutadgu-bilig</em><br><br></p>$tag2$ WHERE slug = 'the-art-of-turkish-statism-kutadgu-bilig';
UPDATE posts SET content = $tag2$<figure class="wp-block-image size-large"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/05/1_NueLlU56dce_SRSLdffq9Q.jpeg" alt="" class="wp-image-1785"/></figure>



<p>Writer, screenwriter and philosopher Ayn Rand has been frequently mentioned during her lifetime, but remains a subject of controversy today. While some are regarded as a philosopher who changed the lives of millions of people with their Rational Selfishness, for others, communism is an enemy of capitalism and its ideas do not represent philosophy, but only American propaganda. So what does Ayn Rand say? What is this Objectivism and Rational Selfishness?</p>



<p>Rand's philosophy strongly rejects above all waiver and sacrifice: she says that one should put herself and her life as individuals individually and live with confidence, as a whole, rational, constructive and productive effort.</p>



<p>Mind is the only tool human has to survive. Of course, every person makes their own choices, but it is an issue that needs to be considered for what they should make. It is not moral to act according to one's feelings and temporary ambitions. Morality is the best way to follow the path of mind.</p>



<p>When emotions clash with logic, your mind should be chosen by using force against emotions if necessary. Emotions can be in the interests of the human or sometimes in the face of others; whereas logic gives the effort to make the most appropriate choice regardless of feelings. In this feeling and conflict of mind, he talks about love as follows: “Love is a selfish feeling. Love is the choice of a person as a great value, and what you fall in love with is again these meat and bones. ” Love is an agreement reached by the two sides offering something to each other, and according to Rand and when the terms of the agreement contradict the individual's logical selfishness, there should be no or should not.</p>



<figure class="wp-block-image size-large"><img src="https://i1.wp.com/www.loveinartsz.com/wp-content/uploads/2020/05/1_vR_5nJL3bNXAF93N2XO9Bg.jpeg?fit=1024%2C563&amp;ssl=1" alt="" class="wp-image-1784"/></figure>



<p>One should not see the selfish person as someone who says “I do what my life wants without caring”, the selfish person recognizes the rights of others and says:</p>



<blockquote class="wp-block-quote"><p>“I will not manage anyone's life, and I will not let anyone take mine. I will not manage or be governed by anyone. I will not be the master, nor the slave. I will not sacrifice myself for anyone and not sacrifice anyone for myself. ”*</p></blockquote>



<p>Every individual is unique and his originality comes to mind. There is no such thing as a collective brain. There is no such thing as collective thinking. The consensus reached by a group of people can only be called concessions of individuals. Each individual should shape his thinking on his own: a meal can be divided among a group of people but not digested in a single stomach.</p>



<p>As can be seen, it is not at all strange that what he said, especially considering the years of his emergence, had a sense of anti-communist propaganda. In the preface to his first novel, We The Living, he used the following: “When I heard that the communist principle at the age of 12 during the Russian revolution said that man should live for his state, no matter what methods are applied, its consequences are only evil. I thought it would be. ”</p>



<p>It is definitely a remarkable move that he always put the individual in front of the society during his lifetime and accepted the mind as the primary guide in the years when he was advocated by many circles that reason was a limited tool. The fact that his books are still selling today and his supporters are many proof of how much he was accepted and respected, contrary to what he supposed.</p>



<p class="has-small-font-size">*<em>A New Textbook Of Americanism</em></p>$tag2$ WHERE slug = 'ayn-rand-and-objectivism';
UPDATE posts SET content = $tag2$<figure><img src="https://i2.wp.com/www.loveinartsz.com/wp-content/uploads/2020/04/albert-camus.jpg?fit=1024%2C512&amp;ssl=1" alt=""></figure>


<p><em>“There is only one question of philosophy that really matters, suicide. To make a judgment about whether life is worth living is to answer the basic question of philosophy. ”</em></p>



<p>Here is the philosophical essay book of Albert Camus, which focuses on Absurdism. In the book published in 1942 in the same year with his novel, Stranger, Camus addresses themes such as the meaninglessness of life and the absurdity of our existence.</p>



<p>So what is this Absurdism?</p>



<p>He explains Camus Absurdism (or Ridiculousness) using the concept of divorce and implies the compulsory but reluctant separation of two lovers. According to him, Absurt is “the divorce of the world that desires the hope and the mind, the unity is the longing, this is the contradiction that connects them with the scattered universe” 1.</p>



<p>While they are often confused with Existentialism, they are of course not the same. To put it briefly:</p>



<p>While nihilism argues that life really does not make sense and the effort to create meaning is useless, Existentialism maintains that people are in a universe without meaning and that they can create their own meaning. On the other hand, Absurdism admits that life has no meaning, and that the effort to find the meaning will ultimately fail; but he still says that people should accept Absurd (the contradictory coexistence of this meaningless world of humankind and those who are meaningless), and they should uphold it and continue to look for it.</p>



<figure class="wp-block-image size-large"><img src="https://i2.wp.com/www.loveinartsz.com/wp-content/uploads/2020/04/5968_PIA17936_fig1-full2-1.jpg?fit=1024%2C464&amp;ssl=1" alt="" class="wp-image-1460"/><figcaption><em>Dünyanın Marstan görünüşü<sup>2</sup></em></figcaption></figure>



<p>It is not placed for a quiz by a creator to the human world and after death, it does not matter what it does in the world. We are not more than biological organisms on a small piece of rock in a universe of great size beyond our perception. While Camus accepts the absurdity and insignificance of our lives here, he avoids the pessimism of Nihilism. Yes, whatever we do, our lives will end, yes everything we do will be forgotten throughout our lives, but we still have to continue. Camus, who likens the person to Sisyphus: In Greek Mythology, the king, who forever carried a rock on a hill, was punished with re-transport after falling from the hill. And he adds: "It is necessary to think that Sisyphus is happy."</p>



<p>Life can be lived happily during its lifetime. Sometimes a short time between friends, even the pleasure of eating or listening to a favorite song is enough to make us happy. One's rebellion against meaninglessness is ultimately to be happy.</p>



<p class="has-small-font-size"><em><em>1, Le Mythe de Sisyphe sayfa 48</em></em></p>



<p class="has-small-font-size"><em>2. https://mars.nasa.gov/resources/5968/bright-evening-star-seen-from-mars-is-earth/?site=msl</em></p>$tag2$ WHERE slug = 'albert-camus-and-absurdism';
UPDATE posts SET content = $tag2$<p class="has-text-color has-very-dark-gray-color">Some people feel unrelated and create areas of representation since their existence. It pours the depths of your soul into the paper, canvas or frame, and reveals it. Now, we will examine life, depression and gradual disappearance from the eyes of such a beautiful soul.</p>



<p class="has-text-color has-very-dark-gray-color">Born in 1958, in Denver, Francesca Woodman was the daughter of a painter father, a ceramist mother. He started taking photos when she was 13 years old. He studied at Rhode Island School of Design between 1975-79. Then he went to Rome and held his first personal photo exhibition on the lower floor of the Maldoror Bookstore.</p>



<figure class="wp-block-gallery aligncenter columns-1"><ul class="blocks-gallery-grid"><li class="blocks-gallery-item"><figure><img src="https://www.loveinartsz.com/wp-content/uploads/2020/04/0x0-011.jpg" alt="" data-id="1432" data-link="https://www.loveinartsz.com/?attachment_id=1432#main" class="wp-image-1432"/></figure></li></ul></figure>



<p class="has-text-color has-very-dark-gray-color"><a class="aioseop-link">Woodman used old decors, ceilings, walls, wallpapers, plasters in his photographs and made them a body image. With his body, which became more and more transparent, he passed through the walls and got out of his self. He described the depression in which he was in, sometimes with a blurred body and sometimes with long exposures. Woodman, who did not hesitate to hide his body, reflected his sense of identity by hiding his face. He made his body a part of the decor and gradually depicted his disappearance in each photograph.</a></p>



<figure class="wp-block-gallery columns-3 is-cropped"><ul class="blocks-gallery-grid"><li class="blocks-gallery-item"><figure><img src="https://www.loveinartsz.com/wp-content/uploads/2020/04/2b26c7db45e1bd8317a96b90007563fc.jpg" alt="" data-id="1433" data-link="https://www.loveinartsz.com/?attachment_id=1433#main" class="wp-image-1433"/></figure></li><li class="blocks-gallery-item"><figure><img src="https://www.loveinartsz.com/wp-content/uploads/2020/04/5380b8ed376ede1cbf080179d1e31ae6.jpg" alt="" data-id="1434" data-link="https://www.loveinartsz.com/?attachment_id=1434#main" class="wp-image-1434"/></figure></li><li class="blocks-gallery-item"><figure><img src="https://www.loveinartsz.com/wp-content/uploads/2020/04/4fa29596823121428c60674ce31a871c.jpg" alt="" data-id="1435" data-full-url="https://i1.wp.com/www.loveinartsz.com/wp-content/uploads/2020/04/4fa29596823121428c60674ce31a871c.jpg?fit=564%2C550&amp;ssl=1" data-link="https://www.loveinartsz.com/?attachment_id=1435#main" class="wp-image-1435"/></figure></li></ul></figure>



<p class="has-text-color has-very-dark-gray-color"><a class="aioseop-link">Even though Woodman said “ghost pictures” for his photographs that started to disappear day by day while being clearer and lively at the beginning, most historians defined his photographs as “Angels”. Kim Knoppers said “a figure that is and is not at the same time” about the Angel theme. Woodman's photographs include appearance and disappearance.</a></p>



<figure class="wp-block-gallery columns-3 is-cropped"><ul class="blocks-gallery-grid"><li class="blocks-gallery-item"><figure><img src="https://www.loveinartsz.com/wp-content/uploads/2020/04/83a6d5189f4f38a938ac4e8d4abb4592.jpg" alt="" data-id="1437" data-full-url="https://i2.wp.com/www.loveinartsz.com/wp-content/uploads/2020/04/83a6d5189f4f38a938ac4e8d4abb4592.jpg?fit=550%2C550&amp;ssl=1" data-link="https://www.loveinartsz.com/?attachment_id=1437#main" class="wp-image-1437"/></figure></li><li class="blocks-gallery-item"><figure><img src="https://www.loveinartsz.com/wp-content/uploads/2020/04/d7hftxdivxxvm.cloudfront.jpg" alt="" data-id="1438" data-full-url="https://i2.wp.com/www.loveinartsz.com/wp-content/uploads/2020/04/d7hftxdivxxvm.cloudfront.jpg?fit=400%2C400&amp;ssl=1" data-link="https://www.loveinartsz.com/?attachment_id=1438#main" class="wp-image-1438"/></figure></li><li class="blocks-gallery-item"><figure><img src="https://www.loveinartsz.com/wp-content/uploads/2020/04/0x0-005.jpg" alt="" data-id="1436" data-full-url="https://i1.wp.com/www.loveinartsz.com/wp-content/uploads/2020/04/0x0-005.jpg?fit=390%2C400&amp;ssl=1" data-link="https://www.loveinartsz.com/?attachment_id=1436#main" class="wp-image-1436"/></figure></li></ul></figure>



<blockquote class="wp-block-quote"><p><a class="aioseop-link">'' In the late 1970s, photography was not a trendy medium. Woodman's work did not attract attention. He sent his self-portraits and fashion photography efforts to all the major New York cultural magazines that ignored him. At the same time, the National Art Foundation rejected the grant application. ''</a></p><cite><a class="aioseop-link" href="https://www.artsy.net/article/artsy-editorial-reevaluating-francesca-woodman-early-death-haunts-groundbreaking-images">source</a></cite></blockquote>



<figure class="wp-block-gallery aligncenter columns-1"><ul class="blocks-gallery-grid"><li class="blocks-gallery-item"><figure><img src="https://www.loveinartsz.com/wp-content/uploads/2020/04/francesca-woodman-untitled-rome-italy-1977-78-c-george-and-betty-woodman-840x8251-e1569491798851.jpg" alt="" data-id="1439" data-full-url="https://i0.wp.com/www.loveinartsz.com/wp-content/uploads/2020/04/francesca-woodman-untitled-rome-italy-1977-78-c-george-and-betty-woodman-840x8251-e1569491798851.jpg?fit=640%2C629&amp;ssl=1" data-link="https://www.loveinartsz.com/?attachment_id=1439#main" class="wp-image-1439"/></figure></li></ul></figure>



<p class="has-text-color has-very-dark-gray-color">Francesca, when she was only 23 in 1981, ended her life by jumping from the window of her building in New York. The mysterious spirit of Woodman is described as the representative of the spirit of Sylvia Plath in the photo. Because, like Plath, he created a space of reality outside of his body and pushed the limits of his soul. It is also possible for us to get the same feeling from Frida Kahlo, the owner of the words "I am painting my own truth."</p>



<p class="has-text-color has-very-dark-gray-color">Francesca Woodman cast her silent screams into her frame through her body, revealing her own truth and flew to eternity. A surrealist, nudist and feminist photographer has announced his name in history.</p>



<p class="has-text-color has-very-dark-gray-color">We are grateful for hosting us in the depths of your soul, Francesca …</p>



