UPDATE posts SET content = $tag2$<blockquote class="wp-block-quote is-style-default"><p><em>Musa elinde iki antlaşma levhasıyla Sina Dağı’ndan indi. Rable konuştuğu için yüzü ışıldıyordu, ama kendisi bunun farkında değildi. Harun’la İsrailliler Musa’nın ışıldayan yüzünü görünce, ona yaklaşmaya korktular. Musa onları yanına çağırdı. Harun’la İsrail topluluğunun bütün önderleri çevresine toplandılar. Musa onlarla konuştu. Sonra herkes ona yaklaştı. Musa Rabbin Sina Dağı’nda kendisine bildirdiği bütün buyrukları onlara verdi.</em></p><p><em>Konuşmasını bitirdikten sonra, yüzüne bir peçe taktı. Ama ne zaman konuşmak için Rabbin huzuruna çıksa, ayrılıncaya kadar peçeyi kaldırırdı. Dönünce de kendisine verilen buyrukları İsrailliler’e bildirir, İsrailliler de onun ışıldayan yüzünü görürlerdi. Sonra Musa içeri girip Rable görüşünceye kadar yine peçeyi takardı. </em></p><cite>(Exodus 34)</cite></blockquote>



<figure class="wp-block-gallery aligncenter has-nested-images columns-default">
<figure class="wp-block-image size-medium"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/1_GqZWG8oCY7W6rkfxwHzPXw-267x400.jpeg" alt="" class="wp-image-2342"/></figure>
</figure>



<p class="has-text-align-justify">Michelangelo'nun Musa'sına baktığımızda bu sahnenin bir canlandırmasını görürüz. Musa'nın Hükmü (Mosè), günümüzde Roma'da San Pietro in Vincoli isimli küçük bir kilisede 'saklanan' Papa II. Julius’un mezarı için yaptırılmış olan bir lahittir. Aslında 40 heykelden oluşan büyük bir yapıda 3.74 metre yukarıda oturması planlanan Musa heykeli verilen son biçiminde alt sıranın ortasında oturur şekilde görünmektedir.</p>



<figure class="wp-block-gallery aligncenter has-nested-images columns-default">
<figure class="wp-block-image size-large"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/unnamed-1.jpg" alt="" class="wp-image-2344"/></figure>
</figure>



<p class="has-text-align-justify">İncil'in Mısır'dan Çıkış kısmında da anlatılageldiği üzere on emiri aldıktan sonra dağdan inen Musa, halkının yaptığı boğa heykelini ve ona tapındıklarını görünce sinirlenmiş, elindeki tabletleri yere atarak parçalamış ve boğa heykelini de parçalayarak yok etmiştir (Exodus 32). Ardından tekrar rabbin yanına giderek levhalarla yeniden dönmüştür. Bu heykelde de bu anı görmekteyiz. Musa, tabletleri sağ kolunun altında tutmakta, sol eliyle de sakalını okşamaktadır. Sağ ayağı yere sağlam basarken sol ayağı her an harekete hazır gibi durmaktadır. </p>



<figure class="wp-block-gallery aligncenter has-nested-images columns-default">
<figure class="wp-block-image size-large"><img src="https://i2.wp.com/www.loveinartsz.com/wp-content/uploads/2020/06/D4HuqfEXsAAr2g6.jpg?fit=1024%2C683&amp;ssl=1" alt="" class="wp-image-2346"/></figure>
</figure>



<p class="has-text-align-justify">Vücuduna bakıldığında oldukça dinç ama aynı zamanda bilge, neredeyse bir tanrı görümündedir. Saçları ve sakalı çok tanrılı dönemlerde yapılan deniz tanrılarının heykellerindekiler gibi uzundur ve kafasının üstünde iki adet boynuz vardır. Bunun sebebi Michelangelo'nun İncil çevirisindeki bir hatayı göze sokma istenci olabilir. Yukarıda da geçen pasajda belirtildiği gibi; "<em>Musa elinde iki antlaşma levhasıyla Sina Dağı'ndan indi. Rable konuştuğu için yüzü ışıldıyordu, ama kendisi bunun farkında değildi." </em>(Exodus 34:29) Burada bahsi geçen ışıldamak kelimesinin İbranicedeki söylenişi ile Zulkarneyn (iki boynuzlu) kelimesinin telafuzu karştırıldığı için Michelangelo Musa’nın başına iki boynuz yerleştirmiştir. Musa'nın kıyafetlerinin üstünde bir akış görmek mümkündür; çeşitli gölge oyunları ve ustalıkla beraber onun neredeyse kanlı canlı bir adam gibi hareket edebileceğini ummak çok da garip kaçmaz. Ayrıca bakışlarında halkına karşı olan kırgınlığı ve öfkesini sezinlemek de mümkündür. Anlatılana göre Michelangelo heykeli bitirdikten sonra karşısına geçmiş ve "Konuş!" demiş, hatta elindeki malzemeleri atıp "Ayağa kalk!" diye seslenmiştir. Heykele bakıldığında gerçekten de her an yerinden kalkıp bize doğru harekete geçeceği düşüncesini akıldan geçirmek mümkündür. Ayrıca saçları, sakalı, boynuzları ve biçimiyle gözümüze normal bir insandan ziyade bir tanrıymış gibi görünür. Bu sebepten olsa gerek, papalık heykeli Roma'da gözden uzak bir noktaya atmıştır ancak günümüzde bile birçok kişi, özellikle de Yahudi kökenli insanlar bu heykeli görmek için bu küçük kiliseciğe ziyarette bulunmaktadır. Bu ziyaretlerden en meşhuru da Freud'un ziyaretidir.</p>



<figure class="wp-block-gallery aligncenter has-nested-images columns-default">
<figure class="wp-block-image size-large"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/480px-Moses_by_Michelangelo_JBU310.jpg" alt="" class="wp-image-2345"/></figure>
</figure>



<p><em>Musa döndü, elinde antlaşma koşulları yazılı iki taş levhayla dağdan indi. Levhaların ön ve arka iki yüzü de yazılıydı. Onları Tanrı yapmıştı, üzerlerindeki oyma yazılar O’nun yazısıydı. Yeşu, bağrışan halkın sesini duyunca, Musa’ya, “Ordugahtan savaş sesi geliyor!” dedi. Musa şöyle yanıtladı: “Ne yenenlerin, ne de yenilenlerin sesidir bu; Ezgiler duyuyorum ben.”</em>                                                                                                                                                           <em>Musa ordugaha yaklaşınca, buzağıyı ve oynayan insanları gördü; çok öfkelendi. Elindeki taş levhaları fırlatıp dağın eteğinde parçaladı. Yaptıkları buzağıyı alıp yaktı, toz haline gelinceye dek ezdi, sonra suya serperek İsrailliler’e içirdi.</em> (Exodus 32)</p>



<p class="has-text-align-justify">Freud'un 1901 yılındaki Roma gezisi sırasında ziyaret ettiği Musa heykeli, onda Stendhal Sendromu benzeri bir rahatsızlığın tezahürüne sebep olmuştur. Hatta ailesine mektubunda "sürekli olarak Roma'da yaşayamamak ne acı!" diye yazmıştır. 1912 yılındaki seyahatinde de eşine yazdığı mektupta her gün kiliseye gidip heykeli gördüğünü, onun üzerine bir deneme kaleme almayı düşündüğünü belirtir. Bu düşünce, 1939 yayımlanan Musa Denen Adam ve Tektanrıcılık kitabının temeli olur.</p>



<p class="has-text-align-justify">Freud, Musa ile ilgili çalışmalarında heykelin Mısır'dan Çıkış 34'ü değil 32'yi betimlediğini anlatmaktadır. Ki bu çok da yanlış bir düşünce olmaz; Musa'nın gözlerindeki öfke ve hayal kırıklığı, kendini tutmak adına sakalına sarınması ve tabletleri kavrama şekliyle her an bir patlamaya hazır olduğunun sinyalini vermektedir.</p>



<p class="has-text-align-justify">Sonuç olarak; Michelangelo'nun bu Musa tasviri, üzerinden 500 sene geçmesine rağmen insanları ilk günkü gibi büyülemeye devam etmektedir.</p>



<div class="wp-block-group">
<h4><strong>Kaynaklar:</strong></h4>



<p><em>İncil</em></p>



<p><em>Bir Peri Masalı: Freud'un Aile ve Tarihsel Romanı- Serol Teber/ Okuyan Us Yayınları</em></p>



<p><em>Musa Heykelinin Sırrı- Semih Yakut</em></p>
</div>$tag2$ WHERE slug = 'michelangelonun-musasi-ve-ziyaretcisi';
UPDATE posts SET content = $tag2$<div class="wp-block-image"><figure class="aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/Michelangelo_Pieta-1.jpg" alt="" class="wp-image-2337" width="572" height="597"/></figure></div>



<p>Pietà, one of Michelangelo's early works, is the only statue he made at the age of twenty and wrote his name on.</p>



<div class="wp-block-image"><figure class="aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/michelangelo-imza.jpg" alt="" class="wp-image-2330" width="477" height="357"/></figure></div>



<p>Pietà, a subject frequently studied after the fifteenth century, is the statue of Mary holding the dead Jesus in her arms. Michelangelo made this work on the order of the French Bishop Jean de Bilheres, who lived in Rome. He is currently in St. Peter's Basilica in the Vatican.</p>



<p>The work has a different mood. Although what we expect to see at first glance is sadness and pain, there is no trace of the suffering that Jesus had on his face. As if a newborn baby is asleep in her mother's lap … It is obvious from every situation that Mary does not want to leave her son.</p>



<p>Michelangelo described Mary as a young girl in her 20s, whereas when Jesus was crucified, her mother was in her fifties. Michelangelo stated the reason for this as an emphasis on the virginity of Mary. In addition, Mary's head is smaller than her body, which, according to Michelangelo, is a giant mother who lost her dead son.</p>



<div class="wp-block-image"><figure class="aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/1pieta4-872x1024-1.jpg" alt="" class="wp-image-2331" width="497" height="581"/></figure></div>



<p>Let's look carefully at Mary's sadness. Mary has just taken her son from the cross and holds her dead body like holding a baby. As the dead body is heavily kneeled but not complaining about the situation, we see how he grasped the bottom of the arm of Jesus with his left hand and how the skin got tense, as he did not want to leave his son. These are the silent screams of a mother who has just lost her son …</p>



<div class="wp-block-image"><figure class="aligncenter size-large"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/Michelangelo_Pieta2w.jpg" alt="" class="wp-image-2332"/><figcaption>Pieta el detayı</figcaption></figure></div>



<p>Although Michelangelo made the two human bodies in this statue made of marble, it turned it into a flesh. We can understand the weight of the body and that it belongs to a lifeless body. The pain of Mary is reflected in the expression on her face. She is extremely beautiful and young. Despite this youth, he can bear the weight of a dead body. This is one of two important contrasts in the work. The other is the immobility of one of the figures, the mobility of the other. So life and death …</p>



<p>The processing of marble is very important. Drapes on the fabric of Mary's dress, the legs of Jesus, the surfaces on the figures, make the statue stand alive.</p>



<p>The head of Christ is lying behind, his foot lying vulnerable in the air. Mary's questioning the situation with her left hand open.</p>



<div class="wp-block-image"><figure class="aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/İsa.jpg" alt="" class="wp-image-2333" width="321" height="336"/></figure></div>



<p>Sculpture, St. Too small (174 x 195 cm) compared to the Peters Basilica. Because when it was first made, an order was placed for Kardinal, but later on the old St. It was placed in Peters. St. The Peters Church was also smaller than before. For this reason, the sculpture looks smaller than the architecture. Although it seems small compared to its location, it has taken its place in history as a great work in terms of its importance and the emotions it arouses in the audience.</p>



<p>If you want to see the huge beauty of the basilica and Pietà, you can visit it online here.</p>



<p><em>Source:</em></p>



<p>Khan Academy</p>



<p><em>Sanatın Büyük Ustaları/ Michelangelo, Hayalperest Yayınları</em></p>$tag2$ WHERE slug = 'michelangelos-pieta-sculpture';
UPDATE posts SET content = $tag2$<blockquote class="wp-block-quote is-style-default"><p><em>Moses descended from Mount Sinai with two treaty signs in his hand. Rable was glowing because he spoke, but he wasn't aware of it. When Harun and the Israelites saw the shining face of Moses, they were afraid to approach him. Moses called them over. Harun and all the leaders of the Israeli community gathered around him. Moses spoke to them. Then everyone approached him. Moses gave them all the commandments the Lord had reported to him on Mount Sinai.</em></p><p><em>After finishing her speech, she wore a veil on her face. But whenever he appeared before the Lord to speak, he would raise the veil until he left. Upon his return, he informed the Israelites about his commands, and the Israelites saw his glowing face. Then Moses wore the veil again until Rable saw him.</em></p><cite>(Exodus 34)</cite></blockquote>



<figure class="wp-block-gallery aligncenter has-nested-images columns-default">
<figure class="wp-block-image size-medium"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/1_GqZWG8oCY7W6rkfxwHzPXw-267x400.jpeg" alt="" class="wp-image-2342"/></figure>
</figure>



<p class="has-text-align-justify">When we look at Michelangelo's Moses, we see an animation of this scene. The Ruling of Moses (Mosè) is Pope II, who is 'hiding' today in a small church called San Pietro in Vincoli in Rome. It is a sarcophagus built for the grave of Julius. In fact, in a large building consisting of 40 sculptures, the Moses statue, which is planned to sit 3.74 meters above, appears to sit in the middle of the lower row in its final form.</p>



<figure class="wp-block-gallery aligncenter has-nested-images columns-default">
<figure class="wp-block-image size-large"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/unnamed-1.jpg" alt="" class="wp-image-2344"/></figure>
</figure>



<p class="has-text-align-justify">As described in the Bible's Exit from Egypt section, Moses, who got down from the mountain after taking the ten commandments, got angry when he saw the bull sculpture he made by his people and worshiped him, he threw the tablets in his hands and destroyed the bull sculpture by destroying it (Exodus 32). Then he went to the Lord again and returned with the plates. We see this moment in this statue. Moses holds the tablets under his right arm and caresses his beard with his left hand. While his right foot is firmly on the ground, his left foot is ready to move at any time.</p>



<figure class="wp-block-gallery aligncenter has-nested-images columns-default">
<figure class="wp-block-image size-large"><img src="https://i2.wp.com/www.loveinartsz.com/wp-content/uploads/2020/06/D4HuqfEXsAAr2g6.jpg?fit=1024%2C683&amp;ssl=1" alt="" class="wp-image-2346"/></figure>
</figure>



<p class="has-text-align-justify">Looking at her body is quite vigorous but also wise, it looks almost like a god. His hair and beard are long, like those in the statues of the sea gods, made in the polytheistic times, and he has two horns on his head. The reason for this may be the willingness of Michelangelo's biblical error to appear. As stated in the passage mentioned above; "Moses came down from Mount Sinai with two treaty signs in his hand. Rable was glowing because he spoke, but he was not aware of it." (Exodus 34:29) Michelangelo placed two horns at the head of Moses, as the word `` luminescence '' was said in Hebrew and the word Zulkarneyn (two horns) was compared. It is possible to see a flow over Moses' clothes; It is not strange to hope that, with various shadow plays and craftsmanship, he can act as an almost bloody alive man. It is also possible to sense the resentment and anger towards his people in his gaze. According to the story, Michelangelo came across after finishing the statue and said "Speak!" he even said, "Stand up!" he called. Looking at the statue, it is really possible to think of the idea that it will get up and act towards us at any moment. In addition, with her hair, beard, horns and shape, she looks to our eyes as a god rather than a normal person. For this reason, the papacy has thrown the statue out of sight in Rome, but even today many people, especially people of Jewish origin, visit this little church to see this statue. The most famous of these visits is Freud's visit.</p>



<figure class="wp-block-gallery aligncenter has-nested-images columns-default">
<figure class="wp-block-image size-large"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/480px-Moses_by_Michelangelo_JBU310.jpg" alt="" class="wp-image-2345"/></figure>
</figure>



<p><em>Moses turned, and came down from the mountain with two stone plates with the terms of the treaty. The front and back sides of the plates were also inscribed. God had made them, the engraving inscriptions on them were his writing. When Joshua heard the shouting people, Moses said, "The sound of war is coming from the camp!" said. Musa replied: “This is neither the voice of the defeated nor the defeated; I hear tunes. ” As Moses approached the camp, he saw the calf and the people playing; He was very angry. He tossed the stone plates in his hand and smashed them at the foot of the mountain. He took the calf they made and burned it, crushed it into powder, then sprinkled it into the water and made it to the Israelites.</em> (Exodus 32)</p>



<p class="has-text-align-justify">The statue of Moses, which Freud visited during his Roman trip in 1901, caused a manifestation of a discomfort like Stendhal Syndrome in him. In fact, in his letter to his family, "What a pain it is not possible to live in Rome constantly!" he wrote. In his letter to his wife during his trip in 1912, he states that he goes to church every day and sees the statue, and that he intends to write an essay on it. This thought becomes the basis of the book Moses Dened and Monotheism, published in 1939.</p>



<p class="has-text-align-justify">In his work on Moses, Freud recounts that the statue depicts 32, not Exit 34, from Egypt. Which is not a very wrong idea; Anger and frustration in Moses' eyes signal that he is ready for an explosion at any time, as he hugs his beard and holds the tablets in order to hold himself.</p>



<p class="has-text-align-justify">As a result; Michelangelo's description of this Moses continues to fascinate people like the first day, even after 500 years have passed.</p>



