UPDATE posts SET content = $tag2$<p class="has-text-align-justify">Mitler; tanrı ve tanrıçaların birbirleriyle olan ilişkilerinin yanı sıra büyük ölçüde de tanrı ve tanrıçaların insanlarla olan ilişkileri neticesinde şekillenmiştir. Bugün bahsini edeceğimiz üzere Yunan mitolojisinde de insanlar ile tanrıların ilişkileri büyük yer kaplar. Kimi gönül ilişkisi, kimi nefret, intikam ve öç alma, kimi kahramanlık ve ölümsüz olma, hatırlanma istenci, kimi de tanrılara aşık atma üzerine kuruludur bu mitlerin.</p>



<p class="has-text-align-justify">Özellikle bilinen iki hikâye vardır ki tanrı ve tanrıçalarla özdeşleşmiş yetenekler üzerinden kurulan bir yarış çerçevesince boyunun ölçüsünü almak zorunda kalan ölümlüleri görürüz. Bunlardan anlatacağım ilk mit bir satir olan Marsyas’ın hikayesidir. Marsyas, kimi anlatılara göre Orpheus'un da babası olan Trakya kralı Oiagros'un, kimi anlatılara göre de aulos adlı müzik aletini icat eden bilindik Frigya müzisyenlerinden biri olan Hyagnis'in oğludur.</p>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/marsyas.-1.png" alt="" width="556" height="358"/></figure>



<p class="has-text-align-justify">Efsaneye göre Athena bir gün Menderes kıyısında yapmış olduğu iki uçlu kavalı çalarken suda yüzünün yansımasını görür ve yüzünün aldığı buruşuk, şişik halden tiksinerek kavalı bir kenara atıp gider. Bir başka anlatıda da bunu yapmasının sebebi olarak Hera ve Afrodit'in onunla dalga geçmesi olduğu gösterilmektedir. Anlatıya göre; Hera ve Afrodit, Athena kaval çalarken yüzünün aldığı şekille dalga geçtikleri için Athena duru bir su kıyısına inerek sudaki aksine bakıp kavalı çalmaya başlar ve bu eylemin yüzünü getirdiği hali görünce sinirlenip kavalı atar ve onu kendisinden sonra kullanacak olan kişiye lanet eder. Bunun ardından durumdan haberi olmayan Marsyas kavalı bulur ve çalmaya başlar. Çıkardığı ses öyle güzel ve doğaldır ki bu müzik aletine hayran kalır, hatta kavalın müziğin tanrısı Apollon'un liriyle yarışabileceğini söyler. Bunun üzerine Apollon bir yarış öne sürer; karşılığında kazanan ne isterse şartsız yerine getirilecektir.</p>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/53dba47a7dbe8010c42fbb5d709f12bf.jpg" alt="" width="371" height="514"/></figure>



<p class="has-text-align-justify">Yarış, tanrı Tmolos'a ait olan Bozdağ'ın eteklerinde yapılır, jüri olarak da dokuz müz ve kral Midas seçilmiştir. Apollon üç telli lirini çalarken müzler de ona eşlik ederek şarkı söylerler. Marsyas kavalını çalmaya başlayınca ise herkes onu hayretle dinler, halk onu alkışlamaya başlar, müzler Apollon'a oy verirken Midas da Marsyas'a oy verir ve böylece eşitlik olur.</p>



<p class="has-text-align-justify">Yarışın sonunda olan eşitliğin bozulması için Apollon bir şart öne sürer. Burada da karşımıza iki farklı anlatı çıkmaktadır: Bir anlatıya göre Apollon lirini ters çevirerek çalmaya başlar ve aynısını Marsyas'ın da yapmasını bekler ancak Marsyas bunu yapamaz. Diğer anlatıya göreyse Apollon lirini çalarken şarkı söyler ve Marsyas'tan da bu beklenir ancak üflemeli bir çalgı çalan Marsyas bunu yapamadığı için kaybetmiş sayılır. Bu halde kral Midas yine de kavalın lirden daha üstün olduğunu söyleyince Apollon tarafından kulakları eşek kulaklarına çevrilerek cezalandırılır. Marsyas ise bir tanrıyla boy ölçüşmenin cezası olarak bir ağaca bağlanır ve derisi yüzülerek öldürülür. Müzler ise bu cezanın gereğinden fazla olduğunu düşünerek yakarmaya, Marsyas için ağıt yakmaya başlarlar. Apollon da verdiği cezadan pişman olup lirini kırar ve bir daha çalmaz, ayrıca Marsyas’ı bir ırmağa çevirir. Marsyas’ın derisinin yüzüldüğü o yerden günümüzde Çine Çayı geçer.</p>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://i0.wp.com/www.loveinartsz.com/wp-content/uploads/2020/06/The_Flaying_of_Marsyas_Roman_Imperial_1st-2nd_century_AD_from_Rome_Louvre_Museum_7462768132.jpg?fit=627%2C1024&amp;ssl=1" alt="" width="399" height="652"/></figure>



<p class="has-text-align-justify">Ne zaman zeytin ağacımın üstünde bir örümcek ağı görsem aklıma gelir Arakne. Anadolulu bir kızın bir Yunan tanrıçasıyla nasıl boy ölçüştüğünü hatırlatır bana. Arakne babası kumaş boyacısı olan Lidya’lı bir kızdır, öyle güzel işlemeler yapar, nakışlar işler ve kilimler dokur ki ünü topraklarının sınırlarını aşar, toprağının kadınlarının gururu olur. Periler düşer peşine, bu ilimi, bu yeteneği kimden aldığını sorarlar, cevap bellidir aslında, bu konuda yetenekli olan kadınlar hep Athena'ya şükran doludur. Ancak Arakne bu yeteneği annesinden aldığını söyler ve Athena'yı bilmediğini, hatta ondan daha iyi bir dokumacı olduğundan emin olduğunu iddia ederek böbürlenir. </p>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/siyah-figür-arachne-1-1024x541-1.jpg" alt="" width="547" height="288"/></figure>



<p class="has-text-align-justify">Athena yaşlı bir kadın kılığında gelerek onu uyarır, böbürlenmesinin iyi bir şey olmadığını söyler ancak Arakne bu uyarıları umursamaz. Athena ile yarışabileceğini söyler. Bunun üzerine Athena üstündeki yaşlı kadın görüntüsünden kurtularak Arakne'ye dokuma tezgahının başına geçmesini söyler ve ikili tezgahlarına odaklanarak yarışa başlarlar. İkisi de öyle hızlı işler ki dokumayı, sadece mekiklerin sesi duyulur çevrelerinde. Athena Atina'yı almak için Poseidon'la yaptığı yarışı resmeder; şehre verdiği zeytin ağacını, Poseidon'un armağanı olan atı. Arakne ise Zeus'un Hera'ya olan sadakatsizliğini dokur tezgahında; bir kuğu şekline bürünüp Artemis ve Apollon'u doğuran Leda'nın koynuna girişini. Athena hem kızın kusursuz iş çıkarmasını kıskanır hem de babasıyla ilgili uygunsuz kaçan bu sahnenin dokunmasına sinirlenir ve Arakne'nin tezgahını, dokumasını paramparça eder. Emekleri ziyan olan kız bir iple kendini ağaca asar ve öldürür. Onun kendi canına kıymasına acıyan tanrıça ise kızı bir örümcek yapar ve o günden sonra örümcekler kuytu köşelere narin ağlarını örerek ömürlerini geçirirler. Takdir görmeden, bir fiskeyle dağılabilecek emekleriyle…</p>



<figure class="wp-block-gallery aligncenter has-nested-images columns-default">
<figure class="wp-block-image size-large"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/luigi-ademollo-arachne-into-a-spider-book-vi-illustration-from-ovid-s-metamorphoses-florence-1832.jpg" alt="" class="wp-image-2448"/></figure>
</figure>



<p class="has-text-align-left">Bu iki hikâyenin de ölümlü kahramanlarının Anadolulu oluşu ilginç bir tesadüf müdür? Ya da Apollon'un eşek kulaklı yaptığı Midas'ın daha sonra Anadolu kökenli bir tanrı olarak görülen ve Apollon'un karşısına konuşlandırılan Dionysos tarafından tuttuğunun altın edilen bir kral olması? Bu mitler bize anakaradaki Yunanlarla Anadolu'daki devletlerin arasındakileri gözlemlememiz için sunulan anlatılar mıdır? Bilinmez. Ama görülen şudur ki; tanrılarla yarışmaktan pek hayır gelmez.</p>



<p><strong>Kaynaklar</strong>:</p>



<div class="wp-block-group">
<p>Hey Koca Yurt - Halikarnas Balıkçısı</p>



<p>Mitoloji Sözlüğü - Azra Erhat</p>



<p>Örümceğe Çevrilen Arakne ve Ağları - Cansu Altaş</p>



