</div>



<p></p>$tag2$ WHERE slug = 'tanrilara-meydan-okumanin-sonu-marsyas-ve-arakne';
UPDATE posts SET content = $tag2$<p>Bir atölye dersimde konuşulan ve çok saygı duyduğum bir hocamızın bize yönelttiği bir soruydu bu. Gördüğümüz, gördüğümüz müdür? Aslında bir evet veya hayır gibi net bir cevap beklesek de sorunun özüne bakarak; sanatın, sanatçıların, felsefi düşünürlerin yüzyıllardır bu soruyu dolaylı yoldan sorduğunu anlayabiliriz. Çünkü görmek varlığa açılan bir kapıdır. Varlık ise bize çok daha derin bilgi ve gizem havuzlarının olduğu kapıları açar. Bu yüzden bu soruya cevap vermeden önce daha önce bu soruya benzer soruları sormuş, yanıt aramış ve üzerine düşünüp deneyler yapmış, tarihimizden bize kalan kaynaklara bakalım.<br>Bir resim hayal edelim, sevdiğimiz bir tabloyla ilk kez karşılaştığımızı ya da o tabloyu ilk incelemenizi yaptınız ve duvarınıza astınız. Aradan aylar, hatta yıllar geçti. Sizin şu an gördüğünüz tablo, ilk kez gördüğünüz tablo ile aynı mıdır? Aynı hisleri mi uyandırır? Ya da sizi ziyarete gelen bir misafir, sizin senelerdir vakit geçirdiğiniz o tabloya bakınca aynı hisleri besler mi? Peki ya çevremiz? Sizce sizin babanızı kaybettiğiniz bir hastanede, çocuğunu doğuran bir kadın, o hastaneye baktığında aynı şeyi mi görür? Bu soruları sorduktan sonra aşağıda bulunan John Berger'in bu videosu, bu hissiyatı size daha kolay aktaracaktır.</p>



<p>Görmek, dil bilgisinde en fazla bir anlama gelirken varlıklar için birden fazla anlama gelmektedir. Eğer görmek insanın zihni, bedeni ve kendi gerçekliği için farklı farklı yorumlanıyorsa, duyuların bileşiminden oluşan o görüntü hiç kimsede aynı sonucu veremeyecek kadar karmaşık varlıklarsak biz gördüğümüz, gördüğümüz değildir.<br>Şimdi ise bu konuyla ilgili yorumlanmış ve basit olan bazı konuları inceleyebiliriz.<br>Öncelikle insanın gerçekliğine bakalım. İnsanın ilk gerçekliği, kendi gözleriyle gördükleri, sonrası ise bilimdir. Kendi gerçekliğinin daha önde olmasının nedeni, insanoğlunun, önüne ne kadar koyarsanız koyun, yine kendi gördüğünü daha doğrusu kendi tecrübeler bütününün ona yüklediği benliğinin görmek istediğini anlaması halinden dolayıdır. Bunun için toplumda görmek, ilk önce bireysel gerçeklik, daha sonrada bilimsel bir gerçekliğe dayanır. Peki ya dünyanın gerçekliği? Zihnimiz bize ne kadar doğru sunuyor?</p>



<p>Bunu düşsel egzersizi  anlamak için, aşağıda John Berger'in ''Görme Biçimleri'' belgeselinden bir kesiti izleyebilirsiniz! </p>



<figure class="wp-block-video aligncenter"><video controls src="https://www.loveinartsz.com/wp-content/uploads/2020/06/JOHN-BERGER.mp4"></video></figure>



<p>"Şunu düşünün: Şu anda, bulunduğunuzu düşündüğünüz yerde değilsiniz. Beyniniz vücudunuzdan ustalıkla çıkarılıyor ve bir laboratuvar tezgahının üstünde duran bir besin kavanozunda canlı halde tutuluyor. Beyninizin sinir uçları, günlük hayatın bütün hislerini size aktaran bir süper bilgisayara bağlı. Bu yüzden tamamen normal bir hayat yaşadığınızı düşünüyorsunuz.<br>Hâlâ var mısınız? Hâlâ "siz" misiniz? Ve bildiğiniz dünya, hayal gücünüzün bir uydurması mı yoksa bu kötü bilim insanı tarafından oluşturulmuş bir yanılsama mı? Kulağa bir kâbus senaryosu gibi geliyor. Fakat bunun doğru olmadığını mutlak kesinlikle söyleyebilir misiniz? Aslında bir kavanozda duran bir beyin olmadığınızı birisine kanıtlayabilir misiniz?"  Düşünür Hilary Putnam, 1981 tarihli kitabı Sebep, Gerçek ve Tarih'te, kavanozdaki beyin adlı düşünce deneyinin bu ünlü örneğini öne sürmüştü, fakat aslında bu, Fransalı düşünür Rene Descartes’ın 1641 tarihli İlk Felsefe Üzerine Derin Düşünceler kitabındaki Kötü Ruh kavramının güncellenmiş bir hâlidir. Bu gibi düşünce deneyleri üstünkörü (ve belki biraz huzur kaçırıcı) gibi görünebilse de faydalı bir amaca hizmet ederler. </p>



<div class="wp-block-image"><figure class="aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/descartes.jpg" alt="" class="wp-image-2396" width="469" height="573"/><figcaption>Bu yazıyı okuduktan sonra bile, Descartes'in bakışları bizde farklı bir anlam uyandırır!</figcaption></figure></div>



<p>Düşünürler bunları kullanarak hangi inanışların doğru olduğuna karar verebileceğimizi ve bunun sonucunda, kendimiz ve etrafımızdaki dünya hakkında ne tür bilgiye sahip olabileceğimizi araştırırlar.<br>Descartes, bunu yapmanın en iyi yolunun her şeyden kuşku duymaya ve bilgimizi buradan inşa etmeye başlamak olduğunu düşünmüştü. Bu kuşkucu yaklaşımı kullanarak, sadece kesin mutlak bir kesinlik özünün bilgi için güvenilir bir esas olarak hizmet göreceğini iddia etmişti. Şöyle söylemişti:<br>“Eğer gerçek bir hakikat arayıcısı olacaksanız, hayatınızda en azından bir kez, her şeyden mümkün olabildiğince şüphe duymak lazımdır.”<br>Descartes, herkesin bu türden felsefî düşünme ile uğraşabileceğine inandı. Çalışmalarından birinde, ahşap kulübesinde şöminenin önünde otururup, piposunu içerkenki bir sahneyi tanımlıyor. O piponun elinde olduğuna veya terliklerinin ayağında bulunduğuna inanıp inanamayacağını soruyor. Bu duyuların, geçmişte onu yanılttığını ve bundan önce yanıltıcı olmuş olan bir şeye güvenilemeyeceğini belirtiyor. Bu yüzden, duyularının güvenilir olduğundan emin olamıyor. Düşünürler tarafından yeğlenen şu gibi klasik kuşkucu soruları Descartes’tan kazandık: Şu an uyanık olduğumuzdan ve uyumadığımızdan, rüya görmüyor olduğumuzdan nasıl emin olabiliriz? Descartes, bu sorunu farz edilen bilgimizin ötesine götürmek için, bizi kandıran, aslında gerçekliğin bize göründüğünden çok farklı olabildiği zaman bizleri kendi hayatımızı yaşadığımıza inandıran her şeye kadir, kötü niyetli bir şeytan bulunduğunu hayal ediyor.<br>''Son derece yüksek güç ve kurnazlığa sahip kötü niyetli bir şeytanın, bütün enerjilerini beni kandırmak için kullandığını varsaymalıyım.'<br>Dış dünyanın duyularımıza nasıl göründüğü konusunda kesin olarak emin olmasak bile, Descartes ikinci derin düşüncesini küçük bir umut parıltısıyla başlatır. En azından kendimizin var olduğundan emin olabiliriz, çünkü bundan kuşku duyduğumuz her seferde, kuşkuyu duyan bir "biz" bulunmalıdır. Bu avuntu, ünlü "Düşünüyorum, o halde varım." ifadesiyle sonuçlanmaktadır.’"<br>Beynimiz, çoğu zaman bize bu tip oyunlar oynayabilir. Ve görmek, diğer duyularımıza da etki eder. Bilim dünyasının bilinen gerçeklerinden olan ama toplumun büyük bir kesiminin bilmediği, hatta duyduğu zaman kavramakta zorlandığı ‘’maddelerin asla birbirine dokunmadığı’’ fikri gibi. Bu bilgiler, görmenin bilimsel dünyada nasıl araştırıldığı ve karşılandığı üzerine kısa bir özet olabilir. Peki ya zihin? İnsan zihni elbette ki bilimsel bir araştırmadan çok daha renkli ve karmaşık bir hal alıyor konusu ‘’görmek’’ olduğu zaman. Ama bana göre, insan zihninde de gördüğümüz, gördüğümüz değildir. Dünyadaki her şey, içine girdikçe değişir ve gelişir. Farklı bir boyut, anlam ve duygu kazanır. İnsanlar da dahil, her şeyin özü ve kabuğu aynı değildir. Bir insanı ilk gördüğünüzde ki hali ile, onu tanıdığınızdaki hali aynı değildir. Eğer aynı olsaydı, ne felsefe olurdu, ne duygular olurdu, ne de sanat. Bana göre insan bir cismi, bir insanı, bir dokuyu ve hatta hayatı keşfettikçe, artık ne o cisim ilk gördüğü renktedir, ne de o insan ve doku, aynı ışığa sahiptir.</p>



<blockquote class="wp-block-quote"><p>“… ne gördüğümüzü söylememiz boşunadır; çünkü gördüğümüz söylediğimizin içine hiçbir zaman yerleşmiş değildir.” </p><cite><em>(M. Foucault)</em></cite></blockquote>



<p>Sanat dünyasında görmeye gelecek olursak, bana göre görmek sanatı oluşturan en önemli parçadır. Asırlar boyunca sanatçılar, görmeyi, farklı boyutlara taşımış ve bunu sanatına yansıtarak öncü olmuşlardır. Çoğu sanatçı, görmeyi öğrenirken düşünürlerden ilham almışlar ve onlardan çok şey öğrenmişler. Görmeye çalışmak, görmeyi öğrenmek, sadece sanatı değil, dünyayı, sanatçıları ve sanatçıların eserlerinde anlatmak istediklerini de bir nebze de olsa anlamamızı sağlar. Ama her sanatçı, eserlerinde ‘’görmeyi’’ farklı boyutlara taşısa da, hepsinin görme yolundaki başlangıcı aynıdır bana göre.</p>



<p>Bates Lowry’e göre ''görmek'' nedir kısa bir göz atalım;<br>"Görme, ancak gayretle elde edilebilecek bir iştir; görmeyi öğrenebiliriz. Önce basit şekilde çevremize bakarak başlar, her gün karşılaştığımız şeyleri inceleyebiliriz. Ancak bir masaya sadece bakacak, nasıl bir şey olduğunu otomatik şekilde algılayarak ondan bir imge elde edecek yerde biçimini incelemeli, masa üstü düzeyine dikey bacakların nasıl bağlandığına, köşelerin nasıl birleştiğine, oymalarına dikkat etmeliyiz. Görmek, gözümüzü alabildiğine açmaktan ibaret de değildir. Asıl gözümüzü neyin üzerinde yoğunlaştıracağımızı düşünmeliyiz. Eğer görmek istiyorsak, gözümüz ve zihnimiz beraber çalışmalı. Nasıl görmek gerektiğini yalnız kitap okumakla öğrenemeyiz. Görmeyi kendimiz görerek öğrenmeye başlarız. Nasıl görmek gerektiğini öğrenmek için, aslında yapacağımız şey, görsel biçimlere kendimizi alıştırmaktır. Bu alışkanlığı, çevremizdeki nesnelerle temas miktarını sürekli şekilde artırarak elde ederiz. Bir öğretmenin veya tenkitçinin gözüyle, yani iğreti olarak görme, bize güvenilir bir alışkanlık, sağlam bir tecrübe vermez. Görsel imgeler dünyasında emniyetli ve içten görüş tecrübe ve bilgisini, yanlız kişisel deneylerimizle sağlayabiliriz.</p>



<div class="wp-block-image"><figure class="aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/c4b668b6e04cc34115a73000f5647b17-1.jpg" alt="" class="wp-image-2397" width="474" height="407"/><figcaption>Salvador Dali:Third Monk</figcaption></figure></div>



<p>Nasıl görmek gerektiğini öğrenmek, bir sanatçının<em> </em>tâbi&nbsp;olduğu eğitimden farklı değildir. Gerçekte sanatçı bu kabiliyeti kazanmaya başkalarından daha hazır bir zihin yapısıyla doğmuş olabilir, ama o da görsel biçimlerle aynı alışkanlığı kurmak zorundadır. Sanatçı daima çalışmalar ve gözlemler yapar. Doldurduğu kroki defterleri, bu pratik çalışmasının delilleridir. Bir elmayı süratli birkaç çizgiyle göstermek, bir üzüm salkımının yapısını bir fırça vuruşuyla belirtmek doğuştan gelen bir özellik değildir."<br></p>



<p>Görmeyi sorgulamayı ve bu dönemde bile görmeye çalışmamızda ilk olarak Antik Yunanda başlamış, zamanla sanatçılar Yunan'ın görme biçiminden etkilenmiş ya da görme biçimine katkı sağlamıştır. Eğer tarihte daha ileriye gidersek, izlenimcilik gibi akımlarda görmeyi farklı bir boyuta taşımış, bize "Gördüğümüz gördüğümüz müdür?" sorusunu sordurmuştur.<br></p>



<p>"İzlenimcilik veya empresyonizm, 19. yüzyılda Fransa’da ortaya çıkan ve bütün sanat dallarını, özellikle resmi etkileyen akım. Doğadaki unsurların kişinin içinde oluşturduğu izlenimleri, duygusal izleri yansıtmayı hedefler. Bu akım içerisinde yer alan sanatçılar, doğayı objektif bir gerçek olarak değil, kendilerinde yarattığı izlenimi resme (veya edebi esere) aktarırlar. İzlenimcilere göre sanatçı doğrudan doğruya gerçeği değil, gördüklerinin kendisinde uyandırdığı duygu ve düşünceleri esas almalı, gerçekçiliği ve nesnelliği ikinci plana atarak, kişisel yorumu ön plana çıkarmalıdır. İzlenimcilikte yorumlar ve izlenimler, sanatçıdan sanatçıya değiştiği ve her sanatçı eserinde kendinde oluşan duyguyu ve izlenimi anlatacağı için, meydana getirilen edebî eser, yazarın veya şairin kişiliğine dair izler taşır. Bu akıma mensup sanatçılar genellikle hayale ve soyut betimlemelere yer verirler ve kendilerini dış dünyanın etkilerinden uzak tutarlar. Onlara göre dış alemdeki varlık ve nesneler göründükleri gibi değil, hayal güçlerinde canlandırdıkları gibidir. Bu sebepten dolayı da gerçeği göründüğü gibi ele almayıp duygusal yönlendirmelerin eşliğinde eserlerine işlemişlerdir."<br></p>



<div class="wp-block-image"><figure class="aligncenter size-large is-resized"><img src="https://i2.wp.com/www.loveinartsz.com/wp-content/uploads/2020/06/weo11yrdjpwngbnyhr4z.jpg?fit=1024%2C826&amp;ssl=1" alt="" class="wp-image-2398" width="518" height="418"/><figcaption> Cezanne: The Rock and Qurry Paintings</figcaption></figure></div>



<p>Şöyle bir şey anladım ki; her zaman soyuta ulaşmak için, somutu tam anlamıyla anlamamız gerektiği, tamamı ile görmeyi öğrenmeden "Ben böyle görüyorum" denmemesi gerektiğini kavramamız gerektiğini anlatmıştır bütün bu akımlar ve sanatçılar… Yani olağanı görürsek, kendi zihnimizde görülenleri de yansıtabiliriz. Bu söylemime en iyi örnekler Picasso’nun eserleri ve çalışmaları; gençlik döneminde yaptığı natürmortlar ve portreler olabilir. Van Gogh’un Yıldızlı Gece'yi yapmadan önce Caravaggio'nun eserlerini kopya etmesi, Michelangelo'nun dikdörtgen bir kütleden Davut'u çıkarması bile olabilir.<br>Bütün sanatçıların ihtiyacı öncelikle görmeyi öğrenmek, aslında gördüğümüzü sandığımız şeyin hiçte öyle olmadığını anlamak, görmek için sadece sanatı değil, bilimi, felsefeyi de okuyup birbirleriyle olan iletişimi anlamak ve iletişimi kurmak, görmeyi "öğrendikten" sonra, kendi zihninde gördüğünü tuvallere döküp, sanatını herkesin farklı bir şekilde görmesini sağlamak ve insanlara "gördüğünü" sorgulatmak olmalıdır. Eğer dünyada tek bir insan olsaydı, gördüğümüz gördüğümüzdür diyebilirdik. Ama dünyada milyarlarca insan var iken ve her insanın zihni farklı çalışırken, sadece kendi gözlerimizle görebildiğimiz bir varlığa "gördüğüm gibidir" diyemeyiz. Ve bu araf; biz bilgiyi aldıkça, bilgeleştikçe, öğrendikçe, gözümüzü açtıkta ilerlemeye devam eder. Bu yüzden, bana göre, gördüğümüz, gördüğümüz değildir.</p>



<p><strong><em>KAYNAKÇA</em></strong></p>



<ol><li>Laura D’Olimpio, The conversation, How do you know you’re not living in a computer simulation?</li><li>Micheal Foucault-Bu Bir Pipo Değildir</li><li>Ders Belgeliği-95-96 Notları</li><li>İzlenimcilik Mark Powell-Jones</li></ol>



