UPDATE posts SET content = $tag2$<p>  Antik Yunan dönemi bilimin, sanatın ve felsefenin çağ atladığı bir dönemdir. Rönesans'ın başlangıcında kendine özendirir. Hala bilim ve sanat deyince akla gelir. Geriye dönüp bakma eğilimimizi en çok arttıran dönemlerden biridir. Bu dönemin sanatçıları kadar o dönemin en önemli bilim insanlarından biri olan Öklid'in ne yaptığına hep birlikte kısaca bakalım!</p>



<div class="wp-block-image"><figure class="aligncenter size-large"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/12/Oklid.jpg" alt="" class="wp-image-5791"/><figcaption><a href="https://www.goodreads.com/photo/author/125792.Euclid">Öklid</a></figcaption></figure></div>



<p>  Öklid, toplam 13 küçük kitaptan oluşan ''Elementler''in ilk kitabında 10 tane aksiyomdan bahsetmektedir. Bu aksiyomların 5'i ortak kanı şeklinde, diğer 5'i de postulatlar olarak nitelendirilmektedir. Öklid, bunlardan yola çıkarak geometrinin diğer önermelerini ispat etmektedir.</p>



<h2>Öklid'in postulatları:</h2>



<p><br>1-Herhangi bir noktadan herhangi başka bir noktaya bir düz doğru çizmek mümkündür.<br>2-Bir tane doğru parçasını her iki yöne de sürekli bir şekilde uzatmak mümkündür.<br>3-Herhangi bir merkez ve herhangi bir yarıçap ile bir çember tanımlamak mümkündür.<br>4-Bütün dik açıların birbirine eşit olduğu doğrudur.<br>5-Eğer iki doğru ile kesişen bir doğru çizilirse, iki doğrunun birbirine bakan tarafında yer alan ve onları kesen doğrunun bir tarafında kalan iki açının toplamı iki dik açıdan küçükse bu iki doğru açıların toplamının iki dik açıdan az olduğu tarafta uzatılmaya devam ederlerse ilerde bir noktada kesişecekleri doğrudur.</p>



<h2>Öklid'in ortak kanıları: </h2>



<p><br>1-Bir şeye eşit olan başka şeyler birbirlerine de eşittirler.<br>2-Eğer eşit miktarlara eşit miktarlar eklenirse elde edilen bütünler de birbirlerine eşittir.<br>3-Eğer eşit miktarlardan eşit miktarlar çıkarılırsa kalanlar da birbirlerine eşittir.<br>4-Birbirleriyle çakışan (özelikleri açısından örtüşen) şeyler birbirlerine eşittir.<br>5-Bütün, parçadan büyüktür.</p>



<p>  Peki nedir bu aksiyom, postulat? Aksiyom, doğru olduğu herkes tarafından kabul edilen önerme olarak geçer ve mantık işlemleri için yeni teorem ve ispatların elde edilmesinde kullanılır. Postulat ise doğruluğu mantıki olarak kabul edildiği halde doğruluğu da yanlışlığı da ispatlanamayan önermedir. </p>



<p>  Düzlem geometrisi, aritmetik, sayılar kuramı, irrasyonel sayılar ve katı cisimler geometrisi Öklid’in kitabında ele aldığı başlıca konulardı. Öklid’in her önermeyi daha önceki önermelerden çıkarma yöntemi, kendisine atfedilen “geometrinin babası” sözünü de haklı kılar. Bu sayılan terimler, sanatta duygularımıza işlemiyor olsa bile o duyguları yansıtmamızda bize çok büyük bir fayda sağlıyor. Eski bilim adamları da sanatçılar da bu buluşlar ve ispatlar sayesinde sanatı duvarlara, tuvallere, kiliselere, hala görüp hayranlıkla izlediğimiz katedrallere işleyebilmişler. Örneğin resmi tuvale, duvara yerleştirme veya kiliselerde duvarlara işleme gibi resmi işlemek istediğimiz birçok alan ve düzlemde yukarıda Öklid'in ispatladığı hemen hemen her şeyi farkında olarak veya olmayarak kullanırız. Ne kadar ayrı gözükseler de bilimin ve bilim insanlarının sanata ve sanatçıya olan katkısını göz ardı edemeyiz. Bilimin ve sanatın hayati oluşu, onların bir arada var olabilmesini sağlar.</p>


