UPDATE posts SET content = $tag2$<p>Barok mimarisinin en görkemli yapılarından biri olan Melk Manastırı, Jakob Prandtuer adlı bir mimar tarafından yapılmış ve bazı gezgin İtalyan virtuosileri (usta sanatçılar) tarafından süslenmiş. Bu muhteşem yapı Avusturya'da, Tuna nehri üzerinde bulunuyor.</p>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://i0.wp.com/www.loveinartsz.com/wp-content/uploads/2020/06/e66df95519f1078caaffcafe42b4dfb5-1.jpg?fit=1024%2C638&amp;ssl=1" alt="" class="wp-image-2420" width="740" height="461"/></figure>



<p>Manastırın büyük bir bölümünde Barok işlemeler ve süslemeler bulunuyor. Kilisenin içinde müthiş bir renk armonisi var ve adeta resimlerin ''sesini'' duyabiliyorsunuz. Karmaşık süslemeler ve altın yaldızlar hem Barok hem de Rokoko esintileri veriyor. Kubbelerin büyüklüğüyle harmanlanan o altın rengi yaldızlar, hem kutsallığın, hem de üslubun görkemini ortaya çıkarır nitelikte. Manastırın içinde aynı zamanda orası ziyaret eden Maria Theresia ve eşi Kaiser Franz Stephan'ın tabloları bulunuyor. Bu jesti(!) bir çok kilisede görebiliriz. Birkaç yazı öncesinde bahsettiğimiz Şansölye Rolin'in, Jan van Eyck'a; bir kiliseye hediye vermek üzere yaptırmış olduğu ve kendisinin de içinde bulunduğu ''kutsanma'' ana temalı resmi gibi. Maria Theresia'da 13 Mayıs 1717- 29 Kasım 1780 yılları arasında yaşamış, Hasburg Hanedanlığı'nın devleti bizzat yöneten tek imparatoriçesi olmuştur. Ayrıca 1740-1780 yılları arasında Macaristan ve Bohemya Kraliçesi ve Avusturya Arşidüşesi olmuştur.<br></p>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://i0.wp.com/www.loveinartsz.com/wp-content/uploads/2020/06/Kaiserin_Maria_Theresia_HRR.jpg?fit=826%2C1024&amp;ssl=1" alt="" class="wp-image-2419" width="616" height="763"/></figure>



<figure class="wp-block-gallery has-nested-images columns-default is-cropped">
<figure class="wp-block-image size-large"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/AustriaPrague-October2013BC-265-2.jpg" alt="" class="wp-image-2423"/></figure>



<figure class="wp-block-image size-large"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/melk-abbey-austria-81-2.jpg" alt="" class="wp-image-2421"/></figure>



<figure class="wp-block-image size-large"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/the-interior-of-the-abbey-chapel-melk-abbey-melk-austria.jpg" alt="" class="wp-image-2425"/></figure>



<figure class="wp-block-image size-large"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/MelkAbbeyInteriorView-2.jpg" alt="" class="wp-image-2424"/></figure>
</figure>



<p>Mekana tekrar gelirsek, E.H Gombrich'in bu konuda ki yorumunu okursak, mekanın önemini daha iyi anlayabiliriz.</p>



<p>''Bernini veya Borromini en coşkun anlarında bile, bu derece ileri gitmemişlerdi. Bir bir Avusturyalı çiftçi için köydeki evinden çıkıp, bu garip harikalar diyarına girmenin ne anlama geldiğini bir kez daha düşünelim. Her yer, bulutlarla dolu. Bulutların üzerinde müzik çalan ve hareketleriyle Cennet'in mutluluğunu gösteren melekler var. Meleklerin bazıları vaz kürsüsünün üzerine yerleşmiş, her şey hareket ediyor, dans ediyor ve görkemli sunağı çevreleyen mimari, bu coşkunun ritminde sallanıyor gibi. Böyle bir kilisenin içinde hiçbir şey ''doğal'' ya da ''normal'' değil- zaten amaçlanan da bu değil. Amaç, Cennet'in ihtişamını önceden göstermek. Belki herkes Cennet'i bu şekilde düşünmüyor, ama bütün bunların ortasında, mekan sizi tamamen içine alıyor ve artık insanın kafasında hiçbir soru kalmıyor.''</p>



<figure class="wp-block-image aligncenter size-large is-resized"><img src="https://i1.wp.com/www.loveinartsz.com/wp-content/uploads/2020/06/46a16d5e752feccd0435ba364babffc5-2-scaled.jpg?fit=1024%2C683&amp;ssl=1" alt="" class="wp-image-2426" width="571" height="380"/></figure>



<p>Kaynakça; E.H. Gombrich, Sanatın Öyküsü</p>$tag2$ WHERE slug = 'tunada-bir-barok-gorkemi-melk-manastiri';
UPDATE posts SET content = $tag2$<div class="wp-block-image"><figure class="aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/Selene_and_Endymion.jpg" alt="" class="wp-image-2546" width="367" height="361"/><figcaption><br></figcaption></figure></div>



<p>Muğla'da Bafa Gölü'nün topraklarındayız. Bir yanda Zeus bir yanda ise Ay Tanrıçası Selene ve Çoban Endymion.</p>



<p>Efsaneye göre Latmos (Beşparmak) dağlarından her gece bir kaval sesi yükselirmiş içli içli... </p>



<p>Derler ki  bu kavalın sahibi bir çobanmış. Bu çobanın adı Endymion'muş. Endymion'un gönlüne Tanrıça Selene'nin aşkı düşmüş. Endymion dağlarda sürüleri otlatır, gün boyunca sahip olduğu tek varlık olan kavalını üflermiş. Geceleri ise otlattığı sürüyü alır, Latmos dağının eteklerinde bir mağaraya çekilirmiş. </p>



<p>Güneş gökyüzünü terk edip ay geceyi aydınlatınca Selene gelirmiş. Selene, boğaların çektiği gümüş bir arabada başında aydan bir taç, elinde meşalesiyle Ay Tanrıçasıymış. Dünyada gezintiye çıkmadan önce Bafa'ya gelir yıkanır ve göğe yükselirmiş. </p>



<p>Selene'nin gelişini izlermiş her gece Edymion ve onun ışıklarla yıkanışını. Endymion zamanla aşık olmuş bu güzel tanrıçaya ve tanrıça da ona. Fakat Selene çok mutsuzmuş çünkü Zeus'un yasalarına göre birlikte olmaları yasakmış. </p>



<div class="wp-block-image"><figure class="aligncenter size-large"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/06/Selene-ve-Endymion-Filippo-Lauri.jpg" alt="" class="wp-image-2547"/></figure></div>



<p>Birbirlerine duydukları aşkla Endymion'un kavalının sesi daha yüksek ve daha anlamlı çıkmaya başlamış Kavalın sesi o kadar gürmüş ki diğer tanrılara kadar ulaşırmış. Onun sesini duyan Selene aşkına karşılık verirmiş. Geceleri sevgilisi uyurken gelir onu ışığıyla sarıp öpermiş.</p>



<p>Onların bu aşkı tanrılar tarafından hoşnutlukla bazende kıskançlıkla izlenirmiş. Tabi Zeus'da izlermiş bu aşkı. Her gün büyüyen ve coşan bu ışıltılı aşk karşısında bir gün Endymion'a bir dilek hakkı sunmuş. </p>



<p>Endymion sevgilisiyle geçirdiği zamanları sonsuz kılabilmek için "sonsuz bir uyku" istemiş.  Zeus, çobanı sonsuz bir uykuya yatırmış sevgilisi onu her gece gelip sarmalasın diye.</p>



<p>İşte o gün bu gündür Bafa gölünden yükselen ay, aşkla dokunur Latmos dağlarına</p>



<div class="wp-block-image"><figure class="aligncenter size-large is-resized"><img src="https://www.loveinartsz.com/wp-content/uploads/2020/07/Rococo-Revisited.jpg" alt="" class="wp-image-2559" width="346" height="562"/></figure></div>



<h3><strong>Bafa Gölü Nerede?</strong></h3>



<p>Söke ovası 2000 yıl kadar önce denizdi, burada büyük bir körfez vardı. Büyük Menderes ırmağının getirdiği alüvyonlar körfezi duldurdu ve ova haline getirdi. Bugünkü Bafa Gölü denizden bir parça olarak arada kaldı. Gölün üzerinde iki ada bulunmaktadır. İkiz adalardan biri aslında tam ada değil, bir kumulla karaya bağlıdır. Bafa Gölü’nde kefal, levrek, yılan balığı tutulmaktadır.&nbsp; Gölde gezmek isterseniz dolmuş usulü motorlara binebilirsiniz. Bu sayede Adalar, Heraklia antik kentini de gezilebilirsiniz. Göldeki adalarda manastırlar, kiliseler kurulmuş. Bunlardan "Yediler Manastırı" en eskisidir. Gölün çevresi zeytinliklerle çevrili. Bu nedenle gölün çevresindeki lokantalar da yapılan yemeklerin hepsi zeytinyağı ile yapılmaktadır.</p>



<figure class="wp-block-gallery columns-2 is-cropped"><ul class="blocks-gallery-grid"><li class="blocks-gallery-item"><figure><img src="https://www.loveinartsz.com/wp-content/uploads/2020/07/4.jpg" alt="" data-id="2571" data-full-url="https://i1.wp.com/www.loveinartsz.com/wp-content/uploads/2020/07/4.jpg?fit=1000%2C667&amp;ssl=1" data-link="https://www.loveinartsz.com/bafa-golu-efsanesi-selene-ve-endymion/4-3/#main" class="wp-image-2571"/></figure></li><li class="blocks-gallery-item"><figure><img src="https://www.loveinartsz.com/wp-content/uploads/2020/07/2.jpg" alt="" data-id="2573" data-full-url="https://i1.wp.com/www.loveinartsz.com/wp-content/uploads/2020/07/2.jpg?fit=961%2C639&amp;ssl=1" data-link="https://www.loveinartsz.com/bafa-golu-efsanesi-selene-ve-endymion/2-7/#main" class="wp-image-2573"/></figure></li><li class="blocks-gallery-item"><figure><img src="https://www.loveinartsz.com/wp-content/uploads/2020/07/3.jpg" alt="" data-id="2574" data-full-url="https://i1.wp.com/www.loveinartsz.com/wp-content/uploads/2020/07/3.jpg?fit=1000%2C664&amp;ssl=1" data-link="https://www.loveinartsz.com/bafa-golu-efsanesi-selene-ve-endymion/3-4/#main" class="wp-image-2574"/></figure></li></ul><figcaption class="blocks-gallery-caption">görsel sahibi: Getty Images</figcaption></figure>



